window.IA = {"lang": "pl", "ui": {"app_title": "ClayArena Interpreter Academy", "tagline": "Strzelectwo do rzutków dla tłumaczy — od zera", "hero_p": "Dwanaście misji, by poznać język Parcours de Chasse – Sporting™ i Compak® Sporting: rzutki i ich tory lotu, strzelbę, wyprzedzenie i technikę strzału, przepisy FITASC, decyzje sędziego i etykietę tego sportu. Potem ćwiczysz jak na prawdziwym stanowisku: tłumaczysz trenera, rozpoznajesz rzutek, znajdujesz wyprzedzenie i podejmujesz decyzję sędziego.", "missions": "Misje", "practice": "Ćwiczenia", "start": "Zacznij", "continue": "Kontynuuj", "lessons_n": "lekcji", "min": "min", "back": "Wstecz", "back_mission": "Do misji", "home": "Strona główna", "key_points": "Najważniejsze", "coach_says": "Trener mówi", "listen": "Posłuchaj", "reveal": "Pokaż znaczenie", "meaning": "Znaczenie", "say_it": "Jak to powiedzieć", "terms": "Terminy", "rules_refs": "W przepisach FITASC", "sources": "Źródła", "quiz": "Sprawdź się", "correct": "Dobrze!", "wrong": "Niezupełnie.", "next": "Dalej", "next_lesson": "Następna lekcja", "finish_lesson": "Lekcja ukończona", "xp": "XP", "level": "Poziom", "levels": ["Nowicjusz", "Słuchacz", "Tłumacz na strzelnicy", "Tłumacz na stanowisku", "Tłumacz zawodowiec"], "done_of": "ukończono", "game_coach": "Przetłumacz trenera", "game_coach_d": "Usłysz zdanie trenera po angielsku i wybierz, co naprawdę znaczy.", "game_flight": "Nazwij tor lotu", "game_flight_d": "Obserwuj lot rzutka i nazwij rodzaj prezentacji.", "game_lead": "Laboratorium wyprzedzenia", "game_lead_d": "Zobacz, jak działa wyprzedzenie w każdej metodzie, a potem sam pociągnij za spust.", "game_call": "Decyzja sędziego", "game_call_d": "Prawdziwe sytuacje na stanowisku: jak rozstrzyga sędzia?", "game_terms": "Karty terminów", "game_terms_d": "Dopasuj angielski termin do słowa, którego używają strzelcy w twoim języku.", "game_exam": "Egzamin końcowy", "game_exam_d": "30 pytań ze wszystkich misji. Zdaj z wynikiem 80% i odbierz certyfikat.", "which_flight": "Jaka to prezentacja?", "which_meaning": "Co ma na myśli trener?", "which_term": "Jak mówią to strzelcy w twoim języku?", "which_def": "Co oznacza ten termin?", "launch": "Wyrzuć", "again": "Jeszcze raz", "score": "Wynik", "play_again": "Zagraj ponownie", "method": "Metoda", "m_maintained": "Stałe wyprzedzenie (maintained lead)", "m_swing": "Przeciągnięcie (swing-through)", "m_pullaway": "Pull-away", "m_ambush": "Zasadzka (ambush)", "speed": "Prędkość rzutka", "distance": "Odległość", "demo": "Zobacz metodę", "try": "Twoja kolej: naciśnij, gdy oddałbyś strzał", "shoot": "Strzał", "hit": "Trafiony! Rzutek pęka.", "behind": "Za rzutkiem — śrut przeszedł za rzutkiem", "ahead": "Przed rzutkiem — śrut przeszedł przed rzutkiem", "perceived": "Wyprzedzenie widziane w chwili decyzji", "actual": "Rzeczywiste wyprzedzenie w chwili strzału", "lab_note": "Zwolnione tempo, uproszczona fizyka do nauki: średnia prędkość śrutu ok. 330 m/s i 0,15 s od decyzji do strzału. Rzeczywiste wyprzedzenie zależy też od strzelca, naboju i kąta.", "exam_pass": "Zdane! Możesz teraz odebrać certyfikat.", "exam_fail": "Jeszcze nie — potrzeba 80%. Powtórz misje i spróbuj ponownie.", "cert_name": "Twoje imię i nazwisko na certyfikacie", "cert_print": "Drukuj lub zapisz jako PDF", "cert_title": "Certyfikat", "cert_text": "ukończył(a) kurs ClayArena Interpreter Academy z terminologii, techniki, przepisów FITASC i etykiety Parcours de Chasse – Sporting™ i Compak® Sporting.", "cert_note": "Certyfikat samodzielnej nauki ClayArena; nie jest kwalifikacją FITASC.", "question": "Pytanie", "of": "z", "term_all": "We wszystkich językach ClayArena", "term_note_anglicism": "Strzelcy często używają po prostu angielskiego słowa.", "confidence_low": "do potwierdzenia", "reset": "Wyzeruj postępy", "reset_confirm": "Usunąć wszystkie postępy i XP na tym urządzeniu?", "saved_local": "Postępy są zapisywane na tym urządzeniu.", "disclaimer": "Kurs ClayArena. Przepisy FITASC przedstawiamy własnymi słowami, z linkami do stron przepisów; wiążący jest wyłącznie oficjalny tekst FITASC. Parcours de Chasse – Sporting™ i Compak® Sporting są znakami towarowymi FITASC.", "language": "Język", "all_missions_done": "Wszystkie misje ukończone — czas na egzamin końcowy!", "decision": "decyzja", "shot_moment": "strzał", "lead_word": "wyprzedzenie", "unit_m": "m", "unit_ft": "ft", "unit_ms": "m/s", "glossary_page": "Strona słownika", "pair_report": "Dublet na zawołanie (on report): drugi rzutek wylatuje na huk pierwszego strzału", "pair_sim": "Dublet symultaniczny: oba rzutki wylatują jednocześnie", "pair_rafale": "Rafale (following pair): drugi rzutek z tej samej wyrzutni zaraz po pierwszym"}, "missions": [{"id": "sport", "icon": "flag", "title": "Ten sport w dziesięć minut", "intro": "Zanim przetłumaczysz pierwszą wskazówkę trenera, potrzebujesz ogólnego obrazu: do czego naprawdę się strzela, kto pisze przepisy, jak wygląda parcours Parcours de Chasse – Sporting™ i pole Compak® Sporting oraz jak przebiega dzień zawodów. Pięć krótkich lekcji daje ci mapę; każda kolejna misja uzupełnia szczegóły.", "lessons": [{"id": "sport-what-is-clay", "minutes": 5, "title": "Rzutki, nie ptaki: czym jest ten sport", "body": ["Strzelectwo do rzutków to sport, w którym strzelec rozbija ze strzelby małe lecące krążki. Krążek nazywa się rzutkiem (target, clay); strzelcy często mówią na niego „bird” (ptak), ale nikt nie strzela do żywych zwierząt. Przepisy FITASC mówią jasno, że strzelanie do żywych zwierząt jest niedozwolone, a bezpieczeństwo i troska o środowisko są na pierwszym miejscu.", "Każdy rzutek wyrzuca maszyna zwana wyrzutnią (trap). Jego droga w powietrzu (lub po ziemi) to trajektoria, czyli tor lotu. Broń to strzelba gładkolufowa: wystrzeliwuje nabój pełen małych śrucin, czyli śrut, który rozchodzi się w niewielką chmurę. Dlatego strzelec kieruje broń tam, dokąd rzutek leci, a nie tam, gdzie jest teraz.", "Ten kurs dotyczy dwóch dyscyplin międzynarodowej federacji FITASC. Parcours de Chasse – Sporting™ (w skrócie Sporting™) naśladuje polowanie: wyrzutnie są ukryte na polach i w lasach, a rzutki lecą jak kuropatwa, kaczka czy bażant albo toczą się jak zając. Compak® Sporting to wersja zwarta: ta sama różnorodność rzutków, ale na jednym małym polu z pięcioma stanowiskami w linii i sześcioma wyrzutniami.", "Usłyszysz też o trapie i skeecie. To inne dyscypliny ze stałymi, powtarzalnymi torami lotu; olimpijski trap i skeet należą do innej federacji. Nie mieszaj ich przepisów ze Sporting™ ani z Compak® Sporting.", "Trafienie widać od razu: rzutek pęka albo odpada od niego przynajmniej widoczny kawałek. Ta jasność sprawia, że sport łatwo się ogląda, a tobie łatwo go śledzić od pierwszego dnia."], "key_points": ["Strzela się do rzutków wyrzucanych przez wyrzutnie, nigdy do żywych zwierząt.", "Strzelba wystrzeliwuje chmurę małych śrucin (śrut), więc strzelec kieruje broń przed rzutek.", "Sporting™ naśladuje polowanie w naturalnym terenie; Compak® Sporting to jego zwarta wersja na jednym polu.", "Trap i skeet to inne dyscypliny z własnymi przepisami."], "terms": ["target", "trap", "trajectory", "shotgun", "cartridge", "sporting", "compak-sporting"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Clay pigeon shooting", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch1-definition", "label": "1 · What Sporting is"}, {"book": "sporting", "id": "ch1-safety-environment", "label": "1 · Safety, environment and no live animals"}, {"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak Sporting is"}], "coach_says": [{"en": "Watch this bird off trap B.", "meaning": "„Bird” to rzutek, a nie prawdziwy ptak; wyrzutnia B to maszyna oznaczona literą B.", "say": "Obejrzyj ten rzutek z wyrzutni B."}, {"en": "Today we walk the Sporting course, tomorrow it's Compak.", "meaning": "Dwie różne dyscypliny w dwa różne dni.", "say": "Dziś idziemy na parcours Sporting, jutro Compak."}, {"en": "Point it, don't aim it.", "meaning": "Strzelbę się prowadzi i kieruje, z oboma oczami na rzutku, a nie celuje jak z karabinu.", "say": "Wskazuj, nie celuj."}], "quiz": [{"q": "Trener mówi „Watch the next bird.” Co zobaczysz?", "options": ["Żywego gołębia wypuszczonego ze skrzynki", "Rzutek wyrzucony przez wyrzutnię", "Papierową tarczę w kształcie ptaka na tablicy", "Drona"], "answer": 1, "why": "„Bird” to w żargonie strzelców rzutek; przepisy FITASC zabraniają strzelania do żywych zwierząt."}, {"q": "Co wystrzeliwuje strzelba?", "options": ["Jeden pocisk", "Małą strzałkę", "Chmurę małych śrucin (śrut)", "Kulkę z farbą"], "answer": 2, "why": "Śrut wylatuje z lufy jako niewielka chmura śrucin, więc strzelec kieruje broń przed lecący rzutek."}, {"q": "Które stwierdzenie o Compak® Sporting jest prawdziwe?", "options": ["To wersja zwarta na jednym polu, ze stanowiskami w linii", "To olimpijska wersja skeetu", "Strzela się tylko do żywego ptactwa w terenie", "Używa jednej wyrzutni i jednego stanowiska"], "answer": 0, "why": "Compak® Sporting przenosi rzutki w stylu Sporting™ na jedno małe pole z pięcioma stanowiskami i sześcioma wyrzutniami."}]}, {"id": "sport-fitasc", "minutes": 5, "title": "FITASC, federacje i ClayArena", "body": ["FITASC to międzynarodowa federacja strzelectwa do rzutków w stylu myśliwskim. Pisze i aktualizuje przepisy Parcours de Chasse – Sporting™ i Compak® Sporting; wydania, którymi się kierujemy, są datowane na 01/01/2025. Compak® Sporting jest też znakiem towarowym chronionym przez FITASC, dlatego nazwę zawsze pisze się z ®.", "Sport jest zbudowany jak piramida. Na dole są kluby i strzelnice, nad nimi federacje krajowe, a federacje krajowe są członkami FITASC. Osie na zawody krajowe zatwierdza federacja krajowa, a na zawody międzynarodowe FITASC. Federacja może powierzyć organizację zawodów klubowi, ale nadal odpowiada za stosowanie przepisów.", "Na strzelnicy przepisy stosują sędziowie. Każdy sędzia ma certyfikat federacji krajowej, a sędzia główny potrzebuje międzynarodowego certyfikatu FITASC. Jury zajmuje się protestami, karami i problemami technicznymi na zawodach międzynarodowych. Będziesz tłumaczyć dla nich wszystkich, więc naucz się tytułów: sędzia, sędzia główny, jury.", "Istnieją też inne organizacje. W Wielkiej Brytanii i USA krajowe stowarzyszenia prowadzą własne odmiany tego sportu, takie jak angielski Sporting, z innymi przepisami i słowami. Brytyjski lub amerykański trener może używać tych słów na zawodach FITASC; kolejne misje pokażą ci, jak sobie z tym radzić.", "ClayArena to platforma, która stoi za tym kursem. Publikuje kalendarze zawodów, słownik i streszczenie przepisów FITASC prostym językiem, a poprzez ClayAway organizuje wyjazdy treningowe. Pamiętaj: wiążący jest wyłącznie oficjalny tekst FITASC; streszczenie to przewodnik, a nie sam przepis."], "key_points": ["FITASC pisze przepisy Sporting™ i Compak® Sporting (wydania z 01/01/2025).", "Klub, federacja krajowa, FITASC: osie krajowe zatwierdza federacja, międzynarodowe FITASC.", "Sędziowie mają certyfikaty krajowe; sędzia główny międzynarodowy certyfikat FITASC; jury rozpatruje protesty.", "Wiążący jest wyłącznie oficjalny tekst FITASC; ClayArena oferuje streszczenie."], "terms": ["fitasc", "national-federation", "referee", "chief-referee", "jury"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak Sporting is"}, {"book": "sporting", "id": "ch15-layout-approval", "label": "15 · Who approves layouts"}, {"book": "sporting", "id": "ch15-delegation", "label": "15 · Delegating to a club"}, {"book": "sporting", "id": "ch5-referee-certificate", "label": "5 · Referee certificates"}, {"book": "sporting", "id": "ch15-jury-role", "label": "15 · Duties of the jury"}, {"book": "compak", "id": "ch19-referee-qualification", "label": "19 · Referee approval and qualifications"}], "coach_says": [{"en": "That's a CPSA term — under FITASC it's a simultaneous double.", "meaning": "Trener przechodzi ze słownictwa brytyjskiego na nazwę FITASC.", "say": "To termin CPSA — według FITASC to dublet symultaniczny."}, {"en": "Ask the chief referee, not the stand referee.", "meaning": "Pytanie jest do najwyższego rangą sędziego zawodów.", "say": "Zapytaj sędziego głównego, nie sędziego na stanowisku."}, {"en": "The jury will decide this one.", "meaning": "Sprawa wykracza poza sędziego stanowiska i trafia do jury zawodów.", "say": "W tej sprawie zdecyduje jury."}], "quiz": [{"q": "Kto zatwierdza osie na międzynarodowe zawody Sporting™?", "options": ["Miejscowy klub", "Federacja krajowa", "Sędzia w dniu zawodów", "FITASC"], "answer": 3, "why": "Osie krajowe zatwierdza federacja krajowa, a międzynarodowe FITASC."}, {"q": "Jaki certyfikat musi mieć sędzia główny?", "options": ["Międzynarodowy certyfikat FITASC", "Tylko legitymację członka klubu", "Krajową licencję trenerską z klubu", "Żadnego: może nim być każdy doświadczony strzelec"], "answer": 0, "why": "Sędziowie na stanowiskach potrzebują certyfikatu krajowego; sędzia główny międzynarodowego certyfikatu FITASC."}, {"q": "Klient w trakcie sporu pokazuje ci streszczenie przepisów ClayArena. Jaki ma ono status?", "options": ["Ma pierwszeństwo przed oficjalnym tekstem FITASC", "To tylko przewodnik; wiążący jest tekst FITASC", "Jest wiążące, ale tylko w Compak® Sporting", "Zastępuje decyzję sędziego na stanowisku"], "answer": 1, "why": "Streszczenie pomaga zrozumieć przepisy, ale sędzia i jury stosują oficjalny tekst FITASC."}]}, {"id": "sport-sporting-layout", "minutes": 5, "title": "Parcours Sporting™: osie, stanowiska i wyrzutnie", "body": ["W Parcours de Chasse – Sporting™ teren jest podzielony na osie (layouts). Oś to grupa stanowisk strzeleckich, które razem dają 25 rzutków: 15 pojedynczych i 5 dubletów. Zależnie od systemu oś ma trzy, cztery lub pięć stanowisk, każde z własnymi wyrzutniami.", "Stanowisko strzeleckie (shooting stand) to miejsce, w którym stoi strzelec: kwadrat 1 m albo koło o średnicy 1 m, równe i nieśliskie. Uważaj na angielskie „stand”: tłumacz je jako „stanowisko”, a nie „stoisko” czy „trybuna”, i nie myl go z całą strzelnicą. Reszta grupy czeka w pobliżu, na tyle blisko, by śledzić strzelanie, ale nigdy nie rozpraszając strzelca.", "Wyrzutnie rozmieszcza się zgodnie z ukształtowaniem terenu, często częściowo ukryte za krzakami lub drzewami, tak by rzutki wyglądały jak prawdziwa zwierzyna: poprzeczne, nadlatujące, odlatujące, skośne, wysokie lub niskie, na otwartej przestrzeni lub między drzewami. Wyrzutnie stanowiska oznacza się literami A, B, C, D, czytanymi od lewej do prawej, tak jak widać je ze stanowiska.", "Przed każdym stanowiskiem jest menu rzutków: wymienia wyrzutnie w kolejności strzelania i pokazuje rzutki specjalne, np. rzutek 90 mm, 70 mm lub 60 mm, battue albo rabbit. Strzelec czyta je przed wejściem na stanowisko — i ty też powinieneś.", "Tory lotu klasyfikuje się według trudności. Klasę A przeciętny strzelec rozbija w ponad 80% przypadków, klasę B w 60–80%, klasę C w 40–60%. Rzutek klasy C ma więc być trudny; pudło na nim to żadna katastrofa."], "key_points": ["Oś daje 25 rzutków: 15 pojedynczych i 5 dubletów.", "Stanowisko to kwadrat 1 m lub koło 1 m; tłumacz „stand” jako „stanowisko”, nie „stoisko”.", "Wyrzutnie oznacza się literami A, B, C, D od lewej do prawej, tak jak widać je ze stanowiska.", "Menu rzutków pokazuje kolejność wyrzutni i rzutki specjalne.", "Klasy trudności: A ponad 80%, B 60–80%, C 40–60%."], "terms": ["layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "difficulty-class"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}], "coach_says": [{"en": "Layout three is the hard one today — lots of minis in the trees.", "meaning": "Na trzeciej osi jest wiele małych rzutków lecących między drzewami.", "say": "Trzecia oś jest dziś trudna — dużo mini między drzewami."}, {"en": "On this stand, read the menu before you step in.", "meaning": "Najpierw sprawdź kolejność wyrzutni i rzutki specjalne.", "say": "Na tym stanowisku przeczytaj menu, zanim wejdziesz."}, {"en": "Stand two is a class C target, don't worry about it.", "meaning": "Rzutek jest sklasyfikowany jako trudny; pudło jest wkalkulowane.", "say": "Na stanowisku drugim jest rzutek klasy C, nie przejmuj się nim."}], "quiz": [{"q": "Ile rzutków daje jedna oś Sporting™?", "options": ["10", "20", "25", "50"], "answer": 2, "why": "Każdy typ osi daje 25 rzutków: 15 pojedynczych i 5 dubletów."}, {"q": "Trener mówi „Go to stand two.” Jak przetłumaczysz „stand”?", "options": ["„strzelnica” (cały obiekt)", "„stanowisko”", "„trybuna”", "„stojak na broń”"], "answer": 1, "why": "W Sporting™ stand to stanowisko strzeleckie 1 m; nie jest to cała strzelnica ani trybuna."}, {"q": "Jak oznacza się wyrzutnie stanowiska Sporting™?", "options": ["Numerami od 1 do 6, licząc od prawej", "Kolorami namalowanymi na każdej maszynie", "Literami A, B, C, D od lewej do prawej", "Imieniem osoby, która je zwalnia"], "answer": 2, "why": "Litery A, B, C, D czyta się od lewej do prawej, tak jak widać je ze stanowiska, i używają ich menu oraz karta wyników."}]}, {"id": "sport-compak-layout", "minutes": 5, "title": "Pole Compak® Sporting: pięć stanowisk, sześć wyrzutni", "body": ["Compak® Sporting mieści się na jednym polu. Przed strzelcami jest obowiązkowy prostokąt o szerokości 35–40 m i głębokości 25 m, wyznaczony czterema narożnymi palikami z flagami. Przy bezwietrznej pogodzie każdy rzutek musi w którymś momencie nad nim przelecieć.", "Pięć stanowisk strzeleckich, każde to kwadrat 1 m, stoi w linii w odstępach 2–5 m między środkami. Są ponumerowane od 1 do 5 od lewej do prawej. Każde stanowisko ma ogranicznik kąta strzału (Firing Angle Limiter) — ramę z rur, która nie pozwala przenieść broni zbyt daleko w bok lub w górę i nie pozwala strzelcowi zrobić kroku do przodu.", "Sześć wyrzutni, od A do F od lewej do prawej, ma każda tablicę ze swoją literą. Mogą stać z przodu, po bokach, za strzelcami albo na wieży; wyrzutnia za linią stanowisk musi być co najmniej 4 m nad nią. Każdy Compak ma trzy obowiązkowe rzutki: poprzeczny z lewej na prawą, poprzeczny z prawej na lewą i odlatujący.", "Seria to 25 rzutków, po pięć na każdym stanowisku. Gdy strzela grupa sześciu osób, pięciu strzelców stoi na stanowiskach, a szósty czeka za stanowiskiem 1. Każdy strzelec po kolei strzela pięć rzutków z menu stanowiska, zaczynając od stanowiska 1. Gdy stanowisko 5 skończy, ten strzelec idzie czekać za stanowiskiem 1, wszyscy pozostali przesuwają się o jedno stanowisko w prawo, a czekający strzelec wchodzi na stanowisko 1.", "Na niektórych zawodach Compak® Sporting strzela się zamiast tego in line: każdy strzelec zaczyna na stanowisku 1, a kończy na stanowisku 5. Zapytaj organizatora, jaki system obowiązuje, bo procedura jest inna."], "key_points": ["Prostokąt 35–40 m × 25 m, nad którym musi przelecieć każdy rzutek.", "Pięć stanowisk 1 m w linii, co 2–5 m, każde z ogranicznikiem kąta strzału.", "Sześć wyrzutni oznaczonych od A do F od lewej do prawej; wyrzutnia za linią stoi na wieży o wysokości co najmniej 4 m.", "25 rzutków na serię, pięć na stanowisko; grupa przesuwa się o jedno stanowisko w prawo.", "Compak® Sporting można strzelać w grupach albo in line."], "terms": ["fly-over-rectangle", "firing-angle-limiter", "shooting-stand", "trap", "tower", "rotation", "waiting-position", "line"], "sources": [{"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Everybody move one to the right. Number five, to the waiting position.", "meaning": "Grupa się przesuwa; strzelec ze stanowiska 5 idzie za stanowisko 1.", "say": "Wszyscy o jedno w prawo. Piątka na miejsce oczekiwania."}, {"en": "Trap E is the tower — it comes over your head.", "meaning": "Rzutek z wyrzutni E jest wyrzucany z wysokiej wieży i przelatuje nad głową.", "say": "Wyrzutnia E to wieża — leci ci nad głową."}, {"en": "Mind the frame — don't swing past the post.", "meaning": "Respektuj ogranicznik kąta strzału; nie przenoś broni poza niego.", "say": "Uważaj na ramę — nie wychodź bronią za słupek."}], "quiz": [{"q": "Ile wyrzutni i stanowisk ma jedno pole Compak® Sporting?", "options": ["4 wyrzutnie, 3 stanowiska", "6 wyrzutni, 5 stanowisk", "5 wyrzutni, 6 stanowisk", "8 wyrzutni, 8 stanowisk"], "answer": 1, "why": "Wyrzutnie od A do F i stanowiska od 1 do 5."}, {"q": "Gdzie w grupie sześciu osób jest szósty strzelec, gdy pozostali strzelają?", "options": ["W budynku klubowym", "Obok sędziego przy stanowisku 5", "Za wyrzutnią F", "Czeka za stanowiskiem 1"], "answer": 3, "why": "Czekający strzelec stoi za stanowiskiem 1 i wchodzi na nie po każdej zmianie."}, {"q": "Do czego służy ogranicznik kąta strzału (Firing Angle Limiter)?", "options": ["Ogranicza ruch broni i nie pozwala zrobić kroku do przodu", "Mierzy prędkość każdego wyrzuconego rzutka", "Przechowuje naboje na całą serię", "Zwalnia rzutki na komendę strzelca"], "answer": 0, "why": "To rama bezpieczeństwa na każdym stanowisku, ograniczająca ruch broni w bok i w pionie."}]}, {"id": "sport-competition-day", "minutes": 5, "title": "Dzień zawodów od początku do końca", "body": ["Dzień zaczyna się od rejestracji: strzelec potwierdza zgłoszenie, otrzymuje numer startowy i przypina go na górze pleców, w pełni widoczny. Potem wszyscy sprawdzają listy grup i godziny strzelania. Przestrzeganie harmonogramu to obowiązek samego strzelca.", "Grupa (squad) to maksymalnie sześciu strzelców, wylosowanych do wspólnego strzelania. W ClayAway to słowo oznacza też podgrupę w ramach wyjazdu, więc wyjaśnij, o które znaczenie chodzi. W Parcours de Chasse – Sporting™ grupa strzela najpierw wszystkie rzutki pojedyncze stanowiska, potem dublety, a kolejność strzelania zmienia się od stanowiska do stanowiska. Pierwszy strzelec grupy ogląda pokaz rzutków, zanim ktokolwiek strzeli.", "Seria to 25 rzutków: jedna oś w Sporting™, jedno pole w Compak® Sporting. Zawody międzynarodowe to 200 rzutków, czyli osiem serii w ciągu kilku dni. Sędzia zaznacza każdy rzutek na karcie wyników, zwykle X za trafienie i O za pudło. W Sporting™ strzelcy sprawdzają wynik, schodząc ze stanowiska, a w Compak® Sporting podpisują kartę na koniec serii.", "Spóźnienie drogo kosztuje. W Sporting™ sędzia wywołuje nazwisko trzy razy w ciągu jednej minuty; strzelec, który przegapi swoją kolej, dostaje zera za niestrzelane rzutki. W Compak® Sporting strzelec, który przyjdzie po tym, jak pierwszy strzelec grupy zawołał rzutek, dostaje 25 zer w serii.", "Jeśli strzelcy remisują o pierwsze trzy miejsca, jest dogrywka (shoot-off): 25 rzutków, potem nagła śmierć (sudden death). Niższe remisy rozstrzyga się metodą countback, porównując najpierw ostatnią serię. Dzień kończy się tablicą wyników i dekoracją."], "key_points": ["Rejestracja, numer startowy na plecach, listy grup i godziny.", "Grupa to do sześciu wylosowanych strzelców; w Sporting™ najpierw pojedyncze, potem dublety, ze zmienną kolejnością.", "Seria to 25 rzutków; zawody międzynarodowe to 200 rzutków.", "Spóźnienie kosztuje zera; w Compak® Sporting 25 zer w serii.", "Remisy o pierwszą trójkę: dogrywka na 25, potem nagła śmierć; niższe remisy: countback."], "terms": ["entry", "competitor-number", "squad", "round", "rotation", "score-sheet", "shoot-off", "countback", "prize-giving"], "sources": [{"title": "Let's Go Shooting — NSCA beginner's guide to sporting clays", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}], "coach_says": [{"en": "You're in squad twelve, starting on layout five at nine-thirty.", "meaning": "Numer grupy, oś startowa i godzina startu.", "say": "Jesteś w grupie dwunastej, start na osi piątej o dziewiątej trzydzieści."}, {"en": "Check your card before you leave the stand.", "meaning": "Upewnij się teraz, że sędzia poprawnie zapisał twój wynik; później będzie za późno.", "say": "Sprawdź kartę, zanim zejdziesz ze stanowiska."}, {"en": "Twenty-two in the first round is fine — seven more to go.", "meaning": "22 na 25 w pierwszej serii; w zawodach na 200 rzutków zostało siedem serii.", "say": "Dwadzieścia dwa w pierwszej serii to dobrze — jeszcze siedem."}, {"en": "Stay close — if it's a tie, you shoot within fifteen minutes of the call.", "meaning": "Strzelec, który może trafić do dogrywki, musi być gotowy wkrótce po wezwaniu.", "say": "Zostań w pobliżu — jeśli będzie remis, strzelasz w ciągu piętnastu minut od wezwania."}], "quiz": [{"q": "Ile rzutków mają międzynarodowe zawody FITASC?", "options": ["50", "100", "150", "200"], "answer": 3, "why": "200 rzutków w seriach po 25."}, {"q": "W Compak® Sporting w grupach strzelec przychodzi po tym, jak pierwszy strzelec zawołał pierwszy rzutek. Co się dzieje?", "options": ["Nic, dołącza", "Dostaje 25 zer w tej serii", "Strzela serię później sam, bez kary", "Traci jeden rzutek"], "answer": 1, "why": "W Compak® Sporting w grupach spóźnienie po pierwszej komendzie liczy się jako 25 zer; z uzasadnionego powodu możliwe jest odwołanie do jury."}, {"q": "Dwóch strzelców remisuje o 5. miejsce. Jak się ich rozdziela?", "options": ["Dogrywką na 25 rzutków", "Losowaniem po zawodach", "Metodą countback od ostatniej serii", "Według wieku, młodszy pierwszy"], "answer": 2, "why": "Dogrywki są tylko o pierwszą trójkę; poniżej countback porównuje 8. serię, potem 7. i tak dalej."}]}]}, {"id": "gear", "icon": "tool", "title": "Broń i wyposażenie", "intro": "Trenerzy mówią o broni przez cały dzień: „raise the comb”, „check your selector”, „change chokes”, „nines in the bottom”. Ta misja daje ci słowa na broń, jej części, czoki, naboje i środki ochrony, a także kilka przepisów o wyposażeniu, które musi znać każdy tłumacz.", "lessons": [{"id": "gear-gun-types", "minutes": 5, "title": "Rodzaje strzelb i co dopuszczają przepisy", "body": ["Każda broń, którą zobaczysz na stanowisku, to strzelba gładkolufowa. Na niemal każdym stanowisku zawodów jest to bok (over-and-under, O/U; formalnie nadlufka): dwie lufy jedna nad drugą, otwierane przez „złamanie” broni na zawiasie. Każda lufa może mieć własny czok (choke), co ma znaczenie przy dubletach.", "Dubeltówka (side-by-side) ma dwie lufy obok siebie. To klasyczna broń myśliwska i jest dozwolona, ale na zawodach widuje się ją rzadko. Nie tłumacz over-and-under po prostu jako „dwururka”: to słowo obejmuje oba typy.", "Półautomat (semi-automatic; prawnie broń samopowtarzalna) ma jedną lufę i sam się przeładowuje po każdym strzale, wyrzucając pustą łuskę w bok. FITASC go dopuszcza, pod warunkami: najwyżej dwa naboje w broni, zamek otwarty zawsze, gdy broń jest noszona, a w Compak® Sporting urządzenie, które nie pozwala wyrzucanym łuskom trafiać w sąsiada.", "Strzelby z przeładowaniem ślizgowym (pompki, pump-action), przeładowywane ręcznym przesunięciem czółenka, są niedozwolone w Parcours de Chasse – Sporting™ i w Compak® Sporting. Przepisy po prostu podają zakaz bez uzasadnienia, więc nie wymyślaj go, gdy klient zapyta; powiedz tylko, że taki jest przepis. Compak® Sporting zakazuje też dryling, czyli broni łączącej lufy gładkie i gwintowane.", "W obu dyscyplinach obowiązują jeszcze dwa ograniczenia: kaliber nie może być większy niż 12 (więc kaliber 20 jest w porządku), a lufy muszą mieć co najmniej 66 cm długości. Pasy nośne, kamery montowane na broni i wszelkie sztuczne przyrządy celownicze są zabronione."], "key_points": ["Większość zawodników strzela z boku (over-and-under).", "Półautomaty są dozwolone: najwyżej dwa naboje, zamek otwarty przy noszeniu, łapacz łusek w Compak® Sporting.", "Pompki są zakazane w obu dyscyplinach; przepisy nie podają powodu.", "Kaliber nie większy niż 12, lufy co najmniej 66 cm, bez pasów nośnych i przyrządów celowniczych."], "terms": ["shotgun", "over-and-under", "side-by-side", "semi-automatic", "pump-action", "gauge", "barrel-length", "shell-catcher"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-semi-auto", "label": "18 · Semi-automatics: shell catcher and two cartridges"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}], "coach_says": [{"en": "Bring your over-and-under and a spare set of chokes.", "meaning": "Dwulufowa strzelba do zawodów plus zapasowe czoki.", "say": "Weź swojego boka i zapasowy komplet czoków."}, {"en": "With a semi-auto, keep the bolt open until you're on the stand.", "meaning": "Zasada bezpieczeństwa: półautomat nosi się z otwartym zamkiem.", "say": "Z półautomatem trzymaj zamek otwarty, dopóki nie staniesz na stanowisku."}, {"en": "No pumps on this ground.", "meaning": "Strzelby typu pump-action nie są dopuszczone.", "say": "Na tej strzelnicy żadnych pompek."}], "quiz": [{"q": "Która broń NIE jest dozwolona w FITASC Sporting™ i Compak® Sporting?", "options": ["Bok kalibru 20", "Dubeltówka", "Pompka (pump-action)", "Półautomat z dwoma nabojami"], "answer": 2, "why": "Pompki są zakazane; pozostałe są dozwolone, jeśli spełniają wymagania co do kalibru i długości luf."}, {"q": "Ile nabojów może mieć półautomat?", "options": ["Jeden", "Dwa", "Trzy", "Tyle, ile mieści magazynek"], "answer": 1, "why": "Przepisy obu dyscyplin ograniczają półautomat do dwóch nabojów."}, {"q": "Klient pyta, dlaczego pompki są zakazane. Jaka jest uczciwa odpowiedź?", "options": ["Przepisy podają zakaz, nie wyjaśniając go", "Przepisy mówią, że są za wolne do dubletów", "Przepisy mówią, że są mniej bezpieczne", "W rzeczywistości są dozwolone w Compak® Sporting"], "answer": 0, "why": "Przepisy nie podają powodu; jako tłumacz przekaż przepis i nie wymyślaj wyjaśnień."}]}, {"id": "gear-gun-parts", "minutes": 5, "title": "Części broni, od ramienia do wylotu lufy", "body": ["Trenerzy cały czas nazywają części broni, więc poznaj je od tyłu do przodu. Kolba (stock) opiera się o ramię. Jej górna krawędź, na której spoczywa policzek, to grzbiet kolby (comb; z regulacją — baka); „raise the comb” lub „drop the comb” dotyczy dopasowania strzelby. Wąska część trzymana ręką spustową to chwyt pistoletowy (grip, szyjka kolby), a gumowa nakładka na końcu to stopka (recoil pad).", "Metalowy środek broni to baskila (receiver, action). Na górze jest dźwignia otwierająca (top lever): przesuń ją w bok, a broń się otworzy. Za nią jest bezpiecznik (safety catch), często połączony z selektorem luf (barrel selector, „selector”), który decyduje, z której lufy pada pierwszy strzał. Pod spodem jest spust (trigger) w kabłąku.", "Spust zwalniany (release trigger) strzela w chwili puszczenia, a nie naciśnięcia. Broń z takim spustem musi mieć jako ostrzeżenie naklejkę z dużą literą „R” na fluorescencyjnym tle na zewnętrznej stronie kolby.", "Pod lufami druga ręka trzyma czółenko (fore-end). Lufy (barrels) mają z tyłu komory nabojowe na naboje, a z przodu wyloty (muzzles), w które wkręca się czoki. Wzdłuż góry biegnie szyna celownicza (rib) z muszką (bead) na końcu. Muszka to punkt odniesienia, a nie przyrząd celowniczy: „look at the target, not the bead” — patrz na rzutek, nie na muszkę.", "Dwa fałszywi przyjaciele: rib to nie „żebro”, a „break the gun” znaczy otworzyć (złamać) broń, a nie ją uszkodzić. I jedna zasada bezpieczeństwa związana z częściami: po niewypale lub innej awarii broni albo amunicji strzelec nie może otwierać broni ani dotykać bezpiecznika, dopóki sędzia jej nie obejrzy."], "key_points": ["Kolba, grzbiet kolby, chwyt, stopka; baskila z dźwignią otwierającą, bezpiecznikiem i selektorem; spust.", "Czółenko, lufy z komorami i wylotami, szyna z muszką.", "Spust zwalniany wymaga naklejki „R” na kolbie.", "Rib ≠ „żebro”; break the gun = otworzyć (złamać) broń.", "Po niewypale: nie otwieraj broni ani nie dotykaj bezpiecznika, zanim sędzia sprawdzi."], "terms": ["stock", "comb", "grip", "recoil-pad", "receiver", "top-lever", "safety-catch", "barrel-selector", "trigger", "release-trigger", "fore-end", "barrel", "chamber", "muzzle", "rib", "bead"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-release-trigger-marking", "label": "7 · Release trigger: mandatory 'R' sticker"}, {"book": "compak", "id": "ch18-release-trigger-marking", "label": "18 · Release trigger: the 'R' sticker"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}], "coach_says": [{"en": "You're seeing too much rib — your head is up.", "meaning": "Oko jest zbyt wysoko nad szyną, zwykle dlatego, że głowa unosi się z grzbietu kolby.", "say": "Widzisz za dużo szyny — masz podniesioną głowę."}, {"en": "Check your selector — you fired the top barrel first.", "meaning": "Selektor luf jest ustawiony odwrotnie.", "say": "Sprawdź selektor — pierwszy strzał poszedł z górnej lufy."}, {"en": "Break your gun and show me it's clear.", "meaning": "Otwórz broń i pokaż puste komory.", "say": "Złam broń i pokaż mi, że jest pusta."}, {"en": "Forget the bead — look at the target.", "meaning": "Skup się na rzutku, nie na końcu lufy.", "say": "Zapomnij o muszce — patrz na rzutek."}], "quiz": [{"q": "Trener mówi „Raise the comb”. O którą część mu chodzi?", "options": ["Górną krawędź kolby, na której spoczywa policzek", "Małą muszkę na końcu szyny", "Kabłąk wokół spustu", "Czok w wylocie lufy"], "answer": 0, "why": "Comb to grzbiet kolby; jego podniesienie unosi oko nad szyną."}, {"q": "Co musi mieć broń ze spustem zwalnianym?", "options": ["Lufę pomalowaną na czerwono jako ostrzeżenie", "Dużą naklejkę „R” na kolbie", "Drugi, oddzielny bezpiecznik", "Nic: oznaczenie nie jest wymagane"], "answer": 1, "why": "Przepisy obu dyscyplin wymagają ostrzegawczej naklejki „R” na fluorescencyjnym tle po zewnętrznej stronie kolby."}, {"q": "Jak przetłumaczysz „Break your gun”?", "options": ["„Zepsuj broń”", "„Rozłóż broń na części”", "„Otwórz (złam) broń”", "„Wyczyść lufy”"], "answer": 2, "why": "Na strzelnicy „break” oznacza otwarcie broni na zawiasie, żeby nie mogła wystrzelić."}]}, {"id": "gear-chokes", "minutes": 5, "title": "Czoki: co robią i jak mówią o nich trenerzy", "body": ["Czok (choke, zwężenie wylotowe) to niewielkie zwężenie lufy przy wylocie. Decyduje o tym, jak szybko rozchodzi się śrut. Większe zwężenie dłużej utrzymuje śrut razem i daje ciaśniejszy rozrzut na dalekie rzutki; mniejsze rozprasza go wcześniej i daje szerszy, bardziej wybaczający rozrzut na bliskie rzutki.", "Większość broni do zawodów ma czoki wymienne (multichoke): krótkie tulejki wkręcane w wylot lufy kluczem do czoków. Starsza broń może mieć czoki stałe, wykonane w lufie. Tulejki różnych producentów często do siebie nie pasują, a producenci ostrzegają, by nigdy nie strzelać z broni z czokami wymiennymi bez wkręconych tulejek.", "Nazwy pochodzą z angielskiego, od najbardziej otwartego do najciaśniejszego: cylinder, skeet, improved cylinder, light modified, modified, improved modified, full. Europejczycy często podają je jako ułamki: ćwierć (1/4, ćwierćczok = improved cylinder), pół (1/2, półczok = modified), trzy czwarte (3/4 = improved modified) i pełny (full). Wiele włoskich strzelb oznacza czoki gwiazdkami i tam zasada jest odwrotna: więcej gwiazdek oznacza bardziej otwarty czok.", "Trenerzy mówią na przykład „quarter and half”, „open up the bottom barrel”, „go tighter in the top” albo „change chokes for this stand”. Zachowaj nazwy dokładnie tak, jak mówi trener; nie przeliczaj ich na milimetry, które różnią się u różnych producentów.", "Przepisy różnią się między dyscyplinami. W Parcours de Chasse – Sporting™ czoki można zmieniać między stanowiskami albo między rzutkami pojedynczymi a dubletami, jeśli nie powoduje to opóźnienia, ale nigdy po wejściu strzelca na stanowisko. W Compak® Sporting w trakcie serii w ogóle nie wolno zmieniać broni, luf ani czoków, tylko między seriami, z wyjątkiem sytuacji po awarii."], "key_points": ["Czok zwęża wylot lufy: ciaśniejszy na dalekie rzutki, bardziej otwarty na bliskie.", "Tulejki wymienne wkręca się kluczem do czoków; producenci ostrzegają, by nigdy nie strzelać bez nich.", "Ułamki: ćwierć = improved cylinder, pół = modified, trzy czwarte = improved modified, pełny = full.", "Zachowaj nazwy czoków tak, jak padły; nie przeliczaj na milimetry.", "Sporting™: zmiana między stanowiskami, nigdy na stanowisku; Compak®: bez zmian w trakcie serii."], "terms": ["choke", "multichoke", "fixed-choke", "choke-key", "cylinder", "skeet-choke", "improved-cylinder", "modified", "improved-modified", "full-choke", "pattern"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Beretta — Choke tubes identification", "url": "https://estore.beretta.com/en-gb/utility/choke-tubes-identification"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}], "coach_says": [{"en": "What chokes are you using? — Quarter and half.", "meaning": "Improved cylinder w jednej lufie, modified w drugiej.", "say": "Jakie masz czoki? — Ćwierć i pół."}, {"en": "Put quarter in the bottom and half in the top — the second bird is longer.", "meaning": "Bardziej otwarty czok na pierwszy, bliższy rzutek; ciaśniejszy na drugi, dalszy.", "say": "Daj ćwierć na dół i pół na górę — drugi rzutek jest dalej."}, {"en": "Open up — these are all close.", "meaning": "Wkręć bardziej otwarte czoki, bo rzutki są blisko.", "say": "Otwórz czoki — wszystkie są blisko."}, {"en": "Check your tubes are tight before the round.", "meaning": "Upewnij się, że tulejki czoków się nie poluzowały.", "say": "Przed serią sprawdź, czy czoki są dokręcone."}], "quiz": [{"q": "Który czok daje najszerszy rozrzut?", "options": ["Full (pełny)", "Improved modified (3/4)", "Modified (1/2)", "Cylinder (walec)"], "answer": 3, "why": "Cylinder nie ma zwężenia, więc śrut rozchodzi się najwcześniej."}, {"q": "W Sporting™ strzelec, który już stoi na stanowisku, chce zmienić czok. Czy to dozwolone?", "options": ["Tak, jeśli nie powoduje opóźnienia", "Nie, nie po wejściu na stanowisko", "Tak, ale tylko przed dubletami", "Tylko za zgodą jury"], "answer": 1, "why": "Zmiany są dozwolone między stanowiskami albo między rzutkami pojedynczymi a dubletami, bez opóźnienia, ale nigdy po wejściu strzelca na stanowisko."}, {"q": "Na włoskiej strzelbie czok z pięcioma gwiazdkami to…", "options": ["najbardziej otwarty", "najciaśniejszy", "uszkodzony czok", "lufa gwintowana"], "answer": 0, "why": "Przy oznaczeniu gwiazdkami więcej gwiazdek oznacza bardziej otwarty czok."}]}, {"id": "gear-cartridges", "minutes": 5, "title": "Naboje: kaliber, numer śrutu i ograniczenia", "body": ["Nabój (cartridge) zawiera wszystko na jeden strzał: łuskę (hull) z metalowym denkiem, spłonkę (primer), proch (powder), przybitkę (wad) i śrut (shot). Strzelcy mówią też „shell”. „Empties” to puste, wystrzelone łuski.", "Kaliber (gauge) liczy się po staremu: im mniejsza liczba, tym szerszy przewód lufy, więc kaliber 12 jest szerszy niż 20. FITASC dopuszcza broń o kalibrze nie większym niż 12, a większość strzelców używa dwunastki. Nigdy nie tłumacz „12 gauge” jako „12 mm”.", "Numer śrutu też działa odwrotnie: im większy numer, tym mniejsza śrucina, więc nr 9 jest drobniejszy niż nr 7½. Ten sam numer może oznaczać nieco inne średnice w Wielkiej Brytanii, Europie kontynentalnej i USA, więc podawaj numer tak, jak padł, i sprawdzaj milimetry na pudełku. „Nines” (dziewiątki) i „seven-and-a-halfs” (siedem i pół) to częste słowa trenerów.", "Przepisy Parcours de Chasse – Sporting™ i Compak® Sporting są takie same: najwyżej 28 g śrutu ołowianego, z tolerancją +2%; okrągłe śruciny o średnicy od 2,0 do 2,5 mm (±0,1 mm). Naboje elaborowane ponownie (reloads), dyspersery, mieszane numery śrutu, proch czarny i smugacze są zabronione. W Sporting™ sędzia może pobrać do sprawdzenia dwa naboje, po jednym z każdej kieszeni kamizelki; w Compak® Sporting strzały oddane niezgodnymi nabojami przed kontrolą liczą się jako zero.", "Niektóre strzelnice dodają własne zasady środowiskowe na treningi, np. tylko przybitki filcowe (fibre wads) albo tylko śrut stalowy: sprawdź regulamin strzelnicy przed wyjazdem. Puste łuski wrzuca się do pojemnika na stanowisku, a strzelcy z półautomatami zbierają wyrzucone łuski, gdy schodzą ze stanowiska."], "key_points": ["Nabój = łuska, spłonka, proch, przybitka, śrut.", "Kaliber: mniejsza liczba, szerszy przewód lufy; maksimum FITASC to kaliber 12.", "Numer śrutu: większy numer, mniejsza śrucina; numeracja różni się w krajach, sprawdzaj milimetry.", "Ograniczenia: 28 g ołowiu (+2%), śruciny 2,0–2,5 mm; bez naboi elaborowanych, mieszanego śrutu, prochu czarnego i smugaczy.", "Puste łuski do pojemnika; użytkownicy półautomatów zbierają swoje łuski."], "terms": ["cartridge", "hull", "primer", "powder", "wad", "shot-size", "load-weight", "gauge", "lead-shot", "steel-shot", "empties"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}, {"book": "compak", "id": "ch18-cartridge-bans", "label": "18 · Prohibited ammunition"}, {"book": "sporting", "id": "ch7-cartridge-check", "label": "7 · Cartridge checks by the referee"}, {"book": "compak", "id": "ch23-noncompliant-equipment", "label": "23 · Shots with non-compliant guns or ammunition"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "compak", "id": "ch18-empty-cases", "label": "18 · Disposing of empty cases"}], "coach_says": [{"en": "Nines for the close stuff, seven-and-a-halfs for the long crossers.", "meaning": "Drobniejszy śrut nr 9 na bliskie rzutki, grubszy nr 7½ na dalekie rzutki poprzeczne.", "say": "Dziewiątki na bliskie, siedem i pół na dalekie poprzeczne."}, {"en": "Maximum twenty-eight grams on this shoot.", "meaning": "Limit naważki na zawodach, jak w przepisach FITASC.", "say": "Na tych zawodach maksymalnie dwadzieścia osiem gramów."}, {"en": "Empties in the bin, please, not on the grass.", "meaning": "Wrzucaj wystrzelone łuski do pojemnika.", "say": "Puste łuski do pojemnika, proszę, nie na trawę."}, {"en": "Steel only on this ground.", "meaning": "Śrut ołowiany jest na tej strzelnicy niedozwolony (przepis lokalny, nie FITASC).", "say": "Na tej strzelnicy tylko stal."}], "quiz": [{"q": "Który śrut jest drobniejszy?", "options": ["Nr 7", "Nr 7½", "Nr 8", "Nr 9"], "answer": 3, "why": "Im większy numer śrutu, tym mniejsza śrucina."}, {"q": "Jaka jest maksymalna naważka śrutu według przepisów FITASC?", "options": ["24 g, bez tolerancji", "28 g, z tolerancją +2%", "32 g tylko na dalekie rzutki", "Bez limitu, każda naważka jest dozwolona"], "answer": 1, "why": "Obie dyscypliny dopuszczają najwyżej 28 g śrutu ołowianego, +2%."}, {"q": "Klient mówi, że jego broń to „12 gauge”. Co to znaczy?", "options": ["Rozmiar przewodu lufy: szerszy niż kaliber 20", "Przewód lufy ma 12 milimetrów średnicy", "W magazynku mieści się dwanaście nabojów", "Lufy mają 12 cali długości"], "answer": 0, "why": "Kaliber (gauge) to stara jednostka: im mniejsza liczba, tym szerszy przewód lufy. To nie są milimetry."}]}, {"id": "gear-protection-clothes", "minutes": 5, "title": "Ochrona, kamizelka i kodeks ubioru", "body": ["Ochronniki słuchu są obowiązkowe dla każdego na osi lub w jej pobliżu: strzelców, sędziów, obsługi i widzów, a więc także dla ciebie. Sprawdzają się zarówno zatyczki do uszu (earplugs), jak i nauszniki (ear muffs); ochronniki aktywne wzmacniają głos i tłumią huk, co pomaga ci słyszeć trenera i sędziego. Strzelec, który przyjdzie na stanowisko bez ochrony, jest traktowany jako nieobecny.", "Okulary strzeleckie (safety glasses) również są obowiązkowe — dla strzelców, sędziów i obsługi, a w Parcours de Chasse – Sporting™ dla każdego, kto jest blisko stanowiska. Szkła mają różne kolory (żółty, pomarańczowy, fioletowy, dymiony), które pomagają widzieć rzutki w różnym świetle.", "Kamizelka strzelecka (shooting vest) ma dwie przednie kieszenie na naboje i nakładkę na ramię. W Sporting™ ma kontrastową poziomą linię 25 cm poniżej osi barków: przed komendą górna część kolby musi pozostać poniżej niej, a sędzia to sprawdza. Compak® Sporting nie ma takiej linii, bo pozycja broni przy komendzie jest dowolna.", "Zasady ubioru są takie same w obu dyscyplinach: żadnych krótkich szortów (tylko długie szorty kończące się nie wyżej niż 5 cm nad kolanem), górna część ubioru co najmniej z krótkimi rękawami, żadnej kamizelki na gołe ciało i ze względów bezpieczeństwa żadnych sandałów. Numer startowy nosi się na plecach, w pełni widoczny. Naruszenie oznacza najpierw ostrzeżenie, potem kolejne kary.", "Wielu strzelców nosi też czapkę z daszkiem przeciw słońcu i deszczowi, rękawiczki oraz torbę na naboje z zapasem na cały dzień. To zwyczaj, a nie przepisy."], "key_points": ["Ochronniki słuchu są obowiązkowe dla każdego w pobliżu osi, łącznie z tłumaczami.", "Okulary strzeleckie są obowiązkowe; strzelec bez ochrony jest traktowany jako nieobecny.", "Kamizelka w Sporting™: kontrastowa linia 25 cm pod osią barków; Compak® jej nie ma.", "Strój: szorty nie wyżej niż 5 cm nad kolanem, rękawy, bez gołej klatki pod kamizelką, bez sandałów.", "Numer startowy na plecach, w pełni widoczny."], "terms": ["hearing-protection", "earplugs", "electronic-ear-muffs", "safety-glasses", "shooting-vest", "jacket-line", "dress-code", "competitor-number", "cartridge-bag"], "sources": [], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}], "coach_says": [{"en": "Ears and eyes on before you walk up.", "meaning": "Załóż ochronniki słuchu i okulary, zanim podejdziesz do stanowiska.", "say": "Ochronniki i okulary założone, zanim podejdziesz."}, {"en": "Butt under the tape until you see the target.", "meaning": "Zasada broni opuszczonej w Sporting™: kolba zostaje poniżej linii na kamizelce, aż pojawi się rzutek.", "say": "Kolba pod taśmą, dopóki nie zobaczysz rzutka."}, {"en": "No marker needed here — it's Compak.", "meaning": "Compak® nie wymaga linii na kamizelce.", "say": "Tu nie trzeba znacznika — to Compak."}], "quiz": [{"q": "Jesteś tłumaczem i stoisz w pobliżu stanowiska. Czy musisz nosić ochronniki słuchu?", "options": ["Nie, tylko strzelcy na stanowisku", "Tylko podczas finałów i dogrywek", "Tak, każdy na osi lub w jej pobliżu", "Tylko jeśli sędzia cię o to poprosi"], "answer": 2, "why": "Ochronniki słuchu są obowiązkowe dla strzelców, sędziów, obsługi i widzów."}, {"q": "Gdzie jest linia na kamizelce w Sporting™?", "options": ["25 cm poniżej osi barków", "W pasie, na linii paska", "Na rękawie ramienia strzeleckiego", "W Sporting™ nie ma takiej linii"], "answer": 0, "why": "Kontrastowa linia jest 25 cm poniżej osi barków i równolegle do niej; kolba musi pozostać poniżej niej, zanim pojawi się rzutek."}, {"q": "Jakie obuwie jest zakazane w obu dyscyplinach?", "options": ["Buty trailowe", "Sandały", "Buty za kostkę", "Buty sportowe"], "answer": 1, "why": "Sandały są zabronione ze względów bezpieczeństwa."}]}]}, {"id": "targets", "icon": "target", "title": "Rzutki", "intro": "Trener, który mówi „it's a midi off the tower, then a rabbit on report”, zakłada, że potrafisz to sobie wyobrazić. Ta misja uczy rodzajów rzutków, tego, jak kolor i światło zmieniają to, co widzi strzelec, jak wyrzutnie zwalniają rzutki, jak czytać menu rzutków, i jednego pytania o punktację, które rozstrzyga wszystko: trafiony czy chybiony.", "lessons": [{"id": "targets-types", "minutes": 5, "title": "Rodzaje rzutków: standard, midi, mini, battue, rabbit, flash, ZZ", "body": ["Lista FITASC dla Parcours de Chasse – Sporting™ wymienia siedem rodzajów rzutków: standard, midi, super mini, battue, rabbit, flash i ZZ. Compak® Sporting dopuszcza dowolny rzutek standardowy lub specjalny, a jego lista wymienia też rocket. Każdy rodzaj leci inaczej.", "Standard, najczęstszy rzutek, to kopułka o średnicy ok. 108–110 mm. Midi ma 90 mm: dobrze utrzymuje prędkość i wydaje się dalej, niż jest. Mini ma 60 mm: szybko wylatuje z wyrzutni i szybko zwalnia, więc strzelcy mają skłonność dawać mu za dużo wyprzedzenia. Lista Sporting™ nazywa mały rzutek „super mini”, a przepis o menu wymienia rozmiary 70 mm i 60 mm; nazwy nie są używane konsekwentnie, więc zawsze kieruj się milimetrami zapisanymi w menu.", "Battue to płaski, cienki rzutek 110 mm. Leci krawędzią, prawie niewidoczny, potem obraca się, pokazując płaską stronę, i szybko opada. Rabbit (zając) to rzutek 110 mm z grubym, wytrzymałym obrzeżem, toczony na krawędzi po ziemi; odbija się i może podskakiwać na nierównościach. Po polsku usłyszysz „rabbit” albo „zając”; ten kurs używa słowa „rabbit”.", "Rzutek flash jest wypełniony kolorowym proszkiem, który po trafieniu zostawia jasną chmurę; liczy się go jak każdy inny rzutek. Rzutek ZZ, zwany też helice, to plastikowe śmigło z białą nakładką pośrodku, które leci nieregularnie. Rocket to rzutek specjalny wymieniony tylko na liście Compak® Sporting; nie podajemy jego specyfikacji.", "W Sporting™ rzutek niewłaściwego koloru, rozmiaru lub rodzaju to No Bird i jest powtarzany."], "key_points": ["Lista Sporting™: standard, midi, super mini, battue, rabbit, flash, ZZ; Compak® dopuszcza każdy rodzaj, w tym rocket.", "Standard ok. 108–110 mm, midi 90 mm, mini 60 mm; menu może też podawać 70 mm — kieruj się milimetrami.", "Battue: płaski, leci krawędzią, obraca się i opada; rabbit: grube obrzeże, toczy się i podskakuje.", "Flash zostawia chmurę proszku; ZZ to rzutek-śmigło.", "Sporting™: niewłaściwy kolor, rozmiar lub rodzaj = No Bird."], "terms": ["standard-target", "midi", "mini", "super-mini", "battue", "rabbit", "flash-target", "zz-target", "rocket-target", "no-bird"], "sources": [{"title": "Shooting UK — Clay pigeon sizes: knowing what they are will help you improve your score", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}, {"title": "Let's Go Shooting — Types of clay targets", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/types-of-clay-targets/"}, {"title": "GUNS Magazine — Helice", "url": "https://gunsmagazine.com/discover/helice/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}], "coach_says": [{"en": "The midi looks far but it isn't — don't give it too much.", "meaning": "Rzutek 90 mm wydaje się dalej, niż jest, więc wymaga mniej wyprzedzenia, niż myśli strzelec.", "say": "Midi wygląda na daleki, ale nie jest — nie dawaj mu za dużo."}, {"en": "The battue will turn and drop at the end — take it when it shows its belly.", "meaning": "Strzelaj do battue, gdy obróci się do ciebie płaską stroną.", "say": "Battue na końcu się obróci i opadnie — bierz go, gdy pokaże brzuch."}, {"en": "The mini is dying fast — shoot it early.", "meaning": "Mały rzutek szybko traci prędkość; nie czekaj.", "say": "Mini szybko gaśnie — strzelaj wcześnie."}, {"en": "The rabbit will hop on that bump — stay under it.", "meaning": "Trzymaj wyloty luf nisko przy toczącym się rzutku, żeby podskok nadal trafił w śrut.", "say": "Rabbit podskoczy na tym garbie — zostań pod nim."}], "quiz": [{"q": "Który rzutek toczy się po ziemi?", "options": ["Midi", "Battue", "Rabbit", "Flash"], "answer": 2, "why": "Rabbit ma grube obrzeże i jest wyrzucany na krawędzi po ziemi."}, {"q": "Menu podaje „70 mm”. Trener nazywa go mini. Co tłumaczysz?", "options": ["Poprawiasz na 60 mm, bo mini ma 60 mm", "Zachowujesz słowo trenera i 70 mm z menu", "Nazywasz go midi, bo ma ponad 60 mm", "Prosisz trenera, żeby mówił „super mini”"], "answer": 1, "why": "Przepisy wymieniają rozmiary 70 mm i 60 mm oraz nazwę „super mini”; ufaj milimetrom w menu i nie poprawiaj trenera."}, {"q": "Na stanowisku Sporting™ wyrzutnia wyrzuca midi zamiast standardu podanego w menu. Co się dzieje?", "options": ["No Bird, rzutek się powtarza", "Liczy się jako trafienie", "Strzelec traci rzutek", "Serię się anuluje"], "answer": 0, "why": "W Sporting™ rzutek niewłaściwego koloru, rozmiaru lub rodzaju to No Bird i jest powtarzany."}]}, {"id": "targets-colours-visibility", "minutes": 5, "title": "Kolory, światło i widoczność", "body": ["Przepisy obu dyscyplin wymagają tego samego: kolor rzutka musi wyraźnie odcinać się od tła. Rzutki dwukolorowe nie są zalecane. Kolor jest więc wyborem budowniczego parcoursu, dokonywanym dla każdego toru lotu, a nie osobnym rodzajem rzutka.", "Usłyszysz o rzutkach czarnych, pomarańczowych, białych, żółtych i różowych. Wielu budowniczych używa czarnych na tle nieba i pomarańczowych na tle drzew i trawy. Rzutek „blazed” ma kopułkę pomalowaną na jaskrawy pomarańcz. Uwaga: gdy trener mówi „the orange one”, ma na myśli kolor, a nie rozmiar. Czarny midi i pomarańczowy standard mogą lecieć z tego samego stanowiska.", "Jeśli zostanie wyrzucony rzutek w niewłaściwym kolorze, sędzia ogłasza No Bird i rzutek się powtarza. W Compak® Sporting przepisy dodają, że zła pogoda nigdy nie jest powodem do No Bird: rozbity rzutek się liczy, a chybiony jest stracony, niezależnie od warunków. W Parcours de Chasse – Sporting™ sędzia może przerwać strzelanie przy krótkiej, gwałtownej burzy lub ulewie.", "Światło zmienia wszystko. Trenerzy mówią o świetle z tyłu (słońce za rzutkiem), płaskim świetle w szare dni, cieniach pod drzewami i tle za rzutkiem: niebie, linii drzew albo ziemi. Rzutek może „zniknąć” na tle ciemnych drzew i „wyskoczyć” na tle nieba. Dlatego strzelcy zmieniają w ciągu dnia kolor szkieł.", "Tłumacząc, oddawaj słowa o kolorach i świetle dokładnie i krótko: „wylatuje z ciemnych drzew”, „gubisz go w słońcu”. Wyjaśniają, dlaczego strzelec chybił, więc mają znaczenie."], "key_points": ["Kolor rzutka musi odcinać się od tła; rzutki dwukolorowe nie są zalecane.", "Kolor to nie rodzaj: „the orange one” to kolor, a nie rozmiar.", "Niewłaściwy kolor = No Bird.", "Compak®: zła pogoda nigdy nie uzasadnia No Bird; sędziowie Sporting™ mogą przerwać przy krótkiej burzy.", "Światło z tyłu, płaskie światło, tło: słowa o świetle tłumacz dokładnie."], "terms": ["target", "no-bird", "blazed-target", "background"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch20-bad-weather", "label": "20 · No NO BIRD for bad weather"}, {"book": "sporting", "id": "ch5-weather-interruption", "label": "5 · Interrupting shooting for bad weather"}], "coach_says": [{"en": "The black one is the midi, the orange one is the standard — don't mix them up.", "meaning": "Dwa rzutki na stanowisku różnią się kolorem i rozmiarem.", "say": "Czarny to midi, pomarańczowy to standard — nie pomyl ich."}, {"en": "You lose it against the trees — pick it up later, in the sky.", "meaning": "Rzutek trudno zobaczyć na tle drzew; zacznij go obserwować tam, gdzie za nim jest niebo.", "say": "Gubisz go na tle drzew — podejmij go później, na niebie."}, {"en": "Flat light today — put the yellow lens in.", "meaning": "Szare, bezkontrastowe światło; żółte szkło poprawia kontrast.", "say": "Dziś płaskie światło — załóż żółte szkła."}], "quiz": [{"q": "Czego przepisy wymagają od koloru rzutka?", "options": ["Musi być zawsze pomarańczowy", "Musi wyraźnie odcinać się od tła", "Musi być dwukolorowy", "Dowolny kolor: przepisy milczą"], "answer": 1, "why": "Wymogiem jest widoczność na tle; rzutki dwukolorowe nie są zalecane."}, {"q": "W Compak® Sporting zaczyna mocno padać i strzelec chybia. Czy może poprosić o No Bird z powodu pogody?", "options": ["Tak, pogoda zawsze to uzasadnia", "Tylko przy pierwszym rzutku dubletu", "Tylko jeśli jury się zgodzi", "Nie, pogoda nigdy nie uzasadnia No Bird"], "answer": 3, "why": "Przepisy Compak® Sporting mówią, że pogoda nigdy nie jest powodem do No Bird."}, {"q": "Trener mówi „Watch the orange one.” Co opisuje?", "options": ["Kolor rzutka", "Rozmiar rzutka 90 mm", "Rabbita", "Rozbity rzutek"], "answer": 0, "why": "Kolor wybiera się ze względu na widoczność i nic nie mówi o rozmiarze ani rodzaju."}]}, {"id": "targets-traps", "minutes": 5, "title": "Wyrzutnie, zwalnianie i operator wyrzutni", "body": ["Wyrzutnia (trap) to maszyna, która wyrzuca rzutki. Wyrzutnie mogą być ręczne lub automatyczne (przepisy Compak® Sporting wymieniają też półautomatyczne). W Parcours de Chasse – Sporting™ wyrzutnie stanowiska oznacza się literami A, B, C, D od lewej do prawej, tak jak widać je ze stanowiska; w Compak® Sporting sześć wyrzutni to A–F, każda z tablicą z literą. Tłumacząc, zachowaj litery łacińskie: używa ich menu.", "Strzelec zwalnia rzutek komendą: przepisy wymieniają „pull” lub „ready”, choć w praktyce strzelcy wołają różnie. W Sporting™ sędzia przekazuje komendę operatorowi wyrzutni (trapper, osoba obsługująca zwalnianie) sygnałem dźwiękowym, a rzutek musi wylecieć w ciągu trzech sekund. Samej komendy nie tłumacz: to polecenie dla maszyny, a nie zdanie.", "W Compak® Sporting rzutki można zwalniać ręcznie, pilotem albo systemem sterowanym głosem (sonopull). Przy zwalnianiu ręcznym rzutek wylatuje od 0 do 3 sekund po komendzie; sonopull ma stałe opóźnienie 0,5 sekundy. Międzynarodowy Compak® Sporting in-line używa wyłącznie sonopull z elektronicznym sędziowaniem.", "Zwalnianie głosem ma mikrofon na stanowisku. Twój własny głos może go uruchomić. Na takim stanowisku nigdy nie mów głośno, gdy strzelec jest gotowy: szepcz między rzutkami albo się cofnij.", "Błędy wyrzutni to No Bird: rzutek wyrzucony później niż trzy sekundy po komendzie, rzutek z niewłaściwej wyrzutni, rzutek wyrzucony bez komendy, dwa rzutki z wyrzutni tego samego stanowiska w Sporting™ albo rzutek wyrzucony omyłkowo przez maszynę tego samego Compaku."], "key_points": ["Wyrzutnie: A–D na stanowisku Sporting™, A–F na polu Compak®; zachowaj litery łacińskie.", "Komenda („pull”, „ready”) zwalnia rzutek; nie tłumacz jej.", "Sporting™: sędzia daje sygnał operatorowi; rzutek w ciągu 3 sekund.", "Compak®: ręcznie 0–3 s, pilot albo sonopull ze stałym opóźnieniem 0,5 s.", "Rzutki spóźnione, z niewłaściwej wyrzutni lub bez komendy to No Bird; mikrofon może cię usłyszeć."], "terms": ["trap", "trapper", "call", "sonopull", "manual-release", "tower", "no-bird"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch16-terms", "label": "16 · Other basic terms"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Trap B is throwing lower than in the showing — tell the referee.", "meaning": "Tor lotu z tej maszyny się zmienił; strzelec powinien to zgłosić przed strzelaniem.", "say": "Wyrzutnia B rzuca niżej niż na pokazie — powiedz sędziemu."}, {"en": "It's voice release here — don't chat on the stand.", "meaning": "Mikrofon zwalnia rzutki; rozmowa może wyrzucić rzutek.", "say": "Tu jest zwalnianie głosem — nie rozmawiaj na stanowisku."}, {"en": "The trapper was late on that one — that's a no bird.", "meaning": "Rzutek wyleciał później niż trzy sekundy po komendzie.", "say": "Operator się spóźnił z tym rzutkiem — to No Bird."}], "quiz": [{"q": "W Sporting™ ile może trwać, zanim rzutek wyleci po sygnale sędziego?", "options": ["Do 1 sekundy", "Do 3 sekund", "Do 10 sekund", "Dowolnie długo"], "answer": 1, "why": "Rzutek wyrzucony później niż po trzech sekundach to No Bird."}, {"q": "Jakie jest stałe opóźnienie sonopull w Compak®?", "options": ["0 sekund", "3 sekundy", "0,5 sekundy", "Ustawia je każdy strzelec"], "answer": 2, "why": "Sonopull musi mieć stałe, niezmienne opóźnienie 0,5 sekundy."}, {"q": "Jesteś na stanowisku ze zwalnianiem głosem, a strzelec jest gotowy. Co robisz?", "options": ["Tłumaczysz głośno, żeby cię usłyszał", "Prosisz operatora wyrzutni, żeby chwilę poczekał", "Powtarzasz za niego komendę", "Milczysz; szepczesz tylko między rzutkami"], "answer": 3, "why": "Twój głos może uruchomić mikrofon i wyrzucić rzutek, którego nikt nie wołał."}]}, {"id": "targets-menu", "minutes": 5, "title": "Jak czytać menu rzutków", "body": ["Menu rzutków (target menu) to tablica przy stanowisku, która mówi strzelcowi, co go czeka. Strzelcy naprawdę mówią „menu”, więc zachowaj to słowo.", "W Parcours de Chasse – Sporting™ menu wymienia wyrzutnie w kolejności strzelania i musi pokazywać rzutki specjalne: 90 mm, 70 mm, 60 mm, battue lub rabbit. Sędziowie sprawdzają wcześniej, czy maszyny zgadzają się z menu. Oś daje 15 rzutków pojedynczych i 5 dubletów, a w dubletach można używać tylko rzutków pokazanych już jako pojedyncze z tego samego stanowiska. Grupa strzela najpierw pojedyncze, potem dublety.", "Dublet jest oznaczony rodzajem: na zawołanie (drugi rzutek wylatuje na huk pierwszego strzału), symultaniczny (oba razem) lub rafale (dwa z tej samej wyrzutni, jeden po drugim; tylko Sporting™). Menu wyglądają różnie na różnych strzelnicach, więc czytaj słowa, a nie tylko litery. Przykład dla stanowiska z trzema wyrzutniami: pojedyncze A, B, C; dublety A + B symultaniczny i C + C rafale (na takim stanowisku dwa dublety na zawołanie są niedozwolone).", "W Compak® Sporting menu wywiesza się na każdym z pięciu stanowisk. Każde stanowisko ma pięć rzutków: pięć pojedynczych, trzy pojedyncze i dublet albo jeden pojedynczy i dwa dublety. Rodzaj dubletu jest taki sam na wszystkich pięciu stanowiskach Compaku, a pierwszym rzutkiem każdego dubletu jest ostatni rzutek poprzedniego stanowiska. FITASC oferuje 40 gotowych menu na zawody.", "Zanim twój strzelec wejdzie na stanowisko, przeczytaj mu menu na głos w jego języku, litera po literze: „A, potem F, potem dublet C i E na zawołanie”."], "key_points": ["Zachowaj słowo „menu”.", "Menu Sporting™: wyrzutnie w kolejności plus rzutki specjalne (90, 70, 60 mm, battue, rabbit).", "15 pojedynczych + 5 dubletów; dublety z rzutków pokazanych już jako pojedyncze; najpierw pojedyncze.", "Dublety: na zawołanie, symultaniczny, rafale (tylko Sporting™).", "Compak®: pięć rzutków na stanowisko, ten sam rodzaj dubletu na wszystkich stanowiskach, każdy dublet zaczyna się od ostatniego rzutka poprzedniego stanowiska."], "terms": ["target-menu", "single-target", "double", "double-on-report", "simultaneous-double", "rafale-double"], "sources": [{"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch2-doubles-three-traps", "label": "2 · Doubles at a position with 3 machines"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-annex3-tables", "label": "17 · The 40 pre-established trajectory setting tables"}], "coach_says": [{"en": "Read the menu: on station three you have A, then F, then the pair C and E on report.", "meaning": "Kolejność rzutków na stanowisku 3, zakończona dubletem na zawołanie.", "say": "Przeczytaj menu: na stanowisku trzecim masz A, potem F, potem dublet C i E na zawołanie."}, {"en": "Same traps, new menu — don't shoot from memory.", "meaning": "Kolejność zmieniła się od ostatniej serii.", "say": "Te same wyrzutnie, nowe menu — nie strzelaj z pamięci."}, {"en": "Three singles, then a simo pair.", "meaning": "„Simo” to skrót od dubletu symultanicznego.", "say": "Trzy pojedyncze, potem dublet symultaniczny."}], "quiz": [{"q": "Jakie rzutki specjalne musi pokazywać menu Sporting™?", "options": ["Tylko kolory rzutków", "90 mm, 70 mm, 60 mm, battue lub rabbit", "Tylko rabbity i battue", "Żadne; ogłasza je sędzia"], "answer": 1, "why": "Menu musi wymieniać wyrzutnie w kolejności i wszystkie specjalne rodzaje rzutków."}, {"q": "W Compak® Sporting od którego rzutka zaczyna się każdy dublet?", "options": ["Zawsze od wyrzutni A", "Od rzutka, którego nigdy wcześniej nie widziano", "Od ostatniego rzutka strzelanego na poprzednim stanowisku", "Od dowolnego rzutka wybranego przez strzelca"], "answer": 2, "why": "Dublety łączą stanowiska w łańcuch: każdy zaczyna się od ostatniego rzutka poprzedniego stanowiska."}, {"q": "Jaki rodzaj dubletu istnieje tylko w Sporting™?", "options": ["Rafale", "Na zawołanie", "Symultaniczny", "Żaden"], "answer": 0, "why": "Dublety Compak® są na zawołanie lub symultaniczne; rafale to dublet Sporting™."}]}, {"id": "targets-hit-or-lost", "minutes": 5, "title": "Trafiony czy chybiony: widoczny odprysk i pułapka „dymu”", "body": ["Rzutek liczy się jako „one” (trafiony), gdy został prawidłowo wyrzucony, strzelec strzelał zgodnie z przepisami i odpadł od niego co najmniej jeden widoczny kawałek albo rzutek został całkowicie lub częściowo zniszczony. Rzutki flash podlegają tej samej zasadzie. Rzutek to „zero” (chybiony), gdy nie odpada żaden widoczny kawałek, a jest tylko pył lub dym.", "Zasada sprowadza się więc do jednego obrazu: widocznego odprysku. Mały odprysk, który odlatuje, liczy się jako trafienie. Obłoczek pyłu, gdy rzutek leci dalej w całości, to pudło. Na karcie wyników trafienie zwykle oznacza się X, a pudło O.", "Decyduje wyłącznie sędzia. Członkowie grupy nie mogą wyrażać opinii i nikt nie może podnosić rzutka, by go sprawdzić. W Compak® Sporting sędzia ogłasza każde zero głośno lub sygnałem dźwiękowym. W Parcours de Chasse – Sporting™ strzelec musi rozbijać rzutki tam, gdzie widzi je sędzia. Wołając następny rzutek, strzelec akceptuje decyzję w sprawie poprzedniego, więc każde zastrzeżenie musi paść od razu.", "A teraz pułapka dla tłumaczy. Trenerzy chwalą idealne trafienie słowami „smoked it”, „inked it” albo „powdered it”: rzutek zamienił się w czarną chmurę. To najlepsze możliwe trafienie, a nie zero. Ale w przepisach „only dust or smoke” oznacza pudło. „Dusted it” jest ryzykowne: zwykle znaczy, że odpadł tylko pył, czyli rzutek chybiony, ale niektórzy używają tego jako pochwały. Jeśli nie masz pewności, dopytaj, bo oba znaczenia są przeciwne.", "Ponadto: „dead” oznacza trafiony (nie „martwy”), a „lost” chybiony (nie „zgubiony”)."], "key_points": ["Trafiony = odpadł co najmniej jeden widoczny kawałek albo rzutek został całkowicie lub częściowo zniszczony.", "Zero = brak widocznego kawałka, tylko pył lub dym.", "Decyduje tylko sędzia; nie podnosi się rzutków; zawołanie następnego rzutka akceptuje decyzję.", "Żargon trenera „smoked it” = idealne trafienie; w przepisach „only smoke” = chybiony.", "„Dead” = trafiony, „lost” = chybiony; dopytaj, jeśli „dusted” jest niejasne."], "terms": ["one", "zero", "visible-piece", "referee", "score-sheet", "smoked-it", "chip"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "Smoked it! That's the picture.", "meaning": "Idealne trafienie: rzutek zamienił się w pył; strzelec powinien zapamiętać ten obraz.", "say": "Rozniosłeś go w pył! To jest ten obraz."}, {"en": "Dead — only a chip, but it counts.", "meaning": "Odpadł mały widoczny kawałek, więc to trafienie.", "say": "Trafiony — tylko odprysk, ale się liczy."}, {"en": "Lost — you were just behind it.", "meaning": "Pudło; śrut przeszedł za rzutkiem.", "say": "Chybiony — byłeś minimalnie za nim."}, {"en": "Don't argue with me later — say it now, before you call.", "meaning": "Zastrzeżenie trzeba zgłosić od razu; zawołanie następnego rzutka oznacza akceptację decyzji.", "say": "Nie kłóć się ze mną później — powiedz teraz, zanim zawołasz."}], "quiz": [{"q": "Rzutek leci dalej w całości, ale pojawia się obłoczek pyłu. Jaki jest wynik?", "options": ["Zero (chybiony)", "Trafiony", "No Bird", "Pół punktu"], "answer": 0, "why": "Sam pył lub dym, bez widocznego kawałka, to rzutek chybiony."}, {"q": "Trener krzyczy „Smoked it!”. Jak przetłumaczysz sens?", "options": ["Tylko zadymił, więc rzutek jest chybiony", "Lufy się przegrzewają", "Idealne trafienie: rzutek obrócił się w pył", "Wyrzutnia się pali"], "answer": 2, "why": "W żargonie trenerów „smoked it” to pochwała za całkowite rozbicie; sformułowanie z przepisów „only smoke” znaczy coś przeciwnego."}, {"q": "Członek grupy mówi, że ostatni rzutek był trafiony. Kto decyduje?", "options": ["Głosowanie grupy", "Trener", "Tłumacz", "Wyłącznie sędzia"], "answer": 3, "why": "Decyzje o rzutkach należą do sędziego; członkowie grupy nie mogą się wtrącać."}]}]}, {"id": "flight", "icon": "trajectory", "title": "Jak latają rzutki (prezentacje)", "intro": "Trenerzy nazywają każdy rzutek według tego, jak leci: crosser, incomer, teal, looper, rabbit, report pair. W sześciu krótkich lekcjach poznasz znaczenie każdej nazwy, to, co strzelec ma z danym rzutkiem zrobić, i słowa, które łatwo źle przetłumaczyć.", "lessons": [{"id": "flight-crosser", "minutes": 5, "title": "Crosser: rzutek poprzeczny", "body": ["Rzutek poprzeczny (crosser) leci w poprzek przed strzelcem, mniej więcej pod kątem prostym do linii wzroku: z lewej na prawą (zapis L→R) albo z prawej na lewą (R→L). Na osi Parcours de Chasse – Sporting™ przepisy wymagają mieszanki rzutków poprzecznych, skośnych, nadlatujących i odlatujących. W Compak® Sporting rzutek poprzeczny z lewej na prawą i z prawej na lewą to dwa z trzech obowiązkowych torów lotu, więc każdy Compak je ma.", "Rzutek poprzeczny pokazuje całą swoją prędkość w bok, więc ze wszystkich prezentacji wymaga największego wyprzedzenia (lead), a im jest dalej, tym więcej wyprzedzenia potrzebuje. „Long crosser” to rzutek daleki, a nie taki, który długo leci.", "Odczytaj jego linię i prędkość: leci płasko, wznosi się czy w punkcie strzału już opada? Pokazuje „twarz” (kopułkę lub spód) czy tylko krawędź? Zwalnia? Zwalniający rzutek poprzeczny potrzebuje mniej wyprzedzenia niż lecący z pełną prędkością.", "Typowy plan: stopy ustawione pod punkt strzału, oczy podejmują rzutek wcześnie, potem pull-away albo stałe wyprzedzenie (maintained lead), z bronią wciąż w ruchu w chwili strzału. Bardzo częsty werdykt trenera przy rzutku poprzecznym to „behind” — za rzutkiem: za mało wyprzedzenia albo broń, która się zatrzymała.", "Kierunki podaje się z punktu widzenia strzelca. Jeśli stoisz twarzą do strzelca, jego „z lewej na prawą” to twoje z prawej na lewą, więc nigdy nie odwracaj tych słów."], "key_points": ["Rzutek poprzeczny leci w poprzek, ok. 90° do linii wzroku: L→R lub R→L.", "Wymaga największego wyprzedzenia; większa odległość = większe wyprzedzenie.", "„Long crosser” = daleki, a nie długo lecący.", "Compak® Sporting zawsze ma rzutek poprzeczny L→R i R→L.", "Lewo i prawo zawsze z punktu widzenia strzelca."], "terms": ["crosser", "lead", "trajectory", "target-line", "break-point", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["crosser-rl"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}], "coach_says": [{"en": "Long crosser, right to left — trust the lead and keep the gun moving.", "meaning": "Rzutek jest daleko i leci od prawej do lewej strzelca; daj mu zaplanowane wyprzedzenie i nie zatrzymuj broni.", "say": "Daleki poprzeczny, z prawej na lewą — zaufaj wyprzedzeniu i trzymaj broń w ruchu."}, {"en": "You're behind it — give it more.", "meaning": "Śrut przeszedł za rzutkiem: potrzeba więcej wyprzedzenia.", "say": "Jesteś za nim — daj więcej."}, {"en": "It's dropping at your break point — stay under the line.", "meaning": "W miejscu, gdzie strzelec go rozbija, rzutek poprzeczny już opada, więc broń musi iść nieco poniżej jego toru.", "say": "W twoim punkcie strzału już opada — zostań pod linią."}, {"en": "Pick it up early, it's quick off the trap.", "meaning": "Szukaj rzutka bliżej wyrzutni niż zwykle, bo szybko z niej wylatuje.", "say": "Podejmij go wcześnie, szybko schodzi z wyrzutni."}], "quiz": [{"q": "Która prezentacja zwykle wymaga największego wyprzedzenia?", "options": ["Rzutek lecący prosto od strzelca", "Rzutek nadlatujący prosto na strzelca", "Rzutek poprzeczny w tej samej odległości", "Rabbit toczący się prosto od strzelca"], "answer": 2, "why": "Rzutek poprzeczny pokazuje całą prędkość w bok, więc broń musi być najdalej przed nim; rzutki lecące po linii prostej wymagają niewielkiego wyprzedzenia w bok."}, {"q": "Trener mówi „long crosser”. Co znaczy „long”?", "options": ["Rzutek jest daleko", "Rzutek leci długo", "To długi, owalny rzutek", "Strzelec powinien długo czekać"], "answer": 0, "why": "W języku trenerów „long” opisuje odległość. Long crosser to daleki rzutek poprzeczny, który wymaga większego wyprzedzenia."}, {"q": "Co jest prawdą o rzutkach poprzecznych w Compak® Sporting?", "options": ["Rzutki poprzeczne są niedozwolone na Compaku", "Dozwolone są tylko rzutki z prawej na lewą", "Rzutki poprzeczne można wyrzucać tylko jako rabbity", "Rzutek poprzeczny L→R i R→L jest obowiązkowy"], "answer": 3, "why": "Przepisy Compak® Sporting czynią obowiązkowymi trzy tory lotu: rzutek poprzeczny L→R, rzutek poprzeczny R→L i rzutek odlatujący."}]}, {"id": "flight-incomer-going-away", "minutes": 5, "title": "Nadlatujący, odlatujący, driven i nad głową", "body": ["Rzutek nadlatujący (incomer) leci w stronę strzelca, często z odległej wyrzutni lub z wieży, i zwykle opada, zbliżając się. Może wydawać się, że zwalnia i wisi w powietrzu, co kusi strzelców do celowania. Zwykle bierze się go przed sobą, zanim znajdzie się nad głową, a lufy mogą w chwili strzału zakryć rzutek („blot out”). To zamierzone, a nie błąd.", "Rzutek odlatujący (going-away) startuje blisko strzelca lub za nim i odlatuje. Wymaga niewielkiego wyprzedzenia w bok, ale szybko maleje i często się wznosi lub opada, więc wyprzedzenie jest głównie pionowe i liczy się wyczucie czasu: nie czekaj. W Compak® Sporting rzutek odlatujący nad bokiem BC jest obowiązkowy; może wylatywać z rowu z przodu albo z wieży za stanowiskami, co najmniej 4 m nad nimi.", "Rzutek driven (przelot nad głową) to rzutek nadlatujący, który przelatuje nad głową strzelca, jak bażant wypędzany przez naganiaczy. Podejmij go wcześnie, ruszaj z nim, prowadź broń od tyłu w górę przez rzutek, strzelaj, gdy lufy go zakryją, i prowadź dalej. Uwaga: francuskie „en battue” (włoskie „in battuta”) oznacza zwierzynę pędzoną, a nie rzutek battue.", "Rzutek nad głową od tyłu (overhead from behind) nadlatuje zza pleców strzelca i odlatuje. Widać go późno, więc strzelec wcześnie spogląda za siebie, składa się razem z nim, strzela, gdy wylot lufy dotyka jego przodu, i prowadzi broń dalej.", "„Incoming” i „going away” zawsze opisują rzutek względem strzelca."], "key_points": ["Nadlatujący: leci w stronę strzelca, zwykle opadając; bierz go przed sobą.", "Odlatujący: małe wyprzedzenie w bok, głównie pionowe; strzelaj bez zwłoki.", "Driven: nadlatujący nad głową; prowadź od tyłu przez rzutek i zakryj go.", "Nad głową od tyłu: wcześnie spójrz za siebie, składaj się razem z nim, prowadź dalej.", "Compak® Sporting zawsze zawiera rzutek odlatujący."], "terms": ["incomer", "going-away", "driven-target", "overhead", "tower", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "ShotKam — Master incomers", "url": "https://shotkam.com/blogs/blog-collections/master-incomers"}, {"title": "Sporting Gun — How to shoot going-away targets", "url": "https://sporting-gun.com/shooting/how-to-shoot-going-away-targets/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "flight", "preset": "incomer", "also": ["going-away", "overhead"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}], "coach_says": [{"en": "Take it out in front, before it gets on top of you.", "meaning": "Rozbij rzutek nadlatujący, gdy jest jeszcze przed tobą, a nie nad głową.", "say": "Bierz go przed sobą, zanim będzie nad tobą."}, {"en": "Blot it out and keep swinging.", "meaning": "Pozwól lufom zakryć rzutek w chwili strzału i nie zatrzymuj broni.", "say": "Zakryj go i prowadź dalej."}, {"en": "Don't wait on the going-away — it's getting smaller.", "meaning": "Strzelaj do rzutka odlatującego bez zwłoki, bo szybko się oddala.", "say": "Nie czekaj na odlatującego — robi się coraz mniejszy."}, {"en": "It comes from behind you — look back for it early.", "meaning": "To rzutek nad głową od tyłu; zwróć na niego oczy przed komendą.", "say": "Leci zza ciebie — wcześnie spójrz za siebie."}], "quiz": [{"q": "Trener mówi: „Blot it out.” Co powinien zrobić strzelec?", "options": ["Przetrzeć szkła okularów strzeleckich", "Pozwolić lufom zakryć rzutek w chwili strzału", "Poczekać, aż rzutek zniknie z pola widzenia", "Strzelać tylko do spadających kawałków"], "answer": 1, "why": "Przy rzutkach nadlatujących, driven i wznoszących broń często zakrywa rzutek w chwili strzału; trener prosi właśnie o to."}, {"q": "Dlaczego nie należy zbyt długo zwlekać z rzutkiem odlatującym?", "options": ["Szybko się oddala i maleje", "Przepisy pozwalają tylko na trzy sekundy", "Zawsze zamienia się w rzutek poprzeczny", "Sędzia ogłasza No Bird po najwyższym punkcie"], "answer": 0, "why": "Rzutek odlatujący szybko zwiększa odległość, więc im dłużej czekasz, tym jest trudniej. Trzy sekundy to czas wyrzutu, a nie limit na strzał."}, {"q": "Czym rzutek driven różni się od zwykłego nadlatującego?", "options": ["Zawsze jest rabbitem", "Nadlatuje zza strzelca", "Przelatuje nad głową strzelca", "Wyrzuca się go tylko w Compak® Sporting"], "answer": 2, "why": "Driven to rzutek nadlatujący, który przechodzi nad głową, jak zwierzyna pędzona. Rzutek nadlatujący zza pleców to overhead from behind."}]}, {"id": "flight-quartering", "minutes": 5, "title": "Rzutki skośne: odlatujące i nadlatujące", "body": ["Rzutek skośny (quartering) leci pod kątem: częściowo w poprzek, częściowo od strzelca lub na niego. Quartering away (rzutek skośny odlatujący) oddala się od strzelca pod kątem, na przykład w prawo do przodu. Quartering towards (też „quartering in”, rzutek skośny nadlatujący) zbliża się do strzelca pod kątem i przechodzi z boku albo opada przed nim. Kąt to często około 45°, ale możliwe jest wszystko między rzutkiem prostym a pełnym poprzecznym.", "Wyprzedzenie zależy od kąta: większe niż przy rzutku odlatującym prosto, mniejsze niż przy pełnym poprzecznym. Ostry kąt wymaga małego wyprzedzenia, rzutek prawie poprzeczny — niemal tyle co poprzeczny.", "Rzutek skośny odlatujący szybko maleje i zwalnia, więc bierz go bez zwłoki. Dobrze pasuje do niego pull-away, bo broń zostaje na linii lotu rzutka. Rzutek skośny nadlatujący rośnie i wygląda na wolny, co kusi strzelca do czekania; może wtedy przejść zbyt blisko albo opaść poza pole widzenia.", "Ta sama wyrzutnia daje różne prezentacje z różnych stanowisk: z jednego stanowiska rzutek jest poprzeczny, z następnego skośny. Dlatego rzutki trzeba odczytywać dokładnie z tego stanowiska, z którego strzelec będzie strzelał.", "Po polsku mów „rzutek skośny odlatujący” i „rzutek skośny nadlatujący”. Dosłowne słowo utworzone od „quarter” („ćwierć”) nic strzelcowi nie powie."], "key_points": ["Skośny = lecący pod kątem, między prostym a poprzecznym.", "Skośny odlatujący oddala się pod kątem; skośny nadlatujący (in) zbliża się pod kątem.", "Wyprzedzenie rośnie z kątem: mniejsze niż przy poprzecznym, większe niż przy prostym.", "Jedna wyrzutnia wygląda inaczej z każdego stanowiska: odczytuj ją ze swojego.", "Po polsku: „rzutek skośny odlatujący / nadlatujący”."], "terms": ["quartering-away", "quartering-towards", "crosser", "going-away", "lead", "pull-away"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "flight", "preset": "quartering-away", "also": ["quartering-towards"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "The first one's quartering away to the left — take it quickly before it gets small.", "meaning": "Pierwszy rzutek oddala się pod kątem w lewo od strzelca; rozbij go wcześnie.", "say": "Pierwszy odchodzi skośnie w lewo — bierz go szybko, zanim zmaleje."}, {"en": "Quartering in from the right — don't let it get too close.", "meaning": "Rzutek zbliża się do strzelca pod kątem z prawej; nie czekaj na niego.", "say": "Skośny nadlatujący z prawej — nie daj mu podejść za blisko."}, {"en": "Less lead than you think — it's only a slight angle.", "meaning": "Rzutek leci prawie prosto, więc potrzebuje tylko małego wyprzedzenia.", "say": "Mniej wyprzedzenia, niż myślisz — to tylko lekki kąt."}], "quiz": [{"q": "Rzutek zbliża się do strzelca pod kątem i przechodzi z boku. Jak się nazywa?", "options": ["Odlatujący", "Skośny nadlatujący (quartering towards)", "Teal", "Rafale"], "answer": 1, "why": "Quartering towards (lub quartering in) to rzutek skośny nadlatujący; quartering away to rzutek skośny odlatujący."}, {"q": "Jak ma się wyprzedzenie przy rzutku skośnym do pełnego poprzecznego w tej samej odległości i przy tej samej prędkości?", "options": ["Jest takie samo jak przy poprzecznym", "Zawsze wynosi zero", "Jest większe niż przy poprzecznym", "Jest mniejsze, zależnie od kąta"], "answer": 3, "why": "Wyprzedzenia w bok wymaga tylko boczna składowa ruchu, więc im ostrzejszy kąt, tym mniejsze wyprzedzenie."}, {"q": "Dlaczego rzutek trzeba odczytywać dokładnie z tego stanowiska, z którego będziesz strzelać?", "options": ["Z jednego stanowiska wyrzutnia daje rzutek poprzeczny, z innego skośny", "Przepisy zabraniają oglądania z innego miejsca", "Rzutki zmieniają kolor między stanowiskami", "Tylko sędzia może stać gdzie indziej"], "answer": 0, "why": "Kąt między strzelcem a linią lotu rzutka zmienia się z pozycją, więc zmienia się też prezentacja."}]}, {"id": "flight-teal-chandelle-looper", "minutes": 6, "title": "Teal, chandelle, looper i rzutki opadające", "body": ["Te prezentacje dotyczą wysokości i krzywizny, a nie kąta. Ich nazwy pochodzą z języka budowniczych parcoursów, a nie z przepisów: przepisy wymieniają rodzaje rzutków, a przepisy Compak® Sporting wymagają zróżnicowanych torów lotu, np. wznoszących, opadających i wysokich (lofted).", "Teal (springing lub rising teal, od nazwy małej kaczki — cyraneczki) wyrzuca się niemal pionowo w górę; zwalnia, zawisa w najwyższym punkcie i spada z powrotem. Bierze się go albo na wznoszeniu, prowadząc broń od dołu w górę przez rzutek, albo w najwyższym punkcie, gdy zawisa. Klasyczny błąd to „dźganie” (celowanie) w niego na szczycie. Niektórzy budowniczowie nazywają „springing” rzutek, który wznosi się pod kątem, a nie pionowo, jak poderwany ptak.", "Chandelle (po francusku „świeca”) wznosi się stromo po lekkim łuku, przechyla się i spada niemal pionowo. Najłatwiej go wziąć na wznoszeniu; na zakręcie wyprzedzenie idzie w bok i w dół.", "Looper leci szerokim łukiem przez niebo, jak tęcza, często jako battue z przechylonej wyrzutni: wznosi się, obraca „twarz” i spada. Broń podąża za krzywą, przed rzutkiem i pod nim.", "Rzutek opadający (dropping) to każdy rzutek w opadającej części lotu. Wyprzedzenie jest częściowo pionowe: pod rzutkiem i przed nim, z bronią w ruchu.", "Uwaga: nazwy różnią się między krajami. Wielu francuskojęzycznych strzelców nazywa „chandelle” rzutek lecący prawie pionowo w górę, który angielski trener nazwie teal, a polscy strzelcy mogą na oba mówić „świeca”. Gdy słyszysz chandelle, candle albo „świeca”, zapytaj: prosto w górę czy łukiem?"], "key_points": ["Teal: prawie pionowo w górę, zawisa, spada; bierz na wznoszeniu lub w szczycie.", "Chandelle: stromy wznoszący łuk, przechyla się, spada niemal pionowo.", "Looper: szeroki łuk jak tęcza, często battue, które się obraca i spada.", "Opadający: wyprzedzenie pod i przed rzutkiem, nigdy nie zatrzymuj broni.", "Nazwy się różnią: francuskojęzyczni często mówią „chandelle” na teal; „świeca” też jest dwuznaczna, więc dopytaj."], "terms": ["teal", "springing-target", "chandelle", "looper", "dropping-target", "battue"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "Shotgun Life — How to shoot a chandelle target", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}, {"title": "ShotgunWorld — Target terminology (forum)", "url": "https://www.shotgunworld.com/threads/target-terminology.477902/"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}], "sim": {"type": "flight", "preset": "teal", "also": ["chandelle", "looper", "dropping"]}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}], "coach_says": [{"en": "Take the teal on the way up — keep the barrels moving above it.", "meaning": "Rozbij wznoszący się teal przed szczytem; broń wznosi się dalej, mijając go.", "say": "Bierz teal na wznoszeniu — lufy w ruchu nad nim."}, {"en": "Don't poke at it on the top.", "meaning": "Nie zatrzymuj się i nie celuj w rzutek, gdy zawisa w najwyższym punkcie.", "say": "Nie dźgaj go na górze."}, {"en": "The looper's turning over — underneath and in front.", "meaning": "Rzutek przechodzi przez szczyt łuku i zaczyna spadać; wyprzedzenie idzie pod nim i przed nim.", "say": "Looper się przewraca — pod nim i przed nim."}, {"en": "Second bird's dropping — go under it and keep the gun moving.", "meaning": "Drugi rzutek dubletu spada; strzelaj pod nim z bronią w ruchu.", "say": "Drugi opada — idź pod niego i trzymaj broń w ruchu."}], "quiz": [{"q": "Który rzutek wyrzuca się niemal pionowo w górę, zawisa w szczycie i spada z powrotem?", "options": ["Looper", "Skośny odlatujący", "Rabbit", "Teal"], "answer": 3, "why": "To teal (springing lub rising teal). Looper leci szerokim łukiem przez niebo."}, {"q": "Gdzie zwykle idzie wyprzedzenie przy rzutku opadającym?", "options": ["Nad nim i za nim", "Pod nim i przed nim", "Prosto w rzutek", "Tylko w bok, nigdy w dół"], "answer": 1, "why": "Spadający rzutek porusza się w dół i do przodu, więc część wyprzedzenia jest pionowa: pod i przed rzutkiem."}, {"q": "Francuskojęzyczny trener mówi „chandelle”. Co jest najbezpieczniej zrobić?", "options": ["Sprawdzić: prosto w górę czy łukiem przez szczyt?", "Zawsze tłumaczyć jako angielski looper", "Zawsze tłumaczyć jako angielski teal", "Zignorować, bo to nie termin z przepisów"], "answer": 0, "why": "Francuskojęzyczni często mają na myśli rzutek prawie pionowy (angielski teal), a chandelle angielskiego budowniczego wznosi się po łuku i przechyla; szybkie dopytanie chroni przed złym planem."}]}, {"id": "flight-rabbit", "minutes": 5, "title": "Rabbit: toczący się, podskakujący i wyskakujący", "body": ["Rabbit (zając) to rzutek o średnicy 110 mm z grubym, wytrzymałym obrzeżem, wyrzucany na krawędzi tak, że toczy się po ziemi jak biegnący zając. To rzutek specjalny, więc w Parcours de Chasse – Sporting™ musi być podany w menu rzutków stanowiska.", "Trenerzy opisują, jak biegnie: rolling rabbit toczy się płynnie; hopping (bouncing) rabbit podskakuje na nierównościach i kamieniach; bolting rabbit wyskakuje z zarośli i pędzi szybko. Rabbity mogą biec w poprzek, na strzelca lub od niego.", "Rabbit jest ciężki i szybko zwalnia, więc strzelcy często dają mu za dużo wyprzedzenia. Trenerzy każą trzymać wylot lufy nisko i strzelać w dolną przednią krawędź, żeby nagły podskok nadal trafił w śrut. Często widać go tylko w krótkiej luce między krzakami, więc punkt strzału trzeba zaplanować dokładnie.", "Przepisy: do każdego rzutka, także rabbita, strzela się z bronią przy ramieniu; strzał z biodra jest niedozwolony w obu dyscyplinach. Przypadek szczególny: jeśli pierwszy strzał chybi, a rabbit potem pęknie sam, np. na kamieniu, przed drugim strzałem, to No Bird. Przy powtórce liczy się tylko rozbicie drugim strzałem.", "„Fur and feather” („futro i pióro”) to w angielskim Sportingu żargonowe określenie dubletu złożonego z rabbita („fur”) i rzutka powietrznego („feather”). Po polsku usłyszysz „rabbit” albo „zając”; ten kurs używa słowa „rabbit”."], "key_points": ["Rabbit: 110 mm, grube obrzeże, toczy się na krawędzi po ziemi.", "Rolling, hopping (bouncing), bolting: opisują, jak biegnie.", "Szybko zwalnia: nie dawaj za dużo wyprzedzenia; wylot lufy nisko.", "Zawsze strzał z ramienia; rabbit, który sam pęka po chybionym pierwszym strzale, to No Bird.", "„Fur and feather” = dublet rabbit + rzutek powietrzny."], "terms": ["rabbit", "bolting-rabbit", "fur-and-feather", "target-menu", "no-bird", "break-point"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Gun Tests — Rabbit target clay shooting", "url": "https://www.gun-tests.com/recreational/rabbit-target-clay-shooting/"}, {"title": "Shooting UK — Clay pigeon sizes", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}], "sim": {"type": "flight", "preset": "rabbit"}, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch6-nobird-target-single-rabbit", "label": "6 · Target No Bird on a single and on a rabbit"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}], "coach_says": [{"en": "It hops on that bump — stay under it and keep moving.", "meaning": "Rabbit podskakuje w znanym miejscu; trzymaj broń nisko i w ruchu.", "say": "Podskakuje na tym garbie — zostań pod nim i jedź dalej."}, {"en": "Shoot its feet.", "meaning": "Śrut ma trafić w dolną krawędź rabbita, a nie nad nim.", "say": "Strzelaj mu w nogi."}, {"en": "It slows down a lot — less lead than you think.", "meaning": "Rabbit szybko traci prędkość, więc potrzebuje mniejszego wyprzedzenia.", "say": "Mocno zwalnia — mniej wyprzedzenia, niż myślisz."}, {"en": "Fur and feather: rabbit first, before it reaches the bushes.", "meaning": "W dublecie rabbit plus ptak strzelaj najpierw do rabbita, bo znika w zaroślach.", "say": "Futro i pióro: najpierw rabbit, zanim dobiegnie do krzaków."}], "quiz": [{"q": "Pierwszy strzał chybia rabbita, a ten pęka na kamieniu przed drugim strzałem. Co dalej?", "options": ["Liczy się jako trafiony, bo pękł", "Liczy się jako zero za pierwsze pudło", "No Bird: powtórka, liczy się tylko rozbicie drugim strzałem", "Strzelec po prostu przechodzi do następnego rzutka"], "answer": 2, "why": "Przepisy obu dyscyplin traktują to jako No Bird; przy powtórce strzelec musi celowo chybić pierwszym strzałem."}, {"q": "Dlaczego trenerzy ostrzegają przed zbyt dużym wyprzedzeniem przy rabbicie?", "options": ["Przepisy ograniczają wyprzedzenie", "Jest ciężki i szybko zwalnia", "Zawsze leci w górę", "Jest mniejszy od mini"], "answer": 1, "why": "Rabbit ma grube obrzeże i toczy się po ziemi, szybko tracąc prędkość, więc zwykłe wyprzedzenie jak dla rzutka poprzecznego posyła śrut przed niego."}, {"q": "Co znaczy „fur and feather”?", "options": ["Dublet z rabbita i rzutka powietrznego", "Myśliwski kodeks ubioru", "Rzutek z przyklejonymi piórami", "Dublet z dwóch rabbitów"], "answer": 0, "why": "W żargonie angielskiego Sportingu „fur” to rabbit, a „feather” rzutek latający."}]}, {"id": "flight-pairs", "minutes": 6, "title": "Rzutki pojedyncze i dublety: na zawołanie, rafale, symultaniczne", "body": ["Rzutek pojedynczy (single) to jeden rzutek z jednej wyrzutni. W obu dyscyplinach można oddać do niego dwa strzały, więc pudło można uratować drugą lufą. Dublet (pair, double) to dwa rzutki strzelane jako jedna całość po jednej komendzie.", "Dublet na zawołanie (report pair, double on report): komenda zwalnia pierwszy rzutek, a strzał do niego zwalnia drugi. W Parcours de Chasse – Sporting™ drugi wylatuje od 0 do 3 sekund po tym strzale. Kolejność jest stała. „Report” oznacza huk strzału, a nie pisemny raport.", "Dublet następujący (following pair), który FITASC nazywa rafale: dwa rzutki z tej samej wyrzutni po tej samej linii, drugi tak szybko, jak wyrzutnia się przeładuje; do każdego można strzelać jako pierwszego. Istnieje tylko w Sporting™: dublet Compak® Sporting jest na zawołanie albo symultaniczny.", "Dublet symultaniczny („simo”; w angielskim Sportingu „true pair”): oba rzutki wylatują w tej samej chwili, z jednej lub dwóch wyrzutni (w Compak® Sporting zawsze z dwóch różnych wyrzutni), i można je strzelać w dowolnej kolejności.", "Naboje: w Sporting™ na dublet są dwa i oba można oddać do jednego rzutka; jeśli jeden strzał rozbije oba, liczą się oba. W Compak® Sporting dozwolony jest tylko jeden nabój na rzutek, a oba strzały do jednego rzutka to zero-zero; jeden strzał rozbijający oba rzutki też nie jest po prostu liczony podwójnie (wyjaśnia to misja o Compak®).", "Na stanowisku Sporting™ grupa strzela najpierw rzutki pojedyncze, potem dublety. Dublety symultaniczne i rafale pokazuje się przed strzelaniem; dubletów na zawołanie nie."], "key_points": ["Rzutek pojedynczy: jeden rzutek, dozwolone dwa strzały.", "Dublet na zawołanie: strzał do pierwszego zwalnia drugi; kolejność stała.", "Rafale (dublet następujący): ta sama wyrzutnia, ta sama linia, tylko Sporting™.", "Symultaniczny (true pair): oba naraz, dowolna kolejność.", "Sporting™: oba naboje mogą iść do jednego rzutka; Compak® Sporting: jeden na rzutek."], "terms": ["single-target", "double", "double-on-report", "rafale-double", "simultaneous-double", "true-pair", "target-presentation"], "sources": [{"title": "CPSA — English Sporting (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["teal"], "pairs": ["report", "simultaneous", "rafale"]}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}], "coach_says": [{"en": "It's on report — finish the first one properly, the second waits for your shot.", "meaning": "Drugi rzutek wylatuje dopiero, gdy strzelec strzeli do pierwszego, więc nie trzeba się spieszyć z pierwszym.", "say": "To na zawołanie — dokończ porządnie pierwszego, drugi czeka na twój strzał."}, {"en": "Simo: take the rabbit first, the teal will wait for you.", "meaning": "W dublecie symultanicznym strzelaj najpierw do rabbita, bo teal dłużej zostaje w powietrzu.", "say": "Symultan: najpierw rabbit, teal na ciebie poczeka."}, {"en": "Rafale — after the first, come straight back to the trap for the second.", "meaning": "Oba rzutki lecą z tej samej wyrzutni; po pierwszym strzale wróć oczami i bronią w stronę wyrzutni, by podjąć drugi.", "say": "Rafale — po pierwszym od razu wracaj do wyrzutni po drugiego."}, {"en": "True pair from the tower, five of them.", "meaning": "Pięć dubletów symultanicznych z wieży (określenie z angielskiego Sportingu).", "say": "Dublet symultaniczny z wieży, pięć razy."}], "quiz": [{"q": "Co w dublecie na zawołanie zwalnia drugi rzutek?", "options": ["Druga komenda", "Sygnał sędziego", "Strzał do pierwszego rzutka", "Zegar ustawiony na dokładnie 5 sekund"], "answer": 2, "why": "„On report” znaczy na huk strzału: strzał do pierwszego rzutka zwalnia drugi."}, {"q": "W Compak® Sporting strzelec oddaje oba naboje do pierwszego rzutka dubletu symultanicznego. Wynik?", "options": ["Dozwolone, jak w Sporting™", "Zero-zero", "No Bird i powtórka", "Tylko drugi rzutek jest zerem"], "answer": 1, "why": "Compak® Sporting pozwala na jeden nabój na każdy rzutek dubletu; celowe oddanie obu do jednego rzutka to zero-zero. W Sporting™ byłoby to dozwolone."}, {"q": "Brytyjski trener mówi „true pair”. Jak to przetłumaczysz?", "options": ["Prawidłowy, uczciwy dublet", "Para prawdziwych ptaków", "Rafale", "Dublet symultaniczny"], "answer": 3, "why": "„True pair” to angielska nazwa dubletu symultanicznego w Sportingu; „true” nie ma nic wspólnego z poprawnością."}]}]}, {"id": "basics", "icon": "stance", "title": "Podstawy strzału", "intro": "Zanim padnie choć słowo o wyprzedzeniu, trener ustawia podstawy: stopy, złożenie się do strzału, oczy, plan trzech punktów i broń, która nie przestaje się poruszać. Te pięć lekcji daje ci słowa trenera na każdy krok oraz przepisy, które określają, co strzelcowi wolno.", "lessons": [{"id": "basics-stance", "minutes": 5, "title": "Postawa: stopy na punkt strzału", "body": ["Postawa strzelecka (stance) to sposób, w jaki strzelec stoi przed strzałem. Miejsca jest mało: w Parcours de Chasse – Sporting™ stanowisko to kwadrat lub koło o boku/średnicy 1 m i obie stopy muszą być w nim przed komendą. W Compak® Sporting każde stanowisko to kwadrat 1 m z ogranicznikiem kąta strzału (Firing Angle Limiter) — ramą, która nie pozwala strzelcowi zrobić kroku do przodu i ogranicza zakres ruchu broni.", "Typowa podstawa: stopy mniej więcej na szerokość barków; u praworęcznego lewa stopa lekko z przodu (leworęczny robi to w lustrzanym odbiciu); kolana miękkie, nie zablokowane; ciężar ciała lekko do przodu, mniej więcej 60 procent na przedniej nodze. Trenerzy mówią „nose over toes” — nos nad palcami stóp.", "Najważniejsza wskazówka: skieruj przednią stopę na punkt strzału (break point), czyli miejsce, w którym strzelec zamierza rozbić rzutek. Ciało jest wtedy wygodnie „rozkręcone” dokładnie tam, gdzie pada strzał. Strzelec skręca się z bioder z powrotem do punktu wyjściowego lufy (hold point) i rozkręca się w strzał. Jeśli stopy są zwrócone w stronę wyrzutni, ostrzegają trenerzy, zabraknie skrętu ciała i broń się zatrzyma albo głowa uniesie się z kolby.", "Ciało obraca się z bioder, a nie ramionami. Stopy mogą być ustawione nieco inaczej dla każdego rzutka.", "Tłumacz „front foot” i „back foot” jako przednia i tylna noga, a nie lewa i prawa: twój strzelec może być leworęczny."], "key_points": ["Sporting™: obie stopy wewnątrz stanowiska 1 m przed komendą.", "Compak® Sporting: stanowisko 1 m z ogranicznikiem kąta strzału (Firing Angle Limiter).", "Stopy na szerokość barków, miękkie kolana, ciężar lekko do przodu.", "Przednia stopa wskazuje punkt strzału; skręt z bioder z powrotem do punktu wyjściowego lufy.", "Tłumacz przednia/tylna noga, a nie lewa/prawa."], "terms": ["stance", "shooting-stand", "break-point", "hold-point", "firing-angle-limiter"], "sources": [{"title": "NSSA-NSCA — Stance and foot position (blog)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "Shotgun Life — Best foot position for clays shooting", "url": "https://www.shotgunlife.com/briefs/best-foot-position-for-clays-shooting.html"}, {"title": "Positive Shooting — Stance", "url": "http://www.positiveshooting.com/StanceMain.html"}], "sim": {"type": "flight", "preset": "crosser-lr", "focus": "stance"}, "rule_refs": [{"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}], "coach_says": [{"en": "Point your front foot at the break point.", "meaning": "Obróć czubek przedniej stopy w stronę miejsca, w którym rzutek zostanie rozbity.", "say": "Przednia stopa na punkt strzału."}, {"en": "Set your feet for the break, then wind back to the hold.", "meaning": "Najpierw ustaw stopy pod punkt strzału, potem obróć górną część ciała z powrotem do punktu wyjściowego lufy.", "say": "Stopy ustaw pod strzał, potem skręć się z powrotem do punktu wyjściowego."}, {"en": "Weight forward, soft knees.", "meaning": "Przenieś lekko ciężar na przednią nogę i nie blokuj kolan.", "say": "Ciężar do przodu, miękkie kolana."}, {"en": "Turn from the hips, not the arms.", "meaning": "Obraca się cała górna część ciała; same ręce nie prowadzą broni.", "say": "Obracaj się z bioder, nie rękami."}], "quiz": [{"q": "Gdzie zwykle trener chce, by wskazywała przednia stopa?", "options": ["Na wyrzutnię", "Na punkt podjęcia rzutka", "Na sędziego", "Na punkt strzału"], "answer": 3, "why": "Stopy ustawione pod punkt strzału dają ciału wygodną pozycję tam, gdzie pada strzał; przy stopach zwróconych do wyrzutni zabraknie skrętu ciała."}, {"q": "Czego przepisy Parcours de Chasse – Sporting™ wymagają od stóp przed komendą?", "options": ["Obie stopy wewnątrz stanowiska", "Przednia stopa na linii stanowiska", "Stopy złączone", "Żadnych wymagań"], "answer": 0, "why": "Przepis o pozycji gotowości wymaga, by obie stopy były wewnątrz stanowiska strzeleckiego 1 m, zanim strzelec zawoła rzutek."}, {"q": "Strzelec leworęczny. Trener mówi „Open your front foot”. O którą stopę chodzi?", "options": ["Zawsze lewą, niezależnie od ręki", "Prawą: to przednia stopa leworęcznego", "Tylną, bliższą wyrzutni", "Obie stopy razem"], "answer": 1, "why": "U leworęcznego przednią stopą jest prawa. Tłumaczenie „front foot” jako „przednia noga” pozwala uniknąć błędu."}]}, {"id": "basics-mount", "minutes": 6, "title": "Pozycja gotowości i złożenie się do strzału", "body": ["W Parcours de Chasse – Sporting™ start jest z bronią opuszczoną. Przed komendą stopka kolby dotyka ciała, a górny tylny koniec kolby pozostaje poniżej linii na kamizelce, 25 cm pod osią barków, w kontrastowym kolorze. Strzelec utrzymuje tę pozycję, aż rzutek zostanie wyrzucony i będzie widoczny. Wcześniejsze złożenie się kończy się ustnym ostrzeżeniem z żółtą kartką; powtórzenie na tej samej osi oznacza czerwoną kartkę, a rzutek jest liczony jako chybiony (zero).", "W Compak® Sporting pozycja broni w chwili komendy jest dowolna, więc broń może być już przyłożona do ramienia. W obu dyscyplinach do każdego rzutka strzela się z bronią przy ramieniu, a w Sporting™ pozycja broni między dwoma rzutkami dubletu jest dowolna.", "Złożenie się do strzału (gun mount) to podniesienie broni do policzka i ramienia. Trenerzy uczą „muzzles first” — najpierw lufy: przednia ręka zaczyna prowadzić wyloty luf wzdłuż linii rzutka, kolba unosi się do policzka i wchodzi w zagłębienie barku, gdy broń łapie linię. „Move, mount, shoot” — ruch, złożenie, strzał — to jeden płynny ciąg. Broń idzie do twarzy, a nie twarz do broni; policzek zostaje na grzbiecie kolby (comb), bo oko jest szczerbiną.", "Brytyjski trener może powiedzieć „gun up” albo „pre-mount this one” — tego złóż się wcześniej. Na zawodach FITASC Sporting™ jest to niedozwolone, w Compak® Sporting normalne, a na treningu to tylko ćwiczenie. Składanie się i prowadzenie broni po wyobrażonej linii przed komendą (mock shooting, ćwiczenia celowania) jest w Sporting™ zabronione: najpierw ostrzeżenie, potem zero."], "key_points": ["Sporting™: kolba poniżej linii na kamizelce (25 cm pod osią barków), aż rzutek będzie widoczny.", "Za wczesne złożenie: żółta kartka, potem czerwona kartka i stracony rzutek na tej samej osi.", "Compak® Sporting: dowolna pozycja broni przy komendzie; strzał zawsze z ramienia.", "Najpierw lufy, broń do twarzy, policzek na grzbiecie kolby: ruch, złożenie, strzał.", "„Pre-mount” to ćwiczenie treningowe, nigdy na zawodach FITASC Sporting™."], "terms": ["ready-position", "jacket-line", "gun-mount", "move-mount-shoot", "comb", "yellow-card", "mock-shooting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-lr", "focus": "mount"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Gun to your face, not your face to the gun.", "meaning": "Unieś kolbę do policzka; nie opuszczaj głowy do broni.", "say": "Broń do twarzy, nie twarz do broni."}, {"en": "Muzzles first — move, mount, shoot.", "meaning": "Zacznij prowadzić lufy z rzutkiem, złóż się w trakcie ruchu, strzelaj, gdy złożenie jest zakończone.", "say": "Najpierw lufy — ruch, złożenie, strzał."}, {"en": "Your mount's late and too fast — start it with the front hand.", "meaning": "Broń idzie w górę za późno i szarpnięciem; przednia ręka powinna wcześniej prowadzić ruch.", "say": "Składasz się za późno i za szybko — zaczynaj przednią ręką."}, {"en": "Low gun on this one, like in competition.", "meaning": "Zacznij z kolbą poniżej linii na kamizelce, jak wymagają przepisy FITASC Sporting™.", "say": "Ten z bronią opuszczoną, jak na zawodach."}], "quiz": [{"q": "W Parcours de Chasse – Sporting™ do kiedy kolba musi pozostać poniżej linii na kamizelce?", "options": ["Aż strzelec zawoła rzutek", "Aż sędzia skinie głową", "Aż rzutek zostanie wyrzucony i będzie widoczny", "Aż padnie pierwszy strzał"], "answer": 2, "why": "Pozycję gotowości utrzymuje się, dopóki rzutek nie zostanie wyrzucony i nie będzie go widać; dopiero wtedy wolno złożyć się do strzału."}, {"q": "Czy w Compak® Sporting strzelec może zawołać rzutek z bronią już przy ramieniu?", "options": ["Nie: dostaje za to żółtą kartkę", "Tylko przy rabbitach i innych niskich rzutkach", "Tylko między dwoma rzutkami dubletu", "Tak: pozycja broni przy komendzie jest dowolna"], "answer": 3, "why": "Compak® Sporting nie ma przepisu o opuszczonej broni: przy komendzie broń może być złożona lub nie, ale do każdego rzutka strzela się z ramienia."}, {"q": "Dlaczego trenerzy nalegają, by policzek pozostawał na grzbiecie kolby?", "options": ["Oko jest szczerbiną, więc musi być zawsze w tym samym miejscu", "Aby zmniejszyć hałas docierający do ucha", "Bo wymagają tego przepisy obu dyscyplin", "Aby ukryć twarz przed sędzią"], "answer": 0, "why": "Strzelba nie ma szczerbiny: celownikiem jest oko nad szyną, więc uniesiony policzek posyła śrut za wysoko."}]}, {"id": "basics-eyes", "minutes": 5, "title": "Oczy: dominacja, oboje oczu otwarte, ostre skupienie", "body": ["Większość ludzi ma oko dominujące (master eye), któremu mózg bardziej ufa — zwykle po tej samej stronie co ręka dominująca. To oko dominujące musi patrzeć wzdłuż szyny celowniczej. Dominacja skrzyżowana (cross-dominance) oznacza, że oko dominujące jest po przeciwnej stronie niż ramię strzeleckie; widzenie centralne oznacza, że żadne oko wyraźnie nie dominuje. W obu przypadkach broń wskazuje inaczej, niż strzelec się spodziewa, często w bok.", "Prosty test: przy obojgu oczach otwartych obejmij odległy przedmiot małym trójkątem z dłoni, a potem zamykaj po kolei każde oko; oko, przy którym przedmiot zostaje w trójkącie, jest dominujące. Trener może też stanąć przed strzelcem i spojrzeć przez trójkąt.", "Rozwiązania, które wybiera trener: zamknięcie lub przymrużenie drugiego oka podczas składania się; mała kropka na okularach strzeleckich; nauka strzelania z drugiego ramienia; rzadziej kolba z odchyleniem krzyżowym (cross-over). Tam, gdzie to możliwe, preferuje się oboje oczu otwarte, bo dwoje oczu lepiej ocenia prędkość, kąt i odległość.", "Skupienie wzroku: miękkie, szerokie spojrzenie podczas czekania w punkcie podjęcia rzutka, potem ostre skupienie na samym rzutku, najlepiej na jego przedniej krawędzi. Spoglądanie z powrotem na lufę lub muszkę, by sprawdzić wyprzedzenie, zatrzymuje broń.", "Okulary strzeleckie są obowiązkowe dla strzelców w obu dyscyplinach, więc kropkę nakleja się właśnie na nie."], "key_points": ["Oko dominujące musi patrzeć wzdłuż szyny.", "Dominacja skrzyżowana i widzenie centralne sprawiają, że broń wskazuje obok rzutka.", "Test trójkątem z dłoni; rozwiązanie wybiera trener.", "Miękkie spojrzenie przy podjęciu, ostre skupienie na przedniej krawędzi; nigdy nie spoglądaj na muszkę.", "Okulary strzeleckie są obowiązkowe w obu dyscyplinach."], "terms": ["eye-dominance", "master-eye", "cross-dominance", "central-vision", "soft-focus", "hard-focus", "leading-edge", "safety-glasses"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "Paragon School — Eye dominance testing", "url": "https://www.paragonschool.com/blog-post/eye-dominance-testing-and-issues-in-sporting-clays-skeet-and-trap-go-slowly-please"}, {"title": "Shotgun Life — How to shoot a chandelle target (focus on the leading edge)", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}], "sim": {"type": "flight", "preset": "going-away", "focus": "eyes"}, "rule_refs": [{"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}], "coach_says": [{"en": "Close your left eye as the gun comes up.", "meaning": "Zamknij lewe oko w trakcie składania się, nie wcześniej, żeby broń prowadziło prawe oko.", "say": "Zamknij lewe oko, kiedy broń idzie w górę."}, {"en": "Eyes on the clay, not the barrel.", "meaning": "Patrz cały czas na rzutek; sprawdzanie lufy zatrzymuje broń.", "say": "Oczy na rzutku, nie na lufie."}, {"en": "Look at the leading edge.", "meaning": "Skup wzrok na przedniej krawędzi lecącego rzutka, nie na jego środku.", "say": "Patrz na przednią krawędź."}, {"en": "Don't look at the trap — look out to your pick-up point.", "meaning": "Czekaj ze wzrokiem nieco dalej na linii lotu, tam gdzie rzutek widać wyraźnie po raz pierwszy.", "say": "Nie patrz na wyrzutnię — patrz dalej, na punkt podjęcia."}], "quiz": [{"q": "Praworęczny strzelec ma dominujące lewe oko. Jak to się nazywa?", "options": ["Widzenie centralne", "Ostre skupienie", "Dominacja skrzyżowana", "Przednia krawędź"], "answer": 2, "why": "Dominacja skrzyżowana to oko dominujące po stronie przeciwnej do ramienia strzeleckiego."}, {"q": "Dlaczego spoglądanie na muszkę, by sprawdzić wyprzedzenie, jest błędem?", "options": ["Zabraniają tego przepisy", "Zatrzymuje broń i śrut idzie za rzutek", "Muszka odbija słońce", "Rzutek zmienia przez to kolor"], "answer": 1, "why": "Gdy wzrok przenosi się na broń, ruch się zatrzymuje, a rzutek przechodzi na obrzeże pola widzenia, więc śrut idzie za rzutek."}, {"q": "Gdzie zwykle nakleja się kropkę na dominację oka?", "options": ["Na okulary strzeleckie, przed okiem, które trzeba wyłączyć", "Na muszkę na końcu szyny", "Na szynę, w połowie jej długości", "Na linię na kamizelce, poniżej barku"], "answer": 0, "why": "Okulary strzeleckie i tak są obowiązkowe, więc mała kropka na szkle przed okiem niedominującym jest najprostszym rozwiązaniem."}]}, {"id": "basics-three-points", "minutes": 5, "title": "Punkt podjęcia, punkt wyjściowy i punkt strzału: plan na stanowisko", "body": ["Przed każdym rzutkiem strzelec ustala trzy punkty. Punkt podjęcia rzutka (pick-up point) to miejsce, w którym oczy po raz pierwszy wyraźnie widzą rzutek — nieco dalej od wyrzutni, a nie przy jej wylocie, gdzie rzutek jest tylko smugą. Punkt wyjściowy lufy (hold point) to miejsce, w którym czekają wyloty luf przy komendzie, zwykle na linii lotu rzutka lub tuż pod nią, między punktem podjęcia a punktem strzału. Punkt strzału (break point) to miejsce, w którym strzelec zamierza rozbić rzutek.", "Kolejność planowania: najpierw wybierz punkt strzału, ustaw pod niego stopy, skręć się z powrotem do punktu wyjściowego lufy, a potem skieruj oczy na punkt podjęcia. W Parcours de Chasse – Sporting™ kolba jest opuszczona, dopóki rzutek się nie pojawi, więc punkt wyjściowy oznacza tam, gdzie wskazują wyloty luf przy opuszczonej broni.", "Typowe błędy: punkt strzału za daleko oznacza szybki, niekontrolowany ruch broni albo rzutek, który już opada; za blisko — za mało ruchu i „dźgnięcie” bronią (poke). Punkt wyjściowy zbyt blisko wyrzutni zmusza broń do gonienia rzutka; zbyt daleko — rzutek wyprzedza broń.", "Rzutki odczytuje się podczas pokazu. W Sporting™ wszystkie tory lotu pokazuje się pierwszemu strzelcowi, a na prośbę sędzia powtarza pokaz — maksymalnie dwa rzutki dla każdego rzutka z menu; w Compak® Sporting w grupach rzutki pojedyncze pokazuje się raz rano, pierwszej grupie. Rzutek musi zostać rozbity tam, gdzie sędzia może go widzieć, w granicy strzelania.", "„Where are you taking it?” to pytanie o punkt strzału; „kill point” to neutralny synonim."], "key_points": ["Podjęcie = oczy; punkt wyjściowy = wyloty luf; punkt strzału = gdzie rzutek zostaje rozbity.", "Planuj od punktu strzału wstecz: stopy, punkt wyjściowy, oczy.", "Punkt wyjściowy jest zwykle między podjęciem a punktem strzału, na linii lub tuż pod nią.", "Odczytuj rzutki podczas pokazu; rozbijaj je tam, gdzie widzi je sędzia.", "„Where are you taking it?” = gdzie masz punkt strzału?"], "terms": ["pick-up-point", "hold-point", "break-point", "target-presentation", "shooting-limit", "target-line"], "sources": [{"title": "Shotgun Life — The proper hold point for sporting clays", "url": "https://www.shotgunlife.com/briefs/what-is-the-proper-hold-point-for-shooting-sporting-clays.html"}, {"title": "Clay Target Instruction — Hold point", "url": "https://claytargetinstruction.com/articles/hold-point/"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "flight", "preset": "quartering-away", "focus": "points"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}], "coach_says": [{"en": "Where are you taking it?", "meaning": "Trener pyta, gdzie strzelec zamierza rozbić rzutek.", "say": "Gdzie go bierzesz?"}, {"en": "Move your hold point halfway back to the trap.", "meaning": "Trzymaj wyloty luf bliżej wyrzutni, w połowie obecnej odległości.", "say": "Przesuń punkt wyjściowy o połowę bliżej wyrzutni."}, {"en": "Look further out — pick it up where it's sharp.", "meaning": "Przenieś wzrok dalej od wyrzutni, tam gdzie rzutek widać wyraźnie po raz pierwszy.", "say": "Patrz dalej — podejmuj go tam, gdzie jest ostry."}, {"en": "Hold a little lower, just under the line.", "meaning": "Przy komendzie trzymaj wyloty luf nieco poniżej toru lotu rzutka.", "say": "Trzymaj trochę niżej, tuż pod linią."}], "quiz": [{"q": "Który punkt dotyczy oczu, a nie broni?", "options": ["Punkt wyjściowy lufy", "Punkt strzału", "Punkt podjęcia rzutka", "Punkt wejścia"], "answer": 2, "why": "Punkt podjęcia to miejsce, w którym oczy po raz pierwszy wyraźnie widzą rzutek; punkt wyjściowy dotyczy wylotów luf."}, {"q": "Co zwykle się dzieje, gdy punkt wyjściowy lufy jest zbyt blisko wyrzutni?", "options": ["Rzutek wyprzedza broń", "Sędzia ogłasza No Bird", "Broń musi gonić rzutek", "Rzutek zwalnia"], "answer": 2, "why": "Zbyt blisko wyrzutni rzutek mija wyloty luf z pełną prędkością i strzelec musi go gonić."}, {"q": "W Parcours de Chasse – Sporting™ strzelec na stanowisku prosi o ponowny pokaz. Ile maksymalnie rzutków na każdy rzutek z menu?", "options": ["Dwa rzutki", "Żadnego: powtórki są niedozwolone", "Ile zechce", "Dokładnie pięć"], "answer": 0, "why": "Sędzia powtarza pokaz na prośbę, maksymalnie dwa rzutki dla każdego rzutka z menu."}]}, {"id": "basics-follow-through", "minutes": 5, "title": "Prowadzenie broni po strzale, prędkość broni i tempo", "body": ["Prowadzenie broni po strzale (follow-through) oznacza, że broń dalej porusza się wzdłuż linii rzutka po naciśnięciu spustu, jak przy zamachu w golfie czy tenisie. Między decyzją o strzale a wylotem śrutu z luf jest małe opóźnienie; jeśli broń zatrzyma się przy spuście, śrut idzie za rzutek. Trenerzy obserwują wyloty luf po strzale: jeśli zamierają lub opadają, prowadzenia po strzale zabrakło.", "Prędkość broni to szybkość ruchu wylotów luf w porównaniu z rzutkiem i to ona wyznacza metodę wyprzedzenia: ta sama prędkość co rzutek to stałe wyprzedzenie (maintained lead); szybciej niż rzutek to przeciągnięcie (swing-through); ta sama prędkość, a potem krótkie przyspieszenie, to pull-away. Broń zbyt wolna zostaje z tyłu; zbyt szybka, mówią trenerzy, wyskakuje za daleko, a strzelec często ją wtedy zatrzymuje.", "Tempo to szybkość wykonania całego strzału; rytm to jego równomierność. Szybki, bliski rzutek wymaga szybkiego tempa, długi, wolny rzutek poprzeczny (crosser) — spokojniejszego, ale rytm pozostaje płynny. Wielu trenerów mówi, że strzelcy z jednym tempem na wszystko tracą rzutki, które wymagają przeciwnego.", "„Stay in the gun” — zostań w broni: policzek na kolbie i oczy na rzutku, aż pęknie. To także utrzymuje strzelca w gotowości do drugiego strzału, bo do rzutka pojedynczego można oddać dwa strzały.", "Tłumacz „finish the shot” jako kontynuowanie ruchu, a nie jego zatrzymanie."], "key_points": ["Prowadzenie po strzale: broń porusza się dalej po spuście; zatrzymanie posyła śrut za rzutek.", "Prędkość broni wyznacza metodę: równa (maintained), szybsza (swing-through), równa, potem szybsza (pull-away).", "Tempo = szybkość całego strzału; rytm = jego równomierność.", "Zostań w broni: gotowość do drugiego strzału przy rzutku pojedynczym.", "„Finish the shot” = kontynuuj ruch."], "terms": ["follow-through", "gun-speed", "tempo", "stopping-the-gun", "maintained-lead", "swing-through", "pull-away", "single-target"], "sources": [{"title": "Shooting UK — The overhead clay from behind (follow-through)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "focus": "follow-through"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "Follow through — the gun keeps moving after the bang.", "meaning": "Nie zatrzymuj ruchu broni w chwili strzału.", "say": "Prowadź dalej — broń jedzie dalej po huku."}, {"en": "You stopped the gun.", "meaning": "Wyloty luf zatrzymały się przy spuście, więc śrut poszedł za rzutek.", "say": "Zatrzymałeś broń."}, {"en": "Match the speed of the bird — you're racing it.", "meaning": "Broń porusza się dużo szybciej niż rzutek; ruszaj się z prędkością rzutka.", "say": "Dopasuj się do prędkości rzutka — ścigasz się z nim."}, {"en": "Slow the tempo down, this one gives you lots of time.", "meaning": "Rzutek jest wolny albo długi, więc cały ruch może być spokojniejszy.", "say": "Zwolnij tempo, przy tym masz mnóstwo czasu."}, {"en": "Stay in the gun until you see it break.", "meaning": "Trzymaj policzek na kolbie i oczy na rzutku, aż pęknie.", "say": "Zostań w broni, aż zobaczysz, że pękł."}], "quiz": [{"q": "Trener mówi „You stopped the gun”. Gdzie najpewniej poszedł śrut?", "options": ["Przed rzutek", "Nad rzutek", "Dokładnie w rzutek", "Za rzutek"], "answer": 3, "why": "Rzutek leci dalej, a zatrzymana broń nie, więc śrut przechodzi za nim."}, {"q": "Jaka prędkość broni opisuje stałe wyprzedzenie (maintained lead)?", "options": ["Dużo większa niż rzutka", "Taka sama jak rzutka", "Zerowa: broń czeka", "Mniejsza niż rzutka"], "answer": 1, "why": "Przy stałym wyprzedzeniu wyloty luf poruszają się z prędkością rzutka, utrzymując stały odstęp. Broń czekająca to zasadzka (ambush); szybsza to przeciągnięcie (swing-through)."}, {"q": "Jaka jest różnica między tempem a rytmem?", "options": ["Tempo to szybkość strzału, rytm to jego równomierność", "To dwa słowa na to samo", "Tempo to muzyka grana na strzelnicy", "Rytm to limit czasu między rzutkami"], "answer": 0, "why": "Trenerzy zmieniają tempo dla każdego rzutka, zachowując płynny rytm, więc oba słowa tłumacz osobno."}]}]}, {"id": "lead", "icon": "lead", "title": "Wyprzedzenie (lead) i metody strzelania", "intro": "O wyprzedzeniu trenerzy mówią najwięcej: dlaczego broń musi wskazywać przed lecącym rzutkiem, cztery sposoby, by się tam znaleźć, i dziwne jednostki, którymi je opisują. Ta misja pokazuje każdą metodę krok po kroku i uczy tłumaczyć „four foot”, „half a bird” czy „double it” bez zmiany sensu.", "lessons": [{"id": "lead-why", "minutes": 6, "title": "Po co jest wyprzedzenie: rzeczywiste i widziane", "body": ["Śrut potrzebuje ułamka sekundy, by dolecieć do rzutka, a w tym czasie rzutek leci dalej. Broń wycelowana prosto w rzutek poprzeczny strzela więc za nim. Broń musi wskazywać przed rzutek, żeby śrut i rzutek się spotkały. Ten odstęp to wyprzedzenie (lead), w brytyjskim angielskim także „forward allowance”.", "Wyprzedzenie rośnie z prędkością rzutka, jego odległością i kątem. Pełny rzutek poprzeczny wymaga go najwięcej; rzutek lecący prosto na strzelca lub od niego nie wymaga prawie żadnego wyprzedzenia w bok, choć rzutki wznoszące i opadające wymagają wyprzedzenia w pionie (nad lub pod).", "Prawdziwe liczby zaskakują. Jeden serwis strzelecki podaje około 3–4 stóp, czyli mniej więcej metr, rzeczywistego wyprzedzenia dla rzutka poprzecznego w odległości ok. 21–25 jardów (około 20 m). Wielu strzelców mówi, że rośnie ono mniej więcej proporcjonalnie do odległości, więc ten sam mały odstęp przy wylocie lufy oznacza dużo większe rzeczywiste wyprzedzenie na dalekim rzutku.", "Rzeczywiste wyprzedzenie (actual lead) to prawdziwa odległość przed rzutkiem w powietrzu. Wyprzedzenie widziane (perceived lead, „lead picture” lub „sight picture”) to odstęp, który strzelec widzi między wylotem lufy a rzutkiem. Metr na 20 m wygląda przy wylocie lufy jak kilka centymetrów. Metoda zmienia obraz: strzelec stosujący stałe wyprzedzenie widzi największy odstęp, a strzelec stosujący przeciągnięcie (swing-through) niewielki lub żaden, bo prędkość broni dodaje wyprzedzenia.", "Pewien amerykański instruktor zauważa, że praworęczny strzelec często ma wrażenie, iż rzutek poprzeczny z lewej na prawą wymaga większego wyprzedzenia niż z prawej na lewą; rzeczywiste wyprzedzenie jest takie samo, różni się tylko odbiór. Dlatego „cztery stopy” trenera opisują jego obraz, a nie pomiar."], "key_points": ["Wyprzedzenie istnieje, bo rzutek leci, gdy śrut jest w drodze.", "Większa prędkość, odległość i kąt = większe wyprzedzenie.", "Rzeczywiste wyprzedzenie (w powietrzu) jest dużo większe niż widziane (przy wylocie lufy).", "Metoda zmienia obraz: przy stałym wyprzedzeniu widać najwięcej, przy przeciągnięciu najmniej.", "Liczba podana przez trenera to obraz, a nie pomiar."], "terms": ["lead", "perceived-lead", "crosser", "gun-speed", "maintained-lead", "swing-through"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "focus": "perceived-vs-actual"}, "rule_refs": [], "coach_says": [{"en": "Forget the real distance — what matters is your picture.", "meaning": "Nie myśl w metrach w powietrzu; zapamiętaj odstęp przy wylocie lufy, który widziałeś, gdy trafiłeś.", "say": "Zapomnij o rzeczywistej odległości — liczy się twój obraz."}, {"en": "That's the picture — remember it.", "meaning": "Przy tym trafieniu wyprzedzenie było dobre; zachowaj ten sam obraz.", "say": "To jest ten obraz — zapamiętaj go."}, {"en": "Same lead on the right-to-left, it only looks different.", "meaning": "Rzeczywiste wyprzedzenie jest równe w obu kierunkach; zmienia się tylko odbiór.", "say": "Na tym z prawej na lewą to samo wyprzedzenie, tylko wygląda inaczej."}], "quiz": [{"q": "Co to jest wyprzedzenie widziane (perceived lead)?", "options": ["Prawdziwa odległość przed rzutkiem w powietrzu", "Odstęp, który strzelec widzi między wylotem lufy a rzutkiem", "Wyprzedzenie zapisane w menu rzutków", "Odległość od stanowiska do wyrzutni"], "answer": 1, "why": "Wyprzedzenie widziane to obraz przy wylocie lufy; rzeczywiste to prawdziwa odległość w powietrzu i jest dużo większe."}, {"q": "Przy której metodzie wyprzedzenie widziane jest zwykle największe?", "options": ["Przeciągnięcie (swing-through)", "Pull-away", "Stałe wyprzedzenie (maintained lead)", "Przy wszystkich jest identyczne"], "answer": 2, "why": "Przy stałym wyprzedzeniu broń porusza się z prędkością rzutka i prędkość broni nic nie dodaje, więc strzelec musi zobaczyć cały odstęp."}, {"q": "Który rzutek nie wymaga prawie żadnego wyprzedzenia w bok?", "options": ["Rzutek odlatujący prosto", "Daleki rzutek poprzeczny", "Rzutek skośny odlatujący pod kątem 45°", "Rzutek poprzeczny na 40 m"], "answer": 0, "why": "Rzutek odlatujący prosto nie porusza się w bok; jeśli potrzebuje wyprzedzenia, to w pionie."}]}, {"id": "lead-maintained", "minutes": 5, "title": "Stałe wyprzedzenie: wyjdź przed rzutek i zostań przed nim", "body": ["Stałe wyprzedzenie (maintained lead; w USA sustained lead) utrzymuje wyloty luf przed rzutkiem od początku aż do strzału.", "Jak to wygląda krok po kroku na rzutku poprzecznym. 1) Start: wyloty luf czekają w punkcie wyjściowym daleko na linii lotu, przed miejscem, którędy przeleci rzutek; oczy patrzą z powrotem w stronę punktu podjęcia. 2) Wejście: gdy rzutek nadlatuje, broń rusza, a wyloty luf wchodzą na linię przed nim, nigdy za nim; to punkt wejścia (insertion point). 3) Prowadzenie: wyloty luf poruszają się z prędkością rzutka, więc odstęp się nie zmienia. 4) Strzał: spust naciska się, gdy odstęp jest właściwy, a broń wciąż się porusza. 5) Broń porusza się dalej po strzale.", "Zalety: precyzja, mało ruchu bronią, szybkość między rzutkami, łatwa korekta wyprzedzenia. Pasuje do regularnych, przewidywalnych rzutków: dalekich poprzecznych, równych wysokich rzutków.", "Wady: najtrudniejsza metoda do nauczenia; strzelec musi z góry znać prędkość i linię rzutka; a ponieważ broń nie jest szybsza od rzutka, strzelec widzi największy odstęp i kusi go, by go mierzyć, zwolnić i zatrzymać broń.", "Trenerzy mówią „insert the gun in front” (wprowadź broń przed rzutek), „stay ahead of it” (zostań przed nim), „match its speed” (dopasuj się do jego prędkości)."], "key_points": ["Wyloty luf startują przed rzutkiem i wchodzą na linię przed nim.", "Prędkość broni = prędkość rzutka; odstęp pozostaje stały.", "Spust, gdy odstęp jest właściwy, a broń w ruchu; potem prowadzenie po strzale.", "Najlepsze na dalekie, przewidywalne rzutki.", "Główne ryzyko: mierzenie odstępu i zatrzymanie broni."], "terms": ["maintained-lead", "insertion-point", "hold-point", "gun-speed", "follow-through", "crosser"], "sources": [{"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shotgun Sports USA — How to read sporting clays targets (insertion point)", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "muzzle_start": "ahead", "gun_speed": "equal", "trigger": "gap-held", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Get in front and stay in front.", "meaning": "Ustaw wyloty luf przed rzutkiem i trzymaj je tam aż do chwili po strzale.", "say": "Wyjdź przed niego i zostań przed nim."}, {"en": "Your insertion point is behind the bird — put the gun in front of it.", "meaning": "Wyloty luf weszły na linię za rzutkiem; muszą wejść przed nim.", "say": "Twój punkt wejścia jest za rzutkiem — wprowadź broń przed niego."}, {"en": "Match its speed — don't let it catch you.", "meaning": "Prowadź broń z prędkością rzutka, żeby odstęp się nie zmniejszał.", "say": "Dopasuj się do jego prędkości — nie daj mu się dogonić."}, {"en": "You're measuring it — trust the picture and pull.", "meaning": "Strzelec zwalnia, żeby sprawdzić odstęp; strzelaj, gdy tylko obraz jest właściwy.", "say": "Mierzysz go — zaufaj obrazowi i strzelaj."}], "quiz": [{"q": "Przy stałym wyprzedzeniu gdzie wyloty luf wchodzą na linię lotu rzutka?", "options": ["Za rzutkiem", "Na rzutku", "Przed rzutkiem", "Poniżej wyrzutni"], "answer": 2, "why": "Wyloty luf wprowadza się przed rzutek i tam pozostają; za rzutkiem to przeciągnięcie, na rzutku to pull-away."}, {"q": "Jaki jest typowy błąd strzelców stosujących stałe wyprzedzenie?", "options": ["Start zbyt daleko za rzutkiem", "Mierzenie odstępu i zatrzymanie broni", "Złożenie z biodra", "Strzał za wcześnie, przy wyrzutni"], "answer": 1, "why": "Odstęp jest duży i widoczny, więc strzelców kusi, by go sprawdzać; broń zwalnia lub się zatrzymuje i śrut idzie za rzutek."}, {"q": "Na jaki rzutek często zaleca się stałe wyprzedzenie?", "options": ["Daleki, przewidywalny rzutek poprzeczny", "Podskakujący rabbit w krótkiej luce", "Niespodziewany rzutek zza pleców", "Rzutek ZZ"], "answer": 0, "why": "Metoda wymaga znanej prędkości i linii, które dają dalekie, równe rzutki poprzeczne; nieregularne lub niespodziewane rzutki pasują do innych metod."}]}, {"id": "lead-swing-through", "minutes": 5, "title": "Przeciągnięcie: od tyłu, przez rzutek", "body": ["Przy przeciągnięciu (swing-through) wyloty luf startują za rzutkiem i go wyprzedzają. Po polsku usłyszysz „przeciągnięcie” albo po prostu „swing through”.", "Jak to wygląda krok po kroku. 1) Start: wyloty luf wchodzą na linię rzutka za nim, na jego „ogonie”. 2) Wyprzedzanie: broń porusza się szybciej niż rzutek, wzdłuż jego linii, przez jego „ciało”. 3) Strzał: spust naciska się, gdy wyloty luf mijają przód rzutka, tuż przed nim. Ponieważ między decyzją a strzałem jest małe opóźnienie, a broń porusza się szybciej niż rzutek, wyloty luf są już dalej z przodu, gdy śrut wylatuje: rzeczywiste wyprzedzenie w chwili strzału jest większe niż to, które widzi strzelec, a odstęp jest niewielki lub żaden. 4) Ruch broni trwa po strzale. Mnemotechnika to „butt, belly, beak, bang”: ogon, brzuch, dziób, strzał. W brytyjskim angielskim możesz usłyszeć „bum” zamiast „butt”; tłumacz to jako „ogon”.", "Zalety: naturalna i szybka; dobra dla początkujących, na bliskie szybkie rzutki, na rzutki driven i nad głową oraz na rzutki nieregularne lub niespodziewane.", "Wady: bardzo krótkie okno na spust; na dalekich rzutkach poprzecznych strzelcowi może zabraknąć czasu, może zgubić linię albo przestrzelić; zwolnienie, gdy wyloty luf dochodzą do rzutka, daje pudło za rzutkiem.", "Źródła nie zgadzają się co do nazwy „metoda CPSA”: niektóre opisują nią przeciągnięcie, a o dzisiejszym szkoleniu CPSA pisze się, że uczy pull-away. Jeśli trener mówi „CPSA method”, zapytaj, którą metodę ma na myśli."], "key_points": ["Wyloty luf startują za rzutkiem, na jego linii.", "Broń szybsza od rzutka: ogon, brzuch, dziób, strzał.", "Spust, gdy wyloty luf mijają przód; rzeczywiste wyprzedzenie jest większe niż widziane.", "Dobre na bliskie, szybkie, driven i niespodziewane rzutki; trudniejsze na dalekich poprzecznych.", "„Metoda CPSA” jest dwuznaczna: zapytaj, o którą metodę chodzi."], "terms": ["swing-through", "gun-speed", "perceived-lead", "driven-target", "overhead", "follow-through"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}], "sim": {"type": "lead", "method": "swing-through", "preset": "crosser-lr", "muzzle_start": "behind", "gun_speed": "faster", "trigger": "passing-front", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Come from behind, through the bird, and shoot as you see daylight.", "meaning": "Zacznij za rzutkiem, przejdź przez niego i strzelaj, gdy pojawi się odstęp z przodu.", "say": "Wejdź od tyłu, przez rzutek, i strzelaj, gdy zobaczysz prześwit."}, {"en": "Butt, belly, beak, bang.", "meaning": "Mnemotechnika: ogon, brzuch, przód rzutka, potem strzał.", "say": "Ogon, brzuch, dziób, strzał."}, {"en": "You slowed down as you got to it.", "meaning": "Broń straciła prędkość, gdy doszła do rzutka, więc śrut poszedł za nim.", "say": "Zwolniłeś, kiedy do niego doszedłeś."}, {"en": "Brush it out and keep going.", "meaning": "Przejdź przez rzutek, jakbyś ścierał go z nieba, bez zatrzymywania.", "say": "Zetrzyj go z nieba i jedź dalej."}], "quiz": [{"q": "Gdzie startują wyloty luf przy przeciągnięciu (swing-through)?", "options": ["Przed rzutkiem", "Na przedniej krawędzi rzutka", "W stałym punkcie w punkcie strzału", "Za rzutkiem, na jego linii"], "answer": 3, "why": "Przeciągnięcie zaczyna się za rzutkiem i go wyprzedza; start przed rzutkiem to stałe wyprzedzenie, stały punkt to zasadzka (ambush)."}, {"q": "Dlaczego strzelec stosujący przeciągnięcie widzi niewielkie wyprzedzenie albo żadne?", "options": ["Rzutki są zawsze wolniejsze", "Wyprzedzenie tworzy prędkość broni", "Przepisy zabraniają widocznego odstępu", "Strzelec zamyka oboje oczu"], "answer": 1, "why": "Broń porusza się szybciej niż rzutek, więc między decyzją a strzałem sama wychodzi do przodu."}, {"q": "Trener mówi „bum, belly, beak, bang”. Jak przetłumaczyć „bum”?", "options": ["Jako „ogon” (tail)", "Dosadnym słowem, dosłownie", "Jako „bum” (dźwięk)", "Całkowicie pominąć"], "answer": 0, "why": "Chodzi o ogon rzutka; neutralny „ogon” zachowuje sens i rytm mnemotechniki."}]}, {"id": "lead-pull-away", "minutes": 5, "title": "Pull-away: na nim, z nim, wyjdź przed, strzał", "body": ["Przy pull-away (po polsku czasem „odejście od rzutka”) wyloty luf najpierw wchodzą na rzutek, a potem wychodzą przed niego. Ta metoda jest powszechnie nauczana we współczesnym szkoleniu brytyjskim i dziś często nazywa się ją metodą CPSA.", "Jak to wygląda krok po kroku. 1) „On it” — na nim: broń składa się na rzutek lub jego przednią krawędź; wyloty luf dotykają go na jego linii. 2) „With it” — z nim: wyloty luf przez chwilę prowadzą rzutek z jego prędkością, dopasowując linię i tempo. 3) „Pull away” — wyjdź przed: broń płynnie przyspiesza do przodu, aż pojawi się właściwy obraz wyprzedzenia. 4) „Shoot” — strzał: spust naciska się, gdy broń wciąż przyspiesza lub się porusza. 5) Prowadzenie po strzale: broń jedzie dalej po strzale.", "Zalety: najpierw prowadzenie rzutka pozwala strzelcowi ocenić jego prędkość, odległość i linię, zanim się zdecyduje, więc linia jest dobra. Pasuje do dalekich rzutków, rzutków skośnych i wznoszących. Dzięki przyspieszeniu wyprzedzenie widziane jest mniejsze niż przy stałym wyprzedzeniu.", "Wady: wielkość przyspieszenia zmienia się od rzutka do rzutka, więc wyczucie go wymaga praktyki; zbyt długie prowadzenie zamienia się w „riding the target” (prowadzenie za długo), a przerwanie wypychania daje pudło za rzutkiem.", "Trenerzy mówią „touch it and go” (dotknij i jedź), „mount on it and push out” (złóż się na niego i wypchnij do przodu) albo czterotaktowe „on it, with it, pull away, shoot”. Tłumacząc, zachowaj czterotaktowy rytm: jest ważniejszy niż dokładne słowa."], "key_points": ["Wyloty luf startują na rzutku (lub jego przedniej krawędzi).", "Prowadź z jego prędkością, potem przyspiesz przed niego.", "Spust, gdy broń wciąż porusza się do przodu; potem prowadzenie po strzale.", "Dobra kontrola linii; pasuje do dalekich, skośnych i wznoszących rzutków.", "Tłumacząc, zachowaj czterotaktowy rytm."], "terms": ["pull-away", "insertion-point", "gun-speed", "perceived-lead", "quartering-away", "follow-through"], "sources": [{"title": "CPSA — How to hit series (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/how-to-hit-series-3"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "muzzle_start": "on-target", "gun_speed": "equal-then-faster", "trigger": "during-acceleration", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "On it, with it, pull away, shoot.", "meaning": "Wejdź na rzutek, prowadź go, przyspiesz przed niego, strzelaj.", "say": "Na nim, z nim, wyjdź przed, strzał."}, {"en": "Touch it and go.", "meaning": "Spotkaj rzutek wylotami luf i od razu zacznij wychodzić przed niego.", "say": "Dotknij i jedź."}, {"en": "You rode it too long.", "meaning": "Strzelec prowadził rzutek za długo, zanim wyszedł przed niego, i zgubił linię lub moment.", "say": "Prowadziłeś go za długo."}, {"en": "Mount on it and push out a bit more.", "meaning": "Złóż się na rzutek, a potem przed strzałem wyjdź trochę dalej przed niego.", "say": "Złóż się na niego i wypchnij trochę bardziej do przodu."}], "quiz": [{"q": "Co przy pull-away dzieje się tuż przed naciśnięciem spustu?", "options": ["Broń zatrzymuje się na rzutku", "Broń przyspiesza przed rzutek", "Broń opada pod rzutek", "Broń czeka w punkcie strzału"], "answer": 1, "why": "Samo pull-away to przyspieszenie do przodu; strzał pada, gdy broń wciąż porusza się do przodu."}, {"q": "Trener mówi „You rode it too long”. Co poszło nie tak?", "options": ["Za długo stał na stanowisku przed komendą", "Złożył się o wiele za wcześnie", "Za długo prowadził rzutek, zanim wyszedł przed niego", "Operator wyrzutni zwolnił rzutek za późno"], "answer": 2, "why": "„Riding the target” to prowadzenie rzutka zbyt długo, przez co zwalnia, opada lub ucieka, a linia się gubi."}, {"q": "W porównaniu ze stałym wyprzedzeniem wyprzedzenie widziane przy pull-away jest zwykle…", "options": ["mniejsze, bo przyspieszenie dodaje wyprzedzenia", "większe, bo broń startuje na rzutku", "zawsze dokładnie dwa razy większe", "zerowe przy każdym rzutku"], "answer": 0, "why": "Krótkie przyspieszenie niesie broń do przodu w czasie opóźnienia strzału, więc trzeba zobaczyć mniejszy odstęp."}]}, {"id": "lead-ambush-instinctive", "minutes": 5, "title": "Zasadzka i strzelanie instynktowne", "body": ["Zasadzka (ambush), czyli strzał w punkt (spot shooting; po polsku można to opisać jako „strzał w punkt” albo „na przechwyt”), to przeciwieństwo prowadzenia broni. 1) Wyloty luf ustawia się w punkcie przed rzutkiem, na jego linii, blisko punktu strzału. 2) Czekają z niewielkim ruchem albo bez ruchu. 3) Spust naciska się, gdy rzutek dolatuje do tego miejsca.", "Jako ogólny nawyk, typowy dla niewyszkolonych strzelców, jest zawodna: broń stoi, a wyczucie czasu musi być idealne. Ale celowa zasadzka bywa właściwym wyborem: na rzutek, który trzeba wziąć bardzo szybko, albo na rabbita widocznego tylko w krótkiej luce między krzakami. Pokrewny ruch na battue lecących krawędzią w szczycie lotu to „collapse”: trzymaj broń bardzo blisko punktu strzału i wykonaj minimalny ruch. Rzutek nadal musi pęknąć tam, gdzie sędzia może go widzieć.", "Strzelanie instynktowne oznacza brak jakiegokolwiek świadomego wyprzedzenia. Strzelec utrzymuje ostre skupienie na rzutku i pozwala rękom podążać; ruch broni i złożenie dzieją się razem, a strzał pada, gdy broń dochodzi do twarzy. Klasyczna szkoła to ta kojarzona z angielskim rusznikarzem Robertem Churchillem, popularna w łowiectwie.", "Wielu czołowych strzelców Parcours de Chasse – Sporting™ łączy metody, wybierając je dla każdego rzutka. „Which method for this one?” (jaka metoda na ten?) to zwykłe pytanie trenerskie."], "key_points": ["Zasadzka: wyloty luf nieruchomo w punkcie przed rzutkiem; strzał, gdy rzutek dolatuje.", "Zawodna jako nawyk, przydatna celowo (bardzo szybkie rzutki, krótkie luki).", "„Collapse”: minimalny ruch blisko punktu strzału na battue lecących krawędzią.", "Instynktowne: bez świadomego wyprzedzenia, ostre skupienie, złożenie i ruch razem (szkoła Churchilla).", "Dobrzy strzelcy wybierają metodę dla każdego rzutka."], "terms": ["ambush", "instinctive-shooting", "hard-focus", "break-point", "battue", "rabbit"], "sources": [{"title": "Wikipedia — Clay pigeon shooting (methods)", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}, {"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "Shotgun Life — Wingshooting schools of England", "url": "https://www.shotgunlife.com/travel/places-to-shoot/wingshooting-schools-of-england-3.html"}], "sim": {"type": "lead", "method": "ambush", "preset": "rabbit", "muzzle_start": "at-break-point", "gun_speed": "none-or-minimal", "trigger": "target-arrives", "follow_through": false}, "rule_refs": [{"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "You're ambushing it — keep the gun moving with the target.", "meaning": "Strzelec czeka w punkcie; trener chce tu metody z ruchem broni.", "say": "Czekasz na niego w zasadzce — prowadź broń z rzutkiem."}, {"en": "Ambush this one in the gap.", "meaning": "Celowo czekaj przy prześwicie i strzelaj, gdy rzutek go przecina.", "say": "Tego weź z zasadzki w luce."}, {"en": "Don't think about the lead, just look at the bird and let the gun go to it.", "meaning": "Strzelaj instynktownie: skup się na rzutku i pozwól rękom podążać.", "say": "Nie myśl o wyprzedzeniu, patrz na rzutek i pozwól broni do niego pójść."}, {"en": "Hold right on the break point and just collapse onto it.", "meaning": "Ustaw wyloty luf prawie w punkcie strzału i zrób tylko drobny ruch, gdy battue nadlatuje.", "say": "Trzymaj prosto w punkcie strzału i tylko lekko na niego opadnij."}], "quiz": [{"q": "Co charakteryzuje zasadzkę (strzał w punkt)?", "options": ["Broń porusza się szybciej niż rzutek", "Broń czeka w punkcie przed rzutkiem", "Broń prowadzi rzutek, potem przyspiesza", "Broń startuje za rzutkiem, na jego linii"], "answer": 1, "why": "Zasadzka to niewielki ruch broni lub żaden: wyloty luf czekają na linii, a rzutek wlatuje w strzał."}, {"q": "Kiedy celowa zasadzka może być dobrym wyborem?", "options": ["Na każdym dalekim, równym rzutku poprzecznym", "Nigdy: przepisy jej zabraniają", "Tylko w Compak® Sporting, nigdy w Sporting™", "Na rabbita widocznego tylko w krótkiej luce"], "answer": 3, "why": "Gdy rzutek widać tylko przez chwilę, nie ma czasu na prowadzenie broni, więc czekanie przy luce może zadziałać. Żaden przepis nie zabrania żadnej metody."}, {"q": "Co to jest strzelanie instynktowne?", "options": ["Ostre skupienie na rzutku, bez świadomego wyprzedzenia", "Strzelanie bez okularów strzeleckich", "Strzelanie z biodra, bez złożenia", "Czekanie przy wyrzutni na każdy rzutek"], "answer": 0, "why": "Strzelanie instynktowne opiera się na koordynacji oko–ręka; wciąż strzela się z bronią przy ramieniu, jak wymagają przepisy."}]}, {"id": "lead-how-coaches-say-it", "minutes": 6, "title": "Jak trenerzy mówią o wyprzedzeniu i jak to tłumaczyć", "body": ["Jednostki. Trenerzy brytyjscy i amerykańscy mówią w stopach i jardach: „give it four foot” (brytyjskie „cztery stopy”), „two feet in front”. Trenerzy europejscy używają metrów. Jedna stopa to około 30 cm, jeden jard około 0,9 m. Ale liczba przy wyprzedzeniu to obraz trenera, a nie pomiar, więc zachowaj jego liczbę i jednostkę. Nigdy nie przeliczaj w środku wskazówki; jeśli strzelec zapyta, wyjaśnij w przybliżeniu między rzutkami. Odległości do rzutka („it's 30 yards”) można podać jako „około 27 m”.", "Szerokości rzutka: „half a bird”, „a bird's width”, „a clay's length”. Bird oznacza rzutek, nigdy prawdziwego ptaka: „pół rzutka”. Szerokości lufy: „a barrel's width”, „two barrels” oznaczają odstęp widziany przy wylocie lufy. Uwaga: „two barrels” w ustach sędziego oznacza obie lufy wystrzelone jednocześnie.", "Słowa względne: „more”, „less”, „a touch more”, „double it”, „half that”, „same lead”. Zachowaj je jako względne i nigdy nie wymyślaj liczby. „Same lead” (to samo wyprzedzenie) jest kluczowe: strzelec nie może dodawać wyprzedzenia.", "Kierunki: „in front” i „behind” odnoszą się do kierunku lotu rzutka; „over” i „high”, „under” i „low” to synonimy. Tarcza zegara opisuje położenie: godzina 12 to góra, 3 to prawo, tak jak widzi strzelec. „You hit it at six” oznacza dolną krawędź; „it comes from eleven” podaje kierunek.", "Metoda: tłumacz liczbę, jednostkę, punkt odniesienia i kierunek dokładnie, krótko, w rytmie trenera. Jeśli coś jest niejasne, zapytaj go jednym słowem: „Feet?” Na zawodach udzielanie wskazówek trenerskich jest zabronione."], "key_points": ["Zachowaj liczbę i jednostkę trenera; nigdy nie przeliczaj wyprzedzenia w środku wskazówki.", "Bird = rzutek: „half a bird” = „pół rzutka”.", "Słowa względne zostają względne; „same lead” trzeba przetłumaczyć.", "Tarcza zegara: 12 góra, 3 prawo, tak jak widzi strzelec.", "„Two barrels” sędziego to podwójny wystrzał, a nie wyprzedzenie."], "terms": ["lead", "perceived-lead", "clock-face", "double-discharge", "coach"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "Shooting UK — The overhead clay from behind (clock-face pick-up)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-rl", "focus": "lead-units"}, "rule_refs": [{"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Give it four foot.", "meaning": "Daj wyprzedzenie, które trener nazywa „czterema stopami”; to opis jego obrazu, więc zachowaj jego liczbę i jednostkę.", "say": "Daj mu cztery stopy."}, {"en": "Half a bird more.", "meaning": "Dodaj do obrazu wyprzedzenia pół szerokości rzutka.", "say": "Pół rzutka więcej."}, {"en": "Double it.", "meaning": "Zrób obraz wyprzedzenia dwa razy większy niż ostatnio.", "say": "Podwój to."}, {"en": "Same lead, just keep it moving.", "meaning": "Wyprzedzenie było dobre; pudło wzięło się z zatrzymania broni.", "say": "To samo wyprzedzenie, tylko trzymaj broń w ruchu."}, {"en": "You were at two o'clock — a touch low and more in front.", "meaning": "Rozrzut był nad rzutkiem i na prawo od niego na tarczy zegara; strzelaj trochę niżej i daj trochę więcej wyprzedzenia.", "say": "Byłeś na drugiej — odrobinę niżej i bardziej przed nim."}, {"en": "A barrel's width in front.", "meaning": "Utrzymuj przed rzutkiem odstęp szerokości lufy, widziany przy wylocie.", "say": "Szerokość lufy przed nim."}], "quiz": [{"q": "Trener mówi „Give it four foot” strzelcowi, który myśli w metrach. Co mówisz?", "options": ["„Daj 1,22 metra”", "„Daj około metra”", "„Daj cztery stopy”", "„Daj cztery metry”"], "answer": 2, "why": "Liczba przy wyprzedzeniu to obraz trenera; przeliczanie w środku wskazówki dodaje fałszywej precyzji lub błędów, a „cztery metry” całkowicie zmienia sens. Jeśli strzelec zapyta, wyjaśnij w przybliżeniu między rzutkami."}, {"q": "Co znaczy „half a bird”?", "options": ["Pół szerokości rzutka", "Rozbity rzutek", "Mały ptak latający przy wyrzutni", "Połowa serii"], "answer": 0, "why": "W strzelectwie do rzutków „bird” oznacza rzutek, więc trener prosi o wyprzedzenie równe połowie szerokości rzutka."}, {"q": "Trener mówi „Same lead, keep it moving”. Dlaczego trzeba przetłumaczyć „same lead”?", "options": ["To komenda, której używa sędzia", "Inaczej strzelec może dodać wyprzedzenia i chybić", "To grzecznościowe powitanie między strzelcami", "Zmienia kolejność rzutków"], "answer": 1, "why": "Po pudle większość strzelców sama dodaje wyprzedzenia; „same lead” mówi im, że przyczyną była zatrzymana broń, a nie wyprzedzenie."}]}]}, {"id": "faults", "icon": "search", "title": "Błędy i jak trenerzy je diagnozują", "intro": "Gdy rzutek zostaje chybiony, trener nazywa pudło jednym lub dwoma słowami, a potem jego przyczynę. Ta misja uczy słów na pudła i błędy, ich prawdziwego znaczenia oraz tego, jak szybko i dokładnie przekazać strzelcowi diagnozę trenera.", "lessons": [{"id": "faults-behind-in-front", "minutes": 5, "title": "Za, przed, nad, pod, drasnięty", "body": ["Każde pudło ma kierunek. Trener obserwujący zza pleców strzelca zwykle mówi najpierw, gdzie poszedł śrut względem rzutka, a dopiero potem dlaczego. Przekaż to natychmiast: strzelec już przygotowuje się do następnego rzutka.", "Behind (za rzutkiem) oznacza, że śrut przeszedł za lecącym rzutkiem: za małe wyprzedzenie albo broń, która zwolniła. To najczęstsze pudło przy rzutkach poprzecznych (crosser). In front (przed rzutkiem) to odwrotność: za duże wyprzedzenie, często po tym, jak strzelec przesadził z poprawką. Wielu trenerów lubi pudło przed rzutkiem: pokazuje, że broń się nie zatrzymała.", "Over (też „high”, „over the top” — nad rzutkiem) i under („low” — pod rzutkiem) opisują pudło w pionie. Nad rzutkiem zdarza się często przy rzutkach opadających, rabbitach i rzutkach nadlatujących i często wiąże się z oderwaniem głowy od kolby. Pod rzutkiem jest typowe dla rzutków wznoszących, które w chwili strzału wciąż się wznoszą.", "Chipped (drasnięty) oznacza, że odpadł tylko mały kawałek. Dla trenera to w połowie pochwała, w połowie poprawka: rzutek był na skraju rozrzutu śrutu. Dla sędziego to trafienie, o ile kawałek jest widoczny. Pułapką jest pył: według przepisów rzutek, z którego unosi się tylko pył lub dym, bez widocznego odprysku, jest chybiony. Tymczasem „smoked it” w żargonie trenerów to idealne, centralne trafienie, a „dusted it” słyszy się w obu znaczeniach — więc gdy nie masz pewności, dopytaj.", "Zachowaj kolejność trenera: kierunek, przyczyna, poprawka. Jeśli trener mówi „behind, you stopped”, ważniejsza jest przyczyna: strzelec, który usłyszy tylko „za rzutkiem”, doda wyprzedzenia, a to nie wyleczy zatrzymanej broni."], "key_points": ["Najpierw przekaż kierunek: za, przed, nad, pod.", "Za rzutkiem = za małe wyprzedzenie lub zwalniająca broń; przed rzutkiem = za duże wyprzedzenie.", "Widoczny odprysk to dla sędziego trafienie; sam pył lub dym — rzutek chybiony.", "„Smoked it” to pochwała trenera, a nie „dym” z przepisów: nigdy ich nie myl.", "Zachowaj kolejność trenera: kierunek, przyczyna, poprawka."], "terms": ["lead", "crosser", "dropping-target", "visible-piece", "one", "zero", "miss-behind", "miss-in-front", "miss-over", "miss-under", "chip", "smoke-ball"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}], "coach_says": [{"en": "Behind, give it more.", "meaning": "Śrut przeszedł za rzutkiem; zwiększ wyprzedzenie.", "say": "Za nim, daj więcej."}, {"en": "Just over the top, it was already dropping.", "meaning": "Śrut poszedł górą, bo rzutek już opadał; strzelaj niżej i przed nim.", "say": "Minimalnie nad nim, już opadał."}, {"en": "In front this time, good, now a touch less.", "meaning": "Za duże wyprzedzenie, ale broń się ruszała; zmniejsz wyprzedzenie odrobinę.", "say": "Tym razem przed nim, dobrze, teraz troszkę mniej."}, {"en": "You just chipped it, a little more in front.", "meaning": "Trafienie na skraju rozrzutu; trochę większe wyprzedzenie go wycentruje.", "say": "Ledwo go drasnąłeś, trochę bardziej przed nim."}, {"en": "Smoked it! Same again.", "meaning": "Idealne, centralne trafienie (żargon, a nie „dym” z przepisów); powtórz dokładnie to samo.", "say": "Rozniosłeś go w pył! Tak samo jeszcze raz."}, {"en": "Behind, but you stopped, so don't just add lead.", "meaning": "Przyczyną jest zatrzymana broń; samo większe wyprzedzenie nie pomoże.", "say": "Za nim, ale zatrzymałeś broń, więc nie dokładaj tylko wyprzedzenia."}], "quiz": [{"q": "Trener woła: „Behind, you stopped!”. Co najważniejsze trzeba przetłumaczyć?", "options": ["Przyczynę: broń się zatrzymała", "Tylko kierunek „za rzutkiem”", "Nic: strzelec widział pudło", "Prośbę o dużo większe wyprzedzenie"], "answer": 0, "why": "Dodanie wyprzedzenia nie wyleczy zatrzymanej broni; strzelec musi poprawić przyczynę."}, {"q": "Od rzutka odpada mały, ale wyraźnie widoczny kawałek. Trener mówi „just chipped it”. Jak liczy to sędzia?", "options": ["Chybiony, bo większość rzutka poleciała dalej", "No Bird", "Trafiony", "Trafiony tylko, jeśli trener się zgodzi"], "answer": 2, "why": "Co najmniej jeden widoczny odprysk oznacza trafienie zarówno w Sporting™, jak i w Compak® Sporting; decyduje wyłącznie sędzia."}, {"q": "Po trafieniu trener krzyczy „Smoked it!”. Co ma na myśli?", "options": ["Odpadł tylko pył, więc rzutek jest chybiony", "Idealne, centralne trafienie", "To był rzutek flash", "Strzelec powinien zmienić naboje"], "answer": 1, "why": "W żargonie trenerów „smoked it” to pochwała za rzutek obrócony w pył; w przepisach pył lub dym bez widocznego odprysku to pudło."}]}, {"id": "faults-head-lift-stopping", "minutes": 5, "title": "Podnoszenie głowy, zatrzymanie, prowadzenie za długo, celowanie", "body": ["Po kierunku trener nazywa przyczynę. Cztery przyczyny pojawiają się na każdym treningu, każda z własnym krótkim słowem. Ucz się ich parami: błąd i lekarstwo.", "Head lift (podnoszenie głowy z kolby): policzek odrywa się od kolby w chwili strzału lub tuż przed nim, często dlatego, że strzelec chce zobaczyć, jak rzutek pęka. Oko jest szczerbiną, więc uniesienie go przesuwa obraz i śrut zwykle idzie górą. Lekarstwo: „head down”, „cheek on the stock”, „stay in the gun” — głowa w dół, policzek na kolbie, zostań w broni.", "Stopping the gun (zatrzymanie broni): wyloty luf zatrzymują się w chwili strzału, zwykle dlatego, że strzelec sprawdza wyprzedzenie na lufie. Śrut idzie za rzutek. Łagodniejsza wersja to checking: ruch broni waha się przez ułamek sekundy. Lekarstwo: „keep the gun moving”, „follow through”, „finish the shot” — broń w ruchu, prowadź dalej, dokończ strzał.", "Riding the target (prowadzenie rzutka za długo): śledzenie rzutka zbyt długo przed strzałem, przez co zwalnia, opada lub odchodzi łukiem, a strzelec gubi linię. Lekarstwo: „take it earlier”, „commit to it” — bierz go wcześniej, zdecyduj się. Poking (też „aiming”, „measuring” — celowanie, „dźganie”): powolne mierzenie strzelbą jak karabinem, z oczami na muszce zamiast na rzutku. Typowe, gdy punkt strzału jest za blisko albo na tealu w najwyższym punkcie. Lekarstwo: „eyes on the clay”, „let the gun go” — oczy na rzutku, puść broń.", "Trenerzy często nazywają przyczynę, zanim strzelec zdąży opuścić broń. Tłumacz ją jednym tchem i tym samym czasownikiem: „you stopped” to nie „you missed”. Słowo takie jak „aiming” jest prawie zawsze krytyką, więc nigdy nie zamieniaj go w radę typu „celuj lepiej”."], "key_points": ["Podnoszenie głowy: śrut zwykle górą; lekarstwo: głowa w dół, zostań w broni.", "Zatrzymanie lub zawahanie: śrut za rzutkiem; lekarstwo: broń w ruchu, prowadź dalej.", "Prowadzenie za długo: rzutek zwalnia lub opada; lekarstwo: bierz wcześniej, zdecyduj się.", "Celowanie („poking”, „aiming”): powolne mierzenie jak karabinem; lekarstwo: oczy na rzutku.", "Przyczynę tłumacz od razu, czasownikiem trenera."], "terms": ["head-lift", "stopping-the-gun", "follow-through", "break-point", "teal", "checking", "riding-the-target", "poking"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "The Field — Improve your game and clay shooting: 20 top tips", "url": "https://www.thefield.co.uk/shooting/improve-your-game-and-clay-shooting-20-top-tips-45462"}, {"title": "Clay Target Nation — 5 major shooting mistakes", "url": "https://www.claytargetnation-digital.com/articles/5-major-shooting-mistakes"}], "sim": null, "rule_refs": [], "coach_says": [{"en": "You lifted your head, that's why it went over.", "meaning": "Policzek oderwał się od kolby, więc śrut poszedł nad rzutkiem.", "say": "Podniosłeś głowę, dlatego poszło górą."}, {"en": "Keep the gun moving, you stopped on it.", "meaning": "Ruch broni zatrzymał się przy strzale; prowadź dalej przez strzał i po nim.", "say": "Broń w ruchu, zatrzymałeś się na nim."}, {"en": "You checked just before the shot, commit to it.", "meaning": "Krótkie zawahanie przed strzałem; zdecyduj i strzelaj bez zwalniania.", "say": "Zawahałeś się tuż przed strzałem, zdecyduj się."}, {"en": "Stop aiming, look at the bird and let the gun go.", "meaning": "Krytyka: strzelec mierzy jak z karabinu; skup się na rzutku i prowadź swobodnie.", "say": "Przestań celować, patrz na rzutek i puść broń."}, {"en": "You rode it too long, take it earlier.", "meaning": "Strzelec prowadził rzutek za długo; rozbij go wcześniej.", "say": "Prowadziłeś go za długo, bierz go wcześniej."}, {"en": "Stay in the gun.", "meaning": "Trzymaj policzek na kolbie aż do chwili po strzale.", "say": "Zostań w broni."}], "quiz": [{"q": "Trener mówi „You lifted your head”. Gdzie najpewniej poszedł śrut?", "options": ["Za rzutek", "Nad rzutek", "Pod rzutek", "Przed rzutek"], "answer": 1, "why": "Oko jest szczerbiną: gdy głowa się unosi, śrut zwykle idzie górą."}, {"q": "Trener krzyczy „Stop aiming!”. Czego chce?", "options": ["Nie mierz jak z karabinu: patrz na rzutek i prowadź", "Celuj dokładniej", "Natychmiast przerwij strzelanie", "Opuść broń"], "answer": 0, "why": "„Aiming” w ustach trenera to błąd (poking); lekarstwem są oczy na rzutku i swobodny ruch broni."}, {"q": "„You rode it too long” znaczy…", "options": ["Strzelec strzelił za wcześnie", "Wyrzutnia była za wolna", "Strzelec zaczął za daleko za rzutkiem", "Strzelec prowadził rzutek za długo przed strzałem"], "answer": 3, "why": "Riding the target to prowadzenie rzutka zbyt długo, przez co zwalnia lub opada, a linia się gubi."}]}, {"id": "faults-mount-errors", "minutes": 5, "title": "Błędy złożenia: za późno, twarz do broni, przechylenie", "body": ["Wiele pudeł zaczyna się przed ruchem broni, przy złożeniu się do strzału (gun mount) — ruchu, który podnosi broń do policzka i ramienia. Słowa trenera na ten temat są krótkie i fizyczne.", "Late mount (spóźnione złożenie): broń dociera do ramienia po chwili, w której powinien paść strzał, więc strzelec się spieszy albo strzela, zanim policzek opadnie na kolbę. Odwrotny błąd to złożenie zakończone za wcześnie, po którym broń czeka, nieruchoma i ciężka. Lekarstwo: „move, mount, shoot” — ruch, złożenie, strzał: wyloty luf ruszają z rzutkiem, a złożenie kończy się wraz ze strzałem.", "Face to the gun (twarz do broni): zamiast podnieść kolbę do twarzy, strzelec opuszcza głowę do kolby. Oko za każdym razem trafia w inne miejsce, a odrzut uderza w policzek. Trenerzy mówią: „bring the gun to your face, not your face to the gun” — broń do twarzy, nie twarz do broni. Kolba lądująca na ramieniu (bicepsie) zamiast w zagłębieniu barku też boli.", "Canting (przechylenie broni): broń jest przechylona na bok w chwili strzału i śrut zjeżdża z linii. Często towarzyszy temu opuszczony bark. Lekarstwo: „keep the gun level”, „turn from the hips” — broń prosto, obracaj się z bioder.", "Na zawodach FITASC Parcours de Chasse – Sporting™ nie wolno składać się, zanim pojawi się rzutek, więc „pre-mount this one” to wyłącznie ćwiczenie treningowe. Wcześniejsze złożenie się na zawodach Sporting™ oznacza ostrzeżenie i żółtą kartkę. W Compak® Sporting broń może być przy ramieniu już w chwili komendy. Tłumacz ćwiczenie jako ćwiczenie i nie dodawaj nic od siebie."], "key_points": ["Spóźnione złożenie: pośpieszny strzał; lekarstwo: ruch, złożenie, strzał.", "Twarz do broni: oko się przesuwa, odrzut boli; podnoś broń do twarzy.", "Przechylenie: śrut zjeżdża z linii; broń prosto, obrót z bioder.", "Złożenie przed komendą to ćwiczenie: na zawodach Sporting™ niedozwolone, zanim pojawi się rzutek; w Compak® Sporting dozwolone przy komendzie."], "terms": ["gun-mount", "ready-position", "recoil", "comb", "gun-fit", "dry-mounting", "late-mount", "canting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Bring the gun to your face, not your face to the gun.", "meaning": "Podnieś kolbę do policzka; nie opuszczaj głowy do kolby.", "say": "Broń do twarzy, nie twarz do broni."}, {"en": "Move, mount, shoot, all in one.", "meaning": "Ruszaj z rzutkiem, dokończ złożenie w chwili strzału, w jednym płynnym ruchu.", "say": "Ruch, złożenie, strzał — wszystko w jednym."}, {"en": "You canted the gun, keep it level.", "meaning": "Broń była przechylona na bok w chwili strzału.", "say": "Przechyliłeś broń, trzymaj ją prosto."}, {"en": "Mount on the line.", "meaning": "Broń powinna wchodzić od razu na tor lotu rzutka.", "say": "Składaj się na linię."}, {"en": "Pre-mount this one, just for practice.", "meaning": "Ćwiczenie treningowe z bronią już przy ramieniu; niedozwolone na zawodach Sporting™.", "say": "Ten złóż wcześniej, tylko na ćwiczenie."}], "quiz": [{"q": "Na treningu trener mówi strzelcowi, który przygotowuje się do zawodów FITASC Sporting™: „Pre-mount this one.” Co jest prawdą?", "options": ["To dozwolone na wszystkich zawodach FITASC", "Tłumacz powinien odmówić przetłumaczenia", "To ćwiczenie treningowe; na zawodach Sporting™ nie wolno składać się, zanim pojawi się rzutek", "To znaczy złożyć się po strzale"], "answer": 2, "why": "Sporting™ wymaga pozycji gotowości z bronią opuszczoną, dopóki nie pojawi się rzutek; złożenie wcześniej na zawodach to ostrzeżenie z żółtą kartką."}, {"q": "„You canted the gun” znaczy…", "options": ["Broń była przechylona na bok w chwili strzału", "Złożenie było za późne", "Broń się zatrzymała", "Bezpiecznik był włączony"], "answer": 0, "why": "Canting to przechylenie broni na bok, które ściąga śrut z linii."}, {"q": "Która wskazówka leczy błąd „face to the gun”?", "options": ["Mocniej dociśnij głowę w dół", "Podnoś broń do twarzy", "Zamknij jedno oko", "Trzymaj broń niżej na ramieniu"], "answer": 1, "why": "Kolba powinna przychodzić do twarzy, żeby oko było za każdym razem w tym samym miejscu."}]}, {"id": "faults-pairs-transition", "minutes": 5, "title": "Dublety: drugi rzutek", "body": ["Przy dublecie (pair, double) wielu strzelców rozbija pierwszy rzutek, a chybia drugi. Trener mówi wtedy o przejściu (transition), czyli przeniesieniu się z pierwszego rzutka na drugi, i o powrocie (recovery), czyli odzyskaniu kontroli nad bronią i głową po pierwszym strzale.", "Złota zasada brzmi „eyes first, then the gun” — najpierw oczy, potem broń. Oczy opuszczają rozbity pierwszy rzutek i znajdują drugi; broń idzie za nimi. Strzelec, który patrzy, jak pęka pierwszy rzutek, albo przenosi broń, zanim znajdzie drugi, traci czas. Trenerzy mówią „eyes to the second” albo po prostu pokazują ręką.", "Powrót: odrzut podrzuca wyloty luf, a czasem głowę. „Let the gun recover, then go” znaczy: policzek z powrotem na kolbę i broń z powrotem na linii, zanim ruszysz za drugim rzutkiem. Dobra postawa z ciężarem z przodu przyspiesza powrót.", "Planowanie: podczas odczytywania dubletu trener decyduje, który rzutek brać pierwszy i gdzie go rozbić, żeby drugi łatwo było podjąć. Typowe zwroty: „take the dropping one first” (najpierw opadający), „break the first early” (pierwszy rozbij wcześnie), „stick to the plan” (trzymaj się planu). O strzelcu, który zmienił kolejność na stanowisku, mówi się „went for the wrong one” — wziął nie ten.", "Tu liczą się przepisy. W Parcours de Chasse – Sporting™ pozycja broni między dwoma rzutkami każdego dubletu jest dowolna, a strzelec ma na dublet dwa naboje, które oba może oddać do tego samego rzutka. W Compak® Sporting w dublecie dozwolony jest tylko jeden nabój na rzutek. Nie objaśniaj kar sam: tłumacz trenera, a pytania o przepisy zostaw sędziemu."], "key_points": ["Najpierw oczy, potem broń.", "Powrót: policzek z powrotem na kolbie i broń na linii przed drugim rzutkiem.", "Trener planuje kolejność i punkty strzału dubletu podczas jego odczytywania.", "Sporting™: dowolna pozycja broni między rzutkami, oba naboje można oddać do jednego rzutka; Compak® Sporting: jeden nabój na rzutek."], "terms": ["double", "double-on-report", "simultaneous-double", "rafale-double", "recoil", "stance", "dropping-target", "transition", "recovery"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Eyes first to the second bird, then the gun.", "meaning": "Znajdź drugi rzutek oczami, zanim ruszysz bronią.", "say": "Najpierw oczy na drugi rzutek, potem broń."}, {"en": "Let the gun recover, then go to the second.", "meaning": "Po odrzucie ustabilizuj broń i policzek przed drugim strzałem.", "say": "Daj broni wrócić, potem idź na drugi."}, {"en": "Take the dropping one first.", "meaning": "Strzelaj najpierw do rzutka, który najszybciej zniknie albo spadnie.", "say": "Najpierw opadający."}, {"en": "Don't watch the first one break.", "meaning": "Od razu przenieś oczy na drugi rzutek.", "say": "Nie patrz, jak pęka pierwszy."}, {"en": "You went for the wrong one first, stick to the plan.", "meaning": "Strzelec zmienił zaplanowaną kolejność; to uwaga techniczna, a nie naruszenie przepisów.", "say": "Najpierw wziąłeś nie ten, trzymaj się planu."}], "quiz": [{"q": "Co przy dublecie znaczy „eyes first, then the gun”?", "options": ["Zamknij oczy po pierwszym strzale", "Spójrz na lufę przed drugim strzałem", "Złóż się, zanim zawołasz dublet", "Znajdź drugi rzutek oczami, zanim przeniesiesz na niego broń"], "answer": 3, "why": "Przy dobrym przejściu oczy prowadzą, a broń podąża za nimi."}, {"q": "W dublecie Compak® Sporting strzelec chybia pierwszy rzutek i chce oddać do niego także drugi nabój. Czy to dozwolone?", "options": ["Tak, jak w Sporting™", "Tak, ale tylko przy dublecie symultanicznym", "Nie: w dublecie Compak® Sporting dozwolony jest tylko jeden nabój na rzutek", "Tylko za zgodą sędziego"], "answer": 2, "why": "Compak® Sporting zabrania dubletowania pierwszego rzutka w dublecie; Sporting™ pozwala oddać oba naboje do jednego rzutka."}, {"q": "Czy w dublecie Sporting™ strzelec może opuścić broń między pierwszym a drugim rzutkiem?", "options": ["Tak, pozycja broni między dwoma rzutkami jest dowolna", "Nie, broń musi pozostać złożona", "Tylko przy dublecie na zawołanie", "Tylko jeśli sędzia pozwoli"], "answer": 0, "why": "Dowolna pozycja obowiązuje między rzutkami każdego dubletu, ale nie przed pierwszym."}]}, {"id": "faults-reading-the-coach", "minutes": 5, "title": "Jak czytać trenera: krótkie komendy i sygnały", "body": ["Na stanowisku trener mówi urywkami: „Behind.” „Head.” „More.” „Again.” Między rzutkami jest tylko kilka sekund, więc zwięzłość jest celowa. Twoje tłumaczenie powinno być równie krótkie; długie zdanie dotrze dopiero po następnej komendzie.", "Wielu trenerów najpierw pyta, a potem mówi: „Where did it go?” (gdzie poszło?) albo „What did you see?” (co widziałeś?). To pytanie dydaktyczne, a nie sprawdzian dla tłumacza. Przetłumacz pytanie, pozwól strzelcowi odpowiedzieć i przetłumacz odpowiedź dokładnie, nawet jeśli brzmi błędnie. Trener musi wiedzieć, co strzelec zobaczył.", "Sygnały rąk mówią dużo. Typowe: dłonie rozsuwające się lub zsuwające — więcej lub mniej wyprzedzenia, płaska dłoń w dół — „niżej”, stuknięcie w policzek — „głowa w dół”, palec rysujący linię lotu rzutka, kciuk w górę — „tak samo jeszcze raz”. Sygnały różnią się między trenerami, więc ustal je przed zajęciami i nie tłumacz gestu, który strzelec już widział.", "Niektóre słowa to czysty rytm i zachęta: „commit”, „trust it”, „smooth”, „good, same again”. Zachowaj ton. „Bad luck” po pudle to życzliwość, a nie komentarz o sędzi.", "Na zawodach udzielanie wskazówek trenerskich jest zabronione: sędzia daje zawodnikowi żółtą kartkę i odsyła trenera poza teren strzelania. Przepisy nie mówią, czy tłumacz może przekazywać rady trenera w trakcie zawodów: to kwestia otwarta dla FITASC. Bezpieczna praktyka: na zawodach tłumacz wyłącznie dla sędziego, jury i organizatora."], "key_points": ["Trenerzy mówią urywkami; tłumacz równie krótko.", "„Where did it go?” to pytanie dydaktyczne: przetłumacz odpowiedź strzelca dokładnie.", "Ustal sygnały rąk przed zajęciami.", "Bez wskazówek trenerskich na zawodach; tłumacz tylko dla sędziego, jury i organizatora."], "terms": ["coach", "referee", "jury", "yellow-card", "hand-signal"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Where did it go?", "meaning": "Trener pyta, gdzie według strzelca poszedł strzał; pytanie dydaktyczne.", "say": "Gdzie poszło?"}, {"en": "What did you see?", "meaning": "Opisz obraz w chwili strzału.", "say": "Co widziałeś?"}, {"en": "More.", "meaning": "W kontekście prawie zawsze „więcej wyprzedzenia”.", "say": "Więcej."}, {"en": "Good, same again.", "meaning": "Powtórz dokładnie to, co właśnie zrobiłeś.", "say": "Dobrze, tak samo jeszcze raz."}, {"en": "Trust it, commit to it.", "meaning": "Przestań się wahać; zdecyduj i strzelaj.", "say": "Zaufaj sobie, zdecyduj się."}, {"en": "Bad luck.", "meaning": "Współczucie po pudle; nie skarga na sędziego.", "say": "Pech."}], "quiz": [{"q": "Trener pyta strzelca „Where did it go?”. Co powinien zrobić tłumacz?", "options": ["Odpowiedzieć za strzelca", "Przetłumaczyć pytanie, a potem dokładnie odpowiedź strzelca", "Wyjaśnić pudło własnymi słowami", "Nic nie mówić: to pytanie retoryczne"], "answer": 1, "why": "Trener chce poznać odczucia samego strzelca, więc odpowiedź musi dotrzeć do niego bez zmian."}, {"q": "W trakcie zawodów trener strzelca prosi cię o przekazanie: „Give the next one more lead.” Jaka jest bezpieczna praktyka?", "options": ["Przekazać to po cichu", "Przekazać to tylko między stanowiskami", "Nie przekazywać wskazówek na zawodach; tłumaczyć tylko dla sędziego, jury i organizatora", "Najpierw zapytać innych strzelców"], "answer": 2, "why": "Wskazówki trenerskie na zawodach są zabronione, a przepisy nie mówią, czy tłumacz może je przekazywać; trzymanie się od tego z daleka chroni strzelca."}, {"q": "Co przewidują przepisy, jeśli sędzia uzna, że zawodnik otrzymuje wskazówki trenerskie?", "options": ["Żółta kartka dla zawodnika; trener zostaje odesłany poza teren strzelania", "Nic: wskazówki są dozwolone", "Rzutek się powtarza", "Cała grupa zostaje zdyskwalifikowana"], "answer": 0, "why": "Przepisy obu dyscyplin dają zawodnikowi żółtą kartkę, z surowszymi karami za powtórzenia, i usuwają trenera."}]}]}, {"id": "sporting", "icon": "flag", "title": "Przepisy Parcours de Chasse – Sporting™", "intro": "Parcours de Chasse – Sporting™ to dyscyplina FITASC, która naśladuje polowanie w naturalnym terenie. Ta misja prowadzi cię przez jej przepisy tak, jak stosuje je sędzia: serie i stanowiska, start z bronią opuszczoną, rzutki pojedyncze i dublety, pokaz rzutków, awarie i limity czasu. Wszystko to jest omówienie własnymi słowami; odnośniki do przepisów otwierają przewodnik po przepisach ClayArena.", "lessons": [{"id": "sporting-rounds-stands", "minutes": 5, "title": "Serie, stanowiska i kolejność strzelania", "body": ["Zawody Parcours de Chasse – Sporting™ liczy się w seriach po 25 rzutków. Zawody międzynarodowe to 200 rzutków, czyli osiem serii; każdą serię strzela się na jednej osi (zespole stanowisk strzeleckich) albo jednej linii.", "Każda oś daje 15 rzutków pojedynczych i 5 dubletów. Liczba stanowisk i wyrzutni zależy od systemu: stary system używa 5 wyrzutni na 3 stanowiska, a linie nowego systemu mają 4 lub 5 stanowisk z 3 lub 4 wyrzutniami każde. Wyrzutnie oznacza się literami A, B, C, D od lewej do prawej, tak jak widać je ze stanowiska. Menu rzutków przed stanowiskiem wymienia je w kolejności strzelania, wraz z rzutkami specjalnymi: 90, 70 lub 60 mm, battue, rabbit.", "Samo stanowisko to kwadrat 1 m albo koło o średnicy 1 m. Każdy tor lotu ma klasę trudności: A (przeciętny strzelec rozbija ponad 80%), B (60–80%) lub C (40–60%).", "Strzelcy przechodzą parcours w grupach do sześciu osób, tworzonych w drodze losowania. Na każdym stanowisku wszyscy strzelają najpierw rzutki pojedyncze, a potem dublety, a kolejność strzelania zmienia się na każdym stanowisku i ponownie przy dubletach. Pozostali czekają w pobliżu, nie rozpraszając strzelającego.", "Kartę wyników prowadzi sędzia albo osoba pod jego nadzorem, zaznaczając każdy rzutek pod literą jego wyrzutni. Schodząc z każdego stanowiska, każdy strzelec sprawdza wynik; niezgodność trzeba od razu zgłosić sędziemu, a jego decyzja jest ostateczna."], "key_points": ["Seria = 25 rzutków na jednej osi: 15 pojedynczych + 5 dubletów; zawody międzynarodowe = 200 rzutków.", "Wyrzutnie A, B, C, D od lewej do prawej, tak jak widać je ze stanowiska; menu podaje kolejność i rzutki specjalne.", "Grupy do sześciu osób; najpierw pojedyncze, potem dublety; kolejność się zmienia.", "Sprawdź wynik, schodząc z każdego stanowiska; decyduje sędzia."], "terms": ["round", "layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "squad", "rotation", "score-sheet", "referee", "difficulty-class"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}], "coach_says": [{"en": "Singles first, then doubles.", "meaning": "Standardowa kolejność na każdym stanowisku.", "say": "Najpierw pojedyncze, potem dublety."}, {"en": "Read the menu: the traps go A, B, C.", "meaning": "Tablica z menu wymienia wyrzutnie w kolejności, w jakiej będą strzelane.", "say": "Przeczytaj menu: wyrzutnie idą A, B, C."}, {"en": "Next shooter.", "meaning": "Sędzia wzywa następną osobę na stanowisko.", "say": "Następny strzelec."}, {"en": "Check your score before you leave the stand.", "meaning": "Każdą niezgodność trzeba zgłosić teraz, a nie później.", "say": "Sprawdź wynik, zanim zejdziesz ze stanowiska."}], "quiz": [{"q": "Ile rzutków daje jedna oś Sporting™ i jak się dzielą?", "options": ["20: 10 pojedynczych i 5 dubletów", "25: same pojedyncze", "25: 15 pojedynczych i 5 dubletów", "50: 25 pojedynczych i 25 dubletów"], "answer": 2, "why": "Każdy typ osi daje 15 rzutków pojedynczych plus 5 dubletów, czyli 25 rzutków."}, {"q": "W jakiej kolejności grupa strzela na stanowisku?", "options": ["Najpierw dublety, potem pojedyncze", "Wszyscy strzelają najpierw pojedyncze, potem dublety, a kolejność się zmienia", "Każdy strzelec strzela całą oś za jednym razem", "Strzelcy wybierają dowolnie"], "answer": 1, "why": "Najpierw pojedyncze, potem dublety, z rotacją kolejności, chyba że jury zdecyduje inaczej."}, {"q": "Schodząc ze stanowiska, strzelec widzi, że trafienie zapisano jako pudło. Co powinien zrobić?", "options": ["Poczekać do końca serii i odwołać się do jury", "Samemu poprawić kartę", "Poprosić grupę o głosowanie", "Od razu powiedzieć sędziemu; decyduje sędzia"], "answer": 3, "why": "Wyniki sprawdza się, schodząc z każdego stanowiska; decyduje wyłącznie sędzia, a później nie ma odwołania."}]}, {"id": "sporting-gun-position", "minutes": 5, "title": "Start z bronią opuszczoną", "body": ["Najbardziej widocznym przepisem Parcours de Chasse – Sporting™ jest start z bronią opuszczoną. Przed komendą strzelec stoi obiema stopami wewnątrz stanowiska, stopka kolby dotyka ciała, a górny tylny punkt kolby jest poniżej linii na kamizelce. Tę pozycję gotowości utrzymuje się, aż rzutek zostanie wyrzucony i będzie widoczny.", "Linię zaznacza się na kamizelce lub kurtce 25 cm poniżej osi barków, równolegle do niej, w kolorze kontrastującym z kamizelką, żeby sędzia mógł ją widzieć. Przepis dotyczy każdego rodzaju kolby, także z regulowaną baką.", "Broń może pójść w górę dopiero, gdy pojawi się rzutek. Do każdego rzutka, także rabbita, strzela się z bronią przy ramieniu; strzał z biodra jest niedozwolony. Między pierwszym a drugim rzutkiem każdego dubletu pozycja broni jest dowolna, ale przed pierwszym rzutkiem obowiązuje pozycja gotowości.", "Kary: za pierwszym razem, gdy strzelec woła rzutek w niewłaściwej pozycji albo składa się, zanim pojawi się rzutek, sędzia udziela ustnego ostrzeżenia z żółtą kartką. Każde kolejne wykroczenie na tej samej osi oznacza czerwoną kartkę, a rzutek liczy się jako zero przy rzutku pojedynczym, zero i No Bird przy dublecie na zawołanie, zero i zero przy dublecie symultanicznym lub rafale.", "Składanie się i prowadzenie broni po wyobrażonej linii przed komendą (mock shooting, ćwiczenia celowania) też jest zabronione: najpierw ostrzeżenie, potem zero. Jeśli trener przed zawodami FITASC ćwiczy start z bronią w górze, przetłumacz także słowo „drill” — ćwiczenie."], "key_points": ["Przed komendą: obie stopy na stanowisku, kolba dotyka ciała, góra kolby poniżej linii na kamizelce.", "Linia na kamizelce jest 25 cm poniżej osi barków, w kontrastowym kolorze.", "Składaj się dopiero, gdy pojawi się rzutek; zawsze strzał z ramienia; dowolna pozycja między rzutkami dubletu.", "Pierwsze wykroczenie: ostrzeżenie + żółta kartka; kolejne na tej samej osi: czerwona kartka i rzutek liczony według tabeli."], "terms": ["ready-position", "gun-mount", "shooting-stand", "shooting-vest", "adjustable-comb", "mock-shooting", "yellow-card", "red-card", "jacket-line"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}], "coach_says": [{"en": "Gun down, please.", "meaning": "Sędzia: przed komendą opuść kolbę poniżej linii na kamizelce.", "say": "Broń w dół, proszę."}, {"en": "Your stock was above the line. This is a warning.", "meaning": "Pierwsze wykroczenie dotyczące pozycji broni: ustne ostrzeżenie z żółtą kartką.", "say": "Kolba była powyżej linii. To jest ostrzeżenie."}, {"en": "Don't mount before the target appears.", "meaning": "Broń może pójść w górę dopiero, gdy rzutek jest widoczny.", "say": "Nie składaj się, zanim pojawi się rzutek."}, {"en": "Red card, zero.", "meaning": "Powtórne wykroczenie na tej samej osi; rzutek pojedynczy jest stracony.", "say": "Czerwona kartka, zero."}], "quiz": [{"q": "Pierwsze stanowisko. Strzelec woła rzutek z bronią już przy ramieniu. To jego pierwsze wykroczenie na tej osi. Jaka jest decyzja sędziego?", "options": ["Rzutek liczy się jako zero", "Ustne ostrzeżenie z żółtą kartką", "No Bird i nic więcej", "Wykluczenie"], "answer": 1, "why": "Pierwsze wykroczenie dotyczące pozycji broni to ustne ostrzeżenie poparte żółtą kartką."}, {"q": "Ta sama oś, dwa stanowiska dalej: ten sam strzelec woła rzutek pojedynczy z kolbą powyżej linii na kamizelce. Decyzja?", "options": ["Kolejna żółta kartka", "No Bird", "Czerwona kartka, a rzutek się powtarza", "Czerwona kartka, a rzutek pojedynczy liczy się jako zero"], "answer": 3, "why": "Po ostrzeżeniu kolejne wykroczenie na tej samej osi to czerwona kartka: zero przy rzutku pojedynczym."}, {"q": "Dublet na zawołanie. Po rozbiciu pierwszego rzutka strzelec lekko opuszcza broń przed drugim. Decyzja?", "options": ["Dozwolone: pozycja broni między dwoma rzutkami jest dowolna", "Żółta kartka", "Zero na drugim rzutku", "No Bird"], "answer": 0, "why": "Dowolna pozycja obowiązuje między rzutkami każdego dubletu; pozycja gotowości jest wymagana tylko przed pierwszym."}]}, {"id": "sporting-singles-doubles", "minutes": 5, "title": "Rzutki pojedyncze i dublety", "body": ["Rzutek pojedynczy to jeden rzutek z jednej wyrzutni. W Parcours de Chasse – Sporting™ strzelec może oddać do niego dwa naboje, więc pudło z pierwszej lufy można jeszcze uratować drugą. Każdy rzutek pojedynczy musi dawać czas na dwa strzały.", "Dublet to dwa rzutki, a strzelec ma na niego tylko dwa naboje; oba może oddać do tego samego rzutka. Są trzy rodzaje. Na zawołanie (on report): drugi rzutek wylatuje od 0 do 3 sekund po strzale do pierwszego, zwolniony tym strzałem. Symultaniczny: oba wylatują w tej samej chwili, z jednej lub dwóch wyrzutni. Rafale: dwa rzutki z tej samej wyrzutni po tej samej linii, drugi tak szybko, jak wyrzutnia się przeładuje. W dubletach symultanicznych i rafale rzutki można strzelać w dowolnej kolejności. W dubletach używa się tylko rzutków pokazanych już jako pojedyncze z tego samego stanowiska.", "Decyzje, które sędzia często musi podejmować: jeśli jeden strzał rozbije oba rzutki dowolnego dubletu, liczą się oba — trafiony i trafiony. Jeśli strzelec bez uzasadnionego powodu nie strzela do dubletu rafale lub symultanicznego, jest zero i zero.", "Przy dublecie na zawołanie nieprawidłowy pierwszy rzutek oznacza powtórzenie dubletu; jeśli pierwszy rzutek lub jego odłamki rozbiją drugi przed drugim strzałem albo drugi jest nieprawidłowy, dublet się powtarza, a wynik pierwszego zostaje. Przy dubletach symultanicznych i rafale nieprawidłowy rzutek oznacza powtórkę bez zapisania wyniku.", "Wskazówka: wynik dubletu przekazuj jako parę, w kolejności podanej przez sędziego."], "key_points": ["Rzutek pojedynczy: dozwolone dwa naboje.", "Dublet: łącznie dwa naboje, oba mogą iść do jednego rzutka; rodzaje: na zawołanie, symultaniczny, rafale.", "Jeden strzał rozbija oba rzutki: trafiony i trafiony.", "Brak strzału do dubletu symultanicznego lub rafale bez powodu: zero i zero."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "trap", "trajectory", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch2-trajectories-ethics", "label": "2 · Hunting ethics and shooting distances"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-target-doubles", "label": "6 · Target No Bird in doubles"}], "coach_says": [{"en": "Report pair: the second comes on your shot.", "meaning": "Trener: drugi rzutek zwalnia strzał do pierwszego.", "say": "Dublet na zawołanie: drugi wylatuje na twój strzał."}, {"en": "On the rafale, take either one first.", "meaning": "W dublecie rafale kolejność jest dowolna.", "say": "Przy rafale bierz najpierw którykolwiek."}, {"en": "One and one.", "meaning": "Sędzia: oba rzutki dubletu są trafione.", "say": "Trafiony i trafiony."}, {"en": "No Bird, repeat the double.", "meaning": "Nieprawidłowy rzutek; dublet zostanie wyrzucony ponownie.", "say": "No Bird, powtórka dubletu."}], "quiz": [{"q": "Dublet symultaniczny. Jeden strzał rozbija oba rzutki. Jaka jest decyzja sędziego?", "options": ["Trafiony i trafiony", "Trafiony i No Bird", "No Bird, dublet się powtarza", "Trafiony i zero"], "answer": 0, "why": "W Sporting™ dwa rzutki rozbite jednym strzałem w dowolnym dublecie to trafiony i trafiony (w Compak® Sporting jest inaczej)."}, {"q": "Dublet na zawołanie. Strzelec rozbija pierwszy rzutek, a jego odłamek rozbija drugi przed drugim strzałem. Decyzja?", "options": ["Trafiony i trafiony", "Dublet się powtarza, a wynik pierwszego zostaje", "Zero na drugim rzutku", "Trafiony i zero"], "answer": 1, "why": "Gdy pierwszy rzutek lub jego odłamki rozbiją drugi przed drugim strzałem, dublet się powtarza, a wynik pierwszego zostaje."}, {"q": "Dublet rafale. Oba rzutki lecą prawidłowo, ale strzelec opuszcza broń i nie strzela do żadnego, nie podając uzasadnionego powodu. Decyzja?", "options": ["No Bird", "Zero i No Bird", "Tylko żółta kartka", "Zero i zero"], "answer": 3, "why": "Prawidłowy rzutek, do którego nie strzelano bez uzasadnionego powodu, jest stracony; przy dublecie rafale lub symultanicznym oznacza to zero i zero."}]}, {"id": "sporting-viewing", "minutes": 5, "title": "Pokaz rzutków", "body": ["Zanim grupa zacznie strzelać na stanowisku, sędzia każe pokazać rzutki. Pokaz służy do odczytania rzutków: linii, prędkości, odległości i tego, co robi rzutek. Wszystkie tory lotu pokazuje się pierwszemu strzelcowi grupy, który musi stać gotowy na stanowisku.", "Strzelec na stanowisku może poprosić sędziego o powtórzenie pokazu — maksymalnie dwa rzutki dla każdego rzutka z sekwencji menu.", "Dubletów na zawołanie się nie pokazuje, bo drugi rzutek wylatuje dopiero na huk strzału. Dublety symultaniczne i rafale pokazuje się pierwszemu strzelcowi każdej grupy, a na prośbę powtarza się je, maksymalnie dwa pokazane dublety.", "Podczas pokazu broń jest otwarta i rozładowana, jak przy każdej przerwie, a zamyka się ją ponownie dopiero za zgodą sędziego. Strzelanie lub pozorowane strzelanie podczas pokazu jest zabronione i karane jak wykroczenie dotyczące pozycji broni: najpierw ostrzeżenie, potem czerwona kartka.", "Jeśli wyrzutnia się zepsuje albo strzelanie zostanie przerwane na dłużej niż dziesięć minut, sędzia ponownie pokazuje rzutki tego stanowiska. Przed zawodami nikt nie może trenować na osiach zawodów.", "Na treningu pokaz to ulubiony moment trenera: „watch where it turns” — zobacz, gdzie skręca. Na zawodach pokaz jest częścią konkurencji, więc zakaz udzielania wskazówek obowiązuje także tutaj: milcz, chyba że sędzia lub strzelec potrzebuje tłumaczenia w sprawie proceduralnej."], "key_points": ["Wszystkie tory lotu pokazuje się pierwszemu strzelcowi, stojącemu gotowo na stanowisku.", "Powtórki na prośbę: do dwóch na każdy rzutek z menu.", "Dubletów na zawołanie nigdy się nie pokazuje; symultaniczne i rafale tak.", "Broń otwarta podczas pokazu; bez strzelania i pozorowanego strzelania.", "Przerwa dłuższa niż 10 minut: rzutki pokazuje się ponownie."], "terms": ["target-presentation", "target-menu", "double-on-report", "simultaneous-double", "rafale-double", "mock-shooting", "practice", "red-card"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch16-long-interruption", "label": "16 · Interruption over 10 minutes"}, {"book": "sporting", "id": "ch15-no-practice", "label": "15 · No practice on competition layouts"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}], "coach_says": [{"en": "Show me the targets, please.", "meaning": "Strzelec do sędziego: proszę rozpocząć pokaz.", "say": "Proszę pokazać rzutki."}, {"en": "Again, please, B only.", "meaning": "Prośba o powtórzenie jednego rzutka z menu.", "say": "Jeszcze raz, proszę, tylko B."}, {"en": "Guns open during the show.", "meaning": "Sędzia: otworzyć i rozładować broń, aż pozwoli ją zamknąć.", "say": "Podczas pokazu broń otwarta."}, {"en": "Watch where it turns.", "meaning": "Trener na treningu: zauważ punkt, w którym rzutek zmienia kierunek lub kształt.", "say": "Zobacz, gdzie skręca."}], "quiz": [{"q": "Których dubletów NIE pokazuje się podczas pokazu?", "options": ["Symultanicznych", "Rafale", "Na zawołanie", "Żadnych: pokazuje się wszystkie"], "answer": 2, "why": "Drugi rzutek dubletu na zawołanie wylatuje dopiero na strzał, więc tych dubletów się nie pokazuje."}, {"q": "Ile powtórek rzutka może poprosić strzelec na stanowisku?", "options": ["Żadnej", "Do dwóch na każdy rzutek z menu", "Tyle, ile potrzeba", "Jedną na stanowisko"], "answer": 1, "why": "Na prośbę sędzia powtarza pokaz, maksymalnie dwa rzutki dla każdego rzutka z sekwencji menu."}, {"q": "Podczas pokazu strzelec zamyka broń i prowadzi ją po linii rzutka. Co obowiązuje?", "options": ["To zabronione: stosuje się kary jak za pozycję broni — ostrzeżenie, potem czerwona kartka", "Nic: pokaz jest swobodny", "Rzutek pokazuje się ponownie", "Ostrzeżenie dostaje tylko trener"], "answer": 0, "why": "Podczas pokazu broń pozostaje otwarta, a strzelanie lub pozorowane strzelanie karze się według zasad ostrzeżenia i czerwonej kartki."}]}, {"id": "sporting-malfunctions", "minutes": 5, "title": "Awarie broni i amunicji", "body": ["Awaria to niesprawność broni lub naboju: niewypał, niedziałająca druga lufa albo obie lufy wystrzeliwujące jednocześnie (podwójny wystrzał). W Parcours de Chasse – Sporting™ zdarzenia liczy się w ramach serii 25 rzutków.", "Najpierw — co musi zrobić strzelec: zostać na miejscu, z bronią skierowaną w pole strzelania, nie otwierając jej i nie dotykając bezpiecznika, dopóki sędzia jej nie obejrzy. Wcześniejsze otwarcie broni lub dotknięcie bezpiecznika oznacza, że rzutek lub rzutki liczą się jako zero.", "Pierwsze zdarzenie w serii to No Bird z ostrzeżeniem, a rzutek się powtarza. Od drugiego zdarzenia w tej samej serii rzutek nie jest już powtarzany, lecz liczony jako zero.", "Szczegóły pierwszego zdarzenia: jeśli zawiedzie pierwszy strzał, rzutek pojedynczy lub dowolny dublet się powtarza, ale jeśli strzelec mimo to odda drugi strzał, ten wynik zostaje. Jeśli przy rzutku pojedynczym zawiedzie drugi strzał, rzutek się powtarza i wtedy można go rozbić tylko drugim strzałem; rozbicie pierwszym strzałem to zero. Przy dublecie na zawołanie wynik pierwszego zostaje, a dublet się powtarza. Podwójny wystrzał przy rzutku pojedynczym lub przy pierwszym rzutku dowolnego dubletu to No Bird bez żadnego zapisu.", "Jeśli broń zostanie naprawiona, zanim grupa skończy stanowisko, strzelec może za zgodą sędziego strzelać jako ostatni; w przeciwnym razie może od razu kontynuować z inną bronią albo dokończyć w innej grupie za zgodą jury. Po wejściu na stanowisko nie wolno zmieniać broni, czoka ani lufy."], "key_points": ["Po awarii: zostań na miejscu, broń w stronę pola strzelania, nie otwieraj jej i nie dotykaj bezpiecznika.", "Pierwsze zdarzenie w serii: No Bird + ostrzeżenie, rzutek powtórzony.", "Drugie zdarzenie w tej samej serii: zero, bez powtórki.", "Awaria drugiego strzału przy rzutku pojedynczym: przy powtórce liczy się tylko rozbicie drugim strzałem."], "terms": ["malfunction", "double-discharge", "no-bird", "zero", "safety-catch", "round", "choke", "barrel"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}, {"book": "sporting", "id": "ch6-malfunction-first-shot", "label": "6 · Malfunction on the first shot"}, {"book": "sporting", "id": "ch6-malfunction-second-shot", "label": "6 · Malfunction on the second shot"}, {"book": "sporting", "id": "ch6-second-malfunction", "label": "6 · Second malfunction in the same round"}, {"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch7-double-discharge", "label": "7 · Double discharge due to a gun fault"}, {"book": "sporting", "id": "ch7-malfunction-procedure", "label": "7 · What happens after a gun malfunction"}, {"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}], "coach_says": [{"en": "Stay there, don't open the gun.", "meaning": "Sędzia: czekaj na sprawdzenie; wcześniejsze otwarcie kosztuje rzutek.", "say": "Zostań tam, nie otwieraj broni."}, {"en": "Let me see the gun.", "meaning": "Sędzia sprawdza broń lub nabój.", "say": "Pokaż mi broń."}, {"en": "Malfunction. No Bird, first warning.", "meaning": "Pierwsze zdarzenie w serii: rzutek się powtarza.", "say": "Awaria. No Bird, pierwsze ostrzeżenie."}, {"en": "Second malfunction this round. Zero.", "meaning": "Tym razem bez powtórki; rzutek jest stracony.", "say": "Druga awaria w tej serii. Zero."}], "quiz": [{"q": "Pierwszy problem z bronią w serii: przy rzutku pojedynczym pierwszy nabój nie wypala. Strzelec czeka z bronią w stronę pola strzelania na sędziego. Decyzja?", "options": ["Zero", "No Bird z ostrzeżeniem; rzutek się powtarza", "Trafiony", "Żółta kartka i zero"], "answer": 1, "why": "Pierwsze zdarzenie z bronią lub amunicją w serii to No Bird z ostrzeżeniem, a rzutek pojedynczy się powtarza."}, {"q": "Nabój nie wypala, a zirytowany strzelec łamie broń, żeby obejrzeć spłonkę, zanim podejdzie sędzia. Decyzja?", "options": ["No Bird", "Rzutek się powtarza po ostrzeżeniu", "Zero", "Czerwona kartka, a rzutek się powtarza"], "answer": 2, "why": "Otwarcie broni lub dotknięcie bezpiecznika przed sprawdzeniem przez sędziego oznacza, że rzutek liczy się jako zero."}, {"q": "Rzutek pojedynczy, pierwsze zdarzenie: pierwszy strzał chybia, a drugi nabój nie wypala, więc rzutek się powtarza. Przy powtórce strzelec rozbija go pierwszym strzałem. Decyzja?", "options": ["Trafiony", "Znowu No Bird", "Trafiony, z ostrzeżeniem", "Zero: przy tej powtórce liczy się tylko rozbicie drugim strzałem"], "answer": 3, "why": "Po awarii drugiego strzału powtórzony rzutek pojedynczy można rozbić tylko drugim strzałem, więc pierwszy musi być celowo chybiony."}]}, {"id": "sporting-time-and-lateness", "minutes": 5, "title": "Limity czasu i spóźnienia", "body": ["Parcours de Chasse – Sporting™ ma ciasny rytm i chroni go kilka przepisów. Gdy strzelec woła „pull” lub „ready”, sędzia przekazuje komendę operatorowi wyrzutni sygnałem dźwiękowym, a rzutek musi wylecieć w ciągu trzech sekund; późniejszy rzutek to No Bird.", "Między rzutkami pojedynczymi albo między dubletami strzelec ma najwyżej 15 sekund. Za pierwszym przekroczeniem sędzia udziela ostrzeżenia; potem stosuje się kary z czerwoną kartką. Po ostatecznej decyzji w sprawie protestu strzelec musi wznowić strzelanie w ciągu 15 sekund, inaczej liczy się to jako odmowa podporządkowania się; celowe przeciąganie czasu traktuje się tak samo.", "Spóźnienie: gdy brakuje strzelca, sędzia wywołuje jego nazwisko i numer trzy razy w ciągu jednej minuty. Przybycie przed swoją kolejką na rzutkach pojedynczych pierwszego stanowiska nic nie kosztuje. Później każdy niestrzelany rzutek to zero; dołączenie na późniejszym stanowisku oznacza zera za wszystkie rzutki wcześniejszych stanowisk. Osi z opuszczonymi stanowiskami nigdy nie można przestrzelać ponownie w innej grupie.", "Strzelec spóźniony z przyczyn od siebie niezależnych nie może w tej serii wrócić do grupy, lecz odwołuje się na piśmie do jury. Jeśli jury uzna odwołanie, serię strzela się w innej grupie; jeśli nie, 25 zer za każdą nieprzestrzelaną oś.", "Wejście na stanowisko bez ochronników słuchu lub okularów strzeleckich liczy się jako nieobecność. Przy nieplanowanej dogrywce strzelcy muszą być gotowi w ciągu 15 minut od wezwania.", "Dla ciebie: nigdy nie wstrzymuj grupy długim tłumaczeniem. Krótko teraz, szczegóły po stanowisku."], "key_points": ["Rzutek w ciągu 3 sekund od sygnału sędziego, inaczej No Bird.", "Maks. 15 sekund między rzutkami pojedynczymi lub dubletami: ostrzeżenie, potem czerwona kartka.", "Wznowienie w ciągu 15 sekund po ostatecznej decyzji, inaczej odmowa podporządkowania się.", "Spóźnienie: nazwisko i numer wywołane trzy razy w ciągu minuty; opuszczone rzutki to zero."], "terms": ["call", "trapper", "no-bird", "firing-time", "red-card", "jury", "hearing-protection", "safety-glasses", "shoot-off"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch10-deliberate-delay", "label": "10 · Deliberate delay or unfair behaviour"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch16-late-excuse", "label": "16 · Lateness beyond the shooter's control"}, {"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}], "coach_says": [{"en": "Shooter number twenty-three!", "meaning": "Sędzia wywołuje nieobecnego strzelca (trzy razy w ciągu minuty).", "say": "Strzelec numer dwadzieścia trzy!"}, {"en": "Watch your time.", "meaning": "Przypomnienie o 15-sekundowym limicie między rzutkami.", "say": "Pilnuj czasu."}, {"en": "Over fifteen seconds. This is a warning.", "meaning": "Pierwsze przekroczenie limitu: ostrzeżenie; następnym razem kara.", "say": "Ponad piętnaście sekund. To jest ostrzeżenie."}, {"en": "Glasses on, or you can't shoot.", "meaning": "Bez ochrony oczu strzelec jest traktowany jako nieobecny.", "say": "Załóż okulary, inaczej nie możesz strzelać."}], "quiz": [{"q": "Strzelec woła, sędzia przekazuje sygnał, ale rzutek wylatuje około pięciu sekund później. Strzelec strzela i chybia. Decyzja?", "options": ["Zero", "No Bird", "Trafiony", "Ostrzeżenie dla strzelca"], "answer": 1, "why": "Rzutek wyrzucony później niż trzy sekundy po sygnale sędziego to No Bird."}, {"q": "Strzelec przychodzi, gdy jego grupa jeszcze strzela rzutki pojedyncze na stanowisku 1, zanim przyszła jego kolej. Co się dzieje?", "options": ["Dołącza bez kary", "25 zer", "Zero na wszystkich rzutkach pojedynczych stanowiska 1", "Musi strzelać z inną grupą"], "answer": 0, "why": "Przybycie przed przegapieniem swojej kolejki na rzutkach pojedynczych pierwszego stanowiska nie pociąga kary."}, {"q": "Między dwoma rzutkami pojedynczymi strzelec potrzebuje około 25 sekund, pierwszy raz tego dnia. Decyzja?", "options": ["Zero na następnym rzutku", "Czerwona kartka", "Żadnych konsekwencji", "Ostrzeżenie od sędziego"], "answer": 3, "why": "Limit to 15 sekund; za pierwszym przekroczeniem sędzia ostrzega i dopiero potem następują kary."}]}]}, {"id": "compak", "icon": "grid", "title": "Przepisy Compak® Sporting", "intro": "Compak® Sporting mieści różnorodność Parcours de Chasse – Sporting™ na małym polu: pięć stanowisk w linii, sześć wyrzutni i stały prostokąt, nad którym muszą przelatywać rzutki. Wiele przepisów wygląda tak samo, ale pozycja broni, limity czasu, dublety i kary są inne. Tłumacz, który pomyli obie dyscypliny, poda strzelcowi błędne informacje.", "lessons": [{"id": "compak-layout-rotation", "minutes": 5, "title": "Pole, menu i kolejność strzelania", "body": ["Pole Compak® Sporting jest z założenia zwarte. Rzutki muszą przelatywać nad oznaczonym prostokątem o szerokości od 35 do 40 m i głębokości 25 m, z flagą lub znacznikiem w każdym rogu. Naprzeciw niego stoi pięć stanowisk strzeleckich, każde to kwadrat 1 m, w linii 4 do 8 m za przednim bokiem prostokąta; stanowisko 3 jest pośrodku.", "Jest sześć wyrzutni oznaczonych literami od A do F, od lewej do prawej, każda z tablicą. Każdy Compak® musi zawierać rzutek poprzeczny lecący z lewej na prawą, rzutek poprzeczny z prawej na lewą i rzutek odlatujący; pozostałe tory lotu wybiera organizator. Każde stanowisko ma ogranicznik kąta strzału (firing angle limiter) — ramę, która nie pozwala zbyt daleko przenieść broni i utrzymuje strzelca wewnątrz stanowiska.", "Seria to 25 rzutków, po pięć na każdym stanowisku: pięć pojedynczych, trzy pojedyncze i dublet albo jeden pojedynczy i dwa dublety. Na jednym Compak® rodzaj dubletu jest taki sam na wszystkich stanowiskach. Menu, czyli kolejność rzutków, wywiesza się na każdym stanowisku, a pierwszym rzutkiem każdego dubletu jest ostatni rzutek strzelany na poprzednim stanowisku.", "Kolejność strzelania w grupie do sześciu osób: zawsze zaczyna stanowisko 1, a szósty strzelec czeka za nim. Gdy strzelec na stanowisku 5 skończy, idzie czekać za stanowiskiem 1, wszyscy przesuwają się o jedno stanowisko w prawo, a czekający strzelec wchodzi na stanowisko 1. Stanowiska zmienia się z bronią otwartą i rozładowaną, nie przeszkadzając tym, którzy jeszcze strzelają.", "Compak® in-line działa inaczej: każdy strzelec z grupy przechodzi od stanowiska 1 do stanowiska 5."], "key_points": ["Prostokąt 35–40 m × 25 m; pięć stanowisk 1 m; sześć wyrzutni A–F.", "Obowiązkowo: rzutek poprzeczny z lewej na prawą, z prawej na lewą i rzutek odlatujący.", "Seria = 25 rzutków, 5 na stanowisko; jeden rodzaj dubletu na Compak®.", "Każdy dublet zaczyna się od ostatniego rzutka z poprzedniego stanowiska.", "Po stanowisku 5: czekasz za stanowiskiem 1; wszyscy przesuwają się o jedno w prawo."], "terms": ["trap", "target-menu", "round", "squad", "rotation", "crosser", "going-away", "shooting-stand", "double", "fly-over-rectangle", "firing-angle-limiter", "waiting-position"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch3-free-trajectories", "label": "3 · Free trajectories"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-squads-groups", "label": "17 · Size of squads and groups"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Move one station to the right.", "meaning": "Zmiana kolejności po tym, jak strzelec na stanowisku 5 skończył.", "say": "Przejdź o jedno stanowisko w prawo."}, {"en": "Gun open when you change stations.", "meaning": "Między stanowiskami broń jest otwarta i rozładowana.", "say": "Broń otwarta przy zmianie stanowiska."}, {"en": "Your double starts with the last target of the previous station.", "meaning": "Zasada łańcucha w menu Compak®.", "say": "Twój dublet zaczyna się od ostatniego rzutka z poprzedniego stanowiska."}, {"en": "You're waiting behind one.", "meaning": "Szósty strzelec stoi za stanowiskiem 1.", "say": "Czekasz za jedynką."}], "quiz": [{"q": "Ile wyrzutni i stanowisk ma pole Compak® Sporting?", "options": ["4 wyrzutnie, 3 stanowiska", "6 wyrzutni, 5 stanowisk", "5 wyrzutni, 5 stanowisk", "8 wyrzutni, 6 stanowisk"], "answer": 1, "why": "Compak® ma sześć wyrzutni, od A do F, i pięć stanowisk strzeleckich."}, {"q": "Strzelec na stanowisku 5 skończył swoje menu. Dokąd idzie?", "options": ["Na stanowisko 1", "Zostaje na stanowisku 5", "Za stanowisko 1, żeby czekać", "Do sędziego, by podpisać kartę"], "answer": 2, "why": "Staje się czekającym strzelcem za stanowiskiem 1, a wszyscy pozostali przesuwają się o jedno stanowisko w prawo."}, {"q": "Na Compak® pierwszym rzutkiem każdego dubletu jest…", "options": ["dowolny rzutek wybrany przez strzelca", "zawsze wyrzutnia A", "rzutek pokazywany tylko na prośbę", "ostatni rzutek strzelany na poprzednim stanowisku"], "answer": 3, "why": "Menu łączy stanowiska w łańcuch: każdy dublet zaczyna się od rzutka, który zakończył poprzednie stanowisko."}]}, {"id": "compak-gun-and-call", "minutes": 5, "title": "Pozycja broni, komenda i czas", "body": ["Tu Compak® Sporting najwyraźniej różni się od Parcours de Chasse – Sporting™. Przy komendzie pozycja broni jest dowolna: broń może być już przy ramieniu albo nie. Nie ma startu z bronią opuszczoną ani linii na kamizelce. Do każdego rzutka nadal strzela się z bronią przy ramieniu.", "Zwalnianie: wyrzutnie uruchamia się ręcznie, pilotem albo systemem sterowanym głosem (sonopull). Przy zwalnianiu ręcznym rzutek musi wylecieć od 0 do 3 sekund po komendzie; sonopull ma stałe opóźnienie 0,5 sekundy. Na międzynarodowych zawodach in-line używa się wyłącznie sonopull. Rzutek wyrzucony później niż 3 sekundy po komendzie albo taki, którego strzelec nie wołał, to No Bird.", "Czas: strzelec ma najwyżej 10 sekund na komendę od chwili, gdy oddano strzał do rzutka z poprzedniego stanowiska — mniej niż 15 sekund w Sporting™. Za pierwszym razem sędzia zapisuje ostrzeżenie na karcie wyników; jeśli zdarzy się to ponownie w tej samej serii, jest czerwona kartka i rzutki liczy się tak: rzutek pojedynczy zero, dublet na zawołanie (on report) zero i No Bird, dublet symultaniczny zero i zero.", "Pokaz: przy strzelaniu w grupach rzutki pokazuje się raz rano, pierwszej grupie. Strzelec na stanowisku 1 woła każdy rzutek pojedynczy, od A do F; następnie sędzia pokazuje dublety symultaniczne i mówi „start” albo „competition”. Po przerwie dłuższej niż 10 minut sześć rzutków pojedynczych pokazuje się ponownie.", "Ładowanie: tylko na własnym stanowisku, broń otwarta i skierowana w stronę pola strzelania wewnątrz ogranicznika kąta; zamyka się ją dopiero, gdy przychodzi twoja kolej."], "key_points": ["Pozycja broni przy komendzie dowolna; strzał zawsze z ramienia.", "Zwalnianie ręczne 0–3 s po komendzie; sonopull stałe 0,5 s; później niż 3 s = No Bird.", "Maks. 10 sekund na komendę: zapisane ostrzeżenie, potem rzutki liczone jako zero.", "Rzutki pokazuje się raz rano pierwszej grupie; ponownie po przerwie dłuższej niż 10 minut."], "terms": ["ready-position", "call", "sonopull", "no-bird", "firing-time", "score-sheet", "target-presentation", "loading"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}], "coach_says": [{"en": "Start! / Competition!", "meaning": "Sędzia: pokaz się skończył, zaczyna się strzelanie liczone do wyniku.", "say": "Start! / Zawody!"}, {"en": "Gun up or down, your choice here.", "meaning": "Trener: w Compak® pozycja broni przy komendzie jest dowolna.", "say": "Broń w górze albo w dole, tutaj jak wolisz."}, {"en": "Ten seconds, call your target.", "meaning": "Przypomnienie o 10-sekundowym limicie na komendę.", "say": "Dziesięć sekund, wołaj rzutek."}, {"en": "Warning: time.", "meaning": "Pierwsze przekroczenie 10 sekund; zapisane na karcie wyników.", "say": "Ostrzeżenie: czas."}], "quiz": [{"q": "W Compak® Sporting strzelec woła rzutek z bronią już przy ramieniu. Jaka jest decyzja sędziego?", "options": ["Żółta kartka", "Dozwolone: pozycja broni przy komendzie jest dowolna", "Zero", "Dozwolone tylko przy dubletach"], "answer": 1, "why": "Compak® Sporting nie ma startu z bronią opuszczoną ani linii na kamizelce; tylko sam strzał musi paść z ramienia."}, {"q": "Zwalnianie ręczne. Rzutek wylatuje około czterech sekund po komendzie, a strzelec chybia. Decyzja?", "options": ["Zero", "Trafiony", "Ostrzeżenie tylko dla operatora wyrzutni, zero zostaje", "No Bird"], "answer": 3, "why": "Rzutek wyrzucony później niż 3 sekundy po komendzie to No Bird i jest wyrzucany ponownie."}, {"q": "Strzelec po raz drugi w tej samej serii potrzebuje więcej niż 10 sekund na komendę. Rzutek jest pojedynczy. Decyzja?", "options": ["Zero", "Tylko kolejne ostrzeżenie", "No Bird", "Wykluczenie"], "answer": 0, "why": "Po pierwszym ostrzeżeniu powtórzenie w tej samej serii jest karane według tabeli: rzutek pojedynczy liczy się jako zero."}]}, {"id": "compak-singles-doubles", "minutes": 5, "title": "Rzutki pojedyncze i dublety w Compak®", "body": ["Compak® Sporting używa tych samych słów co Parcours de Chasse – Sporting™, ale jego dublety rządzą się innymi zasadami. Tłumacz, który przeniesie przepisy Sporting™, udzieli błędnych odpowiedzi.", "Rzutki pojedyncze: każdy rzutek pojedynczy musi umożliwiać oddanie dwóch strzałów z każdego z pięciu stanowisk, więc druga lufa to uprawniona druga szansa.", "Przepisy Compak® określają dwa rodzaje dubletu: na zawołanie (on report — komenda zwalnia pierwszy rzutek, strzał zwalnia drugi; z jednej lub dwóch wyrzutni) i symultaniczny (dwa rzutki na jedną komendę, zawsze z dwóch różnych wyrzutni, strzelane w dowolnej kolejności). Nie ma dubletu rafale.", "Kluczowa różnica: w dublecie Compak® do każdego rzutka można oddać tylko jeden nabój. Oddanie obu strzałów do pierwszego rzutka jest zabronione, a skrócony przewodnik dla sędziów liczy celowy podwójny strzał do jednego rzutka jako zero i zero. W Sporting™ oba naboje można oddać do jednego rzutka.", "Dwa rzutki jednym strzałem: przy dublecie na zawołanie pierwszy wynik zostaje, drugi rzutek to No Bird i dublet strzela się ponownie. Przy dublecie symultanicznym to No Bird bez żadnego zapisu i dublet się powtarza; tak samo za drugim razem; za trzecim razem jest zero i zero. W Sporting™ taki sam strzał to po prostu trafiony i trafiony.", "Rzutki nieprawidłowe: jeśli pierwszy rzutek dubletu na zawołanie albo którykolwiek rzutek dubletu symultanicznego jest nieprawidłowy, wyrzuca się nowy dublet. Jeśli drugi rzutek dubletu na zawołanie jest nieprawidłowy albo został rozbity przez pierwszy, pierwszy wynik zostaje, a dublet się powtarza."], "key_points": ["Tylko dwa rodzaje dubletu: na zawołanie i symultaniczny; bez rafale.", "Jeden nabój na rzutek w dublecie; oba do jednego rzutka = zero i zero (skrócony przewodnik).", "Dublet na zawołanie, dwa jednym strzałem: pierwszy wynik zostaje, drugi No Bird, dublet powtórzony.", "Symultaniczny, dwa jednym strzałem: dwa razy No Bird, za trzecim razem zero i zero."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch3-two-with-one-report", "label": "3 · Double on report: both targets broken with one shot"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}, {"book": "compak", "id": "ch20-target-no-bird-actions", "label": "20 · What happens after a target NO BIRD"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}], "coach_says": [{"en": "One shot per bird on the pairs here.", "meaning": "Trener: w Compak® do każdego rzutka dubletu jest tylko jeden nabój.", "say": "Tutaj w dubletach jeden strzał na rzutek."}, {"en": "Both with one shot. No Bird, shoot the double again.", "meaning": "Sędzia przy dublecie symultanicznym: nic nie liczymy, powtórka.", "say": "Oba jednym strzałem. No Bird, dublet jeszcze raz."}, {"en": "Choose your order on the show.", "meaning": "Trener: podczas pokazu zdecyduj, który rzutek symultaniczny bierzesz pierwszy.", "say": "Na pokazie wybierz kolejność."}, {"en": "Zero, zero.", "meaning": "Sędzia: żaden rzutek dubletu nie jest zaliczony.", "say": "Zero, zero."}], "quiz": [{"q": "Dublet symultaniczny w Compak®. Jeden strzał rozbija oba rzutki; zdarza się to po raz pierwszy. Decyzja?", "options": ["Trafiony i trafiony", "No Bird, nic nie liczymy, dublet się powtarza", "Trafiony i No Bird", "Zero i zero"], "answer": 1, "why": "W Compak® dublet symultaniczny rozbity jednym strzałem to No Bird za pierwszym i drugim razem, a zero i zero za trzecim."}, {"q": "Dublet na zawołanie w Compak®. Jeden strzał rozbija oba rzutki. Decyzja?", "options": ["Trafiony i trafiony", "Zero i zero", "Pierwszy wynik zostaje, drugi to No Bird, dublet się powtarza", "No Bird, nic nie liczymy"], "answer": 2, "why": "Przy dublecie na zawołanie zapisuje się wynik pierwszego rzutka, a dublet strzela się ponownie, by rozstrzygnąć drugi."}, {"q": "W dublecie Compak® strzelec chybia pierwszy rzutek i celowo oddaje do niego także drugi nabój. Jak liczy to skrócony przewodnik dla sędziów?", "options": ["Zero i zero", "To dozwolone, jak w Sporting™", "Dublet się powtarza", "Liczy się tylko drugi strzał"], "answer": 0, "why": "W dublecie Compak® dozwolony jest tylko jeden nabój na rzutek; celowy podwójny strzał do jednego rzutka to zero i zero."}]}, {"id": "compak-malfunctions", "minutes": 5, "title": "Awarie w Compak®", "body": ["W Compak® Sporting, tak jak w Parcours de Chasse – Sporting™, awarie broni i amunicji liczy się w ramach serii 25 rzutków: pierwsze zdarzenie oznacza No Bird i żółtą kartkę; przy drugim zdarzeniu tego samego rodzaju rzutki, do których nie strzelano, liczy się jako zero, z czerwoną kartką.", "Co musi zrobić strzelec: zostać na miejscu, z bronią skierowaną w pole strzelania, nie otwierając jej i nie dotykając bezpiecznika, dopóki sędzia jej nie sprawdzi. Otwarcie broni wcześniej kosztuje rzutek lub rzutki: zero.", "Pierwsze zdarzenie, gdy obie lufy wystrzelą jednocześnie albo zawiedzie pierwszy nabój: rzutek pojedynczy wyrzuca się ponownie, dublet na zawołanie albo symultaniczny wyrzuca się ponownie i z nieudanej próby nic się nie liczy. Gdy zawiedzie drugi nabój: przy rzutku pojedynczym rzutek wyrzuca się ponownie, ale liczyć się może tylko drugi strzał, więc pierwszy musi być celowo chybiony; przy dublecie na zawołanie pierwszy wynik zostaje, a dublet powtarza się dla drugiego rzutka; przy dublecie symultanicznym — nowy dublet.", "Po awarii strzelec ma dwie minuty na naprawę lub wymianę broni. Wyjątkowo może pożyczyć broń od strzelca spoza własnej grupy, za zgodą właściciela i sędziego. Bez sprawnej broni pozostałe rzutki to zero. Poza tym w trakcie serii nie wolno wymieniać broni, czoka (choke) ani lufy.", "Ta sama logika dotyczy rabbita chybionego pierwszym strzałem, który pęka przed drugim strzałem: No Bird, a przy powtórce liczy się tylko drugi strzał."], "key_points": ["Pierwsze zdarzenie w serii: No Bird + żółta kartka; drugie tego samego rodzaju: zero + czerwona kartka.", "Nie otwieraj broni ani nie dotykaj bezpiecznika przed sprawdzeniem przez sędziego.", "Awaria drugiego naboju przy rzutku pojedynczym: przy powtórce liczy się tylko drugi strzał.", "Dwie minuty na naprawę lub wymianę; pożyczyć tylko spoza grupy, za zgodą właściciela i sędziego."], "terms": ["malfunction", "double-discharge", "safety-catch", "no-bird", "zero", "yellow-card", "red-card", "rabbit", "choke"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch20-gun-failure-principle", "label": "20 · Gun or cartridge failures: first and second incident"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-malfunction", "label": "21 · Malfunction: inspection, 2 minutes, replacement gun"}, {"book": "compak", "id": "ch20-gun-failure-first-shot", "label": "20 · Both barrels fire together or the first cartridge fails"}, {"book": "compak", "id": "ch20-gun-failure-second-shot", "label": "20 · The second cartridge fails"}, {"book": "compak", "id": "ch12-borrowing", "label": "12 · Borrowing a gun after a breakdown"}, {"book": "compak", "id": "ch13-shared-gun", "label": "13 · No sharing a gun within a group"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}], "coach_says": [{"en": "Don't move, keep the gun closed.", "meaning": "Sędzia: po awarii czekaj na sprawdzenie broni.", "say": "Nie ruszaj się, broń zostaje zamknięta."}, {"en": "First malfunction. Yellow card, No Bird.", "meaning": "Pierwsze zdarzenie tego rodzaju w serii; rzutek zostanie wyrzucony ponownie.", "say": "Pierwsza awaria. Żółta kartka, No Bird."}, {"en": "You have two minutes.", "meaning": "Czas na naprawę lub wymianę broni.", "say": "Masz dwie minuty."}, {"en": "Only the second shot counts on this one.", "meaning": "Powtórka po awarii drugiego naboju: pierwszym strzałem chyb celowo.", "say": "Tutaj liczy się tylko drugi strzał."}], "quiz": [{"q": "Pierwsze zdarzenie w serii w Compak®: przy rzutku pojedynczym zawodzi pierwszy nabój. Strzelec prawidłowo czeka. Decyzja?", "options": ["No Bird z żółtą kartką; wyrzuca się nowy rzutek", "Zero", "Czerwona kartka i zero", "Trafiony"], "answer": 0, "why": "Pierwsze zdarzenie z bronią lub amunicją w serii to No Bird z pierwszym ostrzeżeniem w postaci żółtej kartki."}, {"q": "Broń strzelca się psuje. Chce pożyczyć broń od kolegi z grupy. Czy to dozwolone?", "options": ["Tak, za zgodą właściciela", "Tak, jeśli sędzia się zgodzi", "Tak, bez warunków", "Nie: pożyczający musi być spoza jego grupy, a zgodzić się muszą właściciel i sędzia"], "answer": 3, "why": "Compak® zabrania dzielenia się bronią w obrębie grupy; wyjątkowe pożyczenie jest możliwe tylko spoza niej, za obiema zgodami."}, {"q": "Druga awaria broni tego samego rodzaju w tej serii, przy rzutku pojedynczym, do którego strzelec nie mógł strzelić. Decyzja?", "options": ["Znowu No Bird", "No Bird i ostrzeżenie", "Zero, z czerwoną kartką", "Rzutek pokazuje się ponownie"], "answer": 2, "why": "Od drugiego zdarzenia tego samego rodzaju rzutki, do których nie strzelano, liczy się jako zero."}]}, {"id": "compak-dress-and-conduct", "minutes": 5, "title": "Strój i zachowanie", "body": ["Zawody Compak® Sporting są publiczne, więc strój musi być stosowny i praktyczny. Krótkie szorty są zakazane, ale bermudy kończące się nie wyżej niż 5 cm nad kolanem są w porządku. Górna część ubioru musi mieć co najmniej krótkie rękawy i sięgać do szyi; T-shirt jest w porządku, ale goła klatka piersiowa pod kamizelką nie. Sandały są zabronione na treningu i na zawodach. Numer startowy nosi się na plecach, w pełni widoczny; pierwsze naruszenie to ostrzeżenie, potem sankcje.", "Ochronniki słuchu i okulary są obowiązkowe. Przyjście na stanowisko bez nich liczy się jako nieobecność: strzelec nie strzela.", "Punktualność: zgłoś się do sędziego na czas. Przy strzelaniu w grupach przybycie po tym, jak pierwszy strzelec grupy zawołał pierwszy rzutek, kosztuje 25 zer w serii; odwołanie składa się do jury na piśmie tego samego dnia.", "Zachowanie: udzielanie wskazówek trenerskich w trakcie zawodów jest zabronione; zawodnik dostaje żółtą kartkę, a trener zostaje usunięty z terenu strzelania. Kwestionowanie ostatecznej decyzji po wznowieniu strzelania albo otwarte krytykowanie decyzji przez strzelca lub widza to próba wpływania na sędziego i może skończyć się wykluczeniem. Na koniec każdej serii strzelec podpisuje kartę wyników; odmowa podpisu oznacza utratę prawa do reklamacji.", "W pobliżu stanowiska jesteś częścią publiczności: noś ochronniki, zachowaj ciszę podczas komendy, nigdy nie komentuj decyzji. Czy wolno ci przekazywać słowa trenera w trakcie zawodów — to kwestia otwarta dla FITASC; bezpieczna praktyka to tłumaczyć wyłącznie dla sędziego, jury i organizatora."], "key_points": ["Bez krótkich szortów, bez gołej klatki pod kamizelką, bez sandałów (także na treningu); numer na plecach.", "Bez ochronników słuchu lub okularów na stanowisku = nieobecny, nie strzela.", "Spóźnienie po pierwszej komendzie grupy: 25 zer; możliwe pisemne odwołanie tego samego dnia.", "Bez wskazówek trenerskich; bez publicznej krytyki decyzji; podpisz kartę wyników."], "terms": ["dress-code", "competitor-number", "hearing-protection", "safety-glasses", "conduct", "yellow-card", "score-sheet", "protest", "quiet-on-stand"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-late-appeal", "label": "9 · Appealing a lateness penalty"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}], "coach_says": [{"en": "Number on your back, please.", "meaning": "Sędzia: numer startowy musi być w pełni widoczny na plecach.", "say": "Numer na plecy, proszę."}, {"en": "Ears and eyes on.", "meaning": "Załóż ochronniki słuchu i okulary przed wejściem na stanowisko.", "say": "Ochronniki i okulary założone."}, {"en": "Sign the sheet, please.", "meaning": "Koniec serii: strzelec podpisuje kartę wyników.", "say": "Proszę podpisać kartę."}, {"en": "No coaching on the stand.", "meaning": "Ostrzeżenie sędziego: wskazówki trenerskie są zabronione na zawodach.", "say": "Żadnego trenowania na stanowisku."}], "quiz": [{"q": "Strzelec przychodzi na stanowisko w sandałach na serię treningową. Czy to dozwolone?", "options": ["Tak, tylko na treningu", "Nie: sandały są zabronione na treningu i na zawodach", "Tak, ze skarpetkami", "Tylko za zgodą sędziego"], "answer": 1, "why": "Kodeks ubioru Compak® ze względów bezpieczeństwa zakazuje sandałów na treningu i na zawodach."}, {"q": "Strzelanie w grupach. Strzelec przychodzi tuż po tym, jak pierwszy strzelec jego grupy zawołał pierwszy rzutek. Skutek?", "options": ["Bez kary", "Zero tylko na pierwszym rzutku", "Strzela na końcu grupy", "25 zer w serii; możliwe pisemne odwołanie do jury tego samego dnia"], "answer": 3, "why": "Granicą jest pierwsza komenda grupy; po niej spóźniony strzelec dostaje 25 zer, chyba że jury uzna uzasadniony powód."}, {"q": "Po serii strzelec odmawia podpisania karty wyników, bo nie zgadza się z jedną decyzją. Jaki jest skutek?", "options": ["Traci prawo do jakiejkolwiek reklamacji", "Sędzia musi zmienić wynik", "Serię strzela się ponownie", "Nic się nie dzieje"], "answer": 0, "why": "Podpisanie karty na koniec każdej serii jest obowiązkowe; odmowa podpisu sprawia, że żadna reklamacja nie zostanie przyjęta."}]}]}, {"id": "referee", "icon": "whistle", "title": "Sędzia, punktacja i kary", "intro": "Na zawodach to sędzia jest osobą, której słowa będziesz tłumaczyć najczęściej i najstaranniej. Ta misja daje ci wypowiadane komendy i decyzje, kartę wyników, kartki i kary, procedurę protestu i kategorie wiekowe, żeby każda decyzja docierała do twojego strzelca dokładnie taka, jaka zapadła.", "lessons": [{"id": "referee-calls", "minutes": 5, "title": "Co sędzia mówi na stanowisku", "body": ["Stanowisko ma swój krótki język. Strzelec, gdy jest gotowy, woła rzutek (call), zwykle „Pull!” albo „Ready!”. W Parcours de Chasse – Sporting™ sędzia przekazuje tę komendę operatorowi wyrzutni sygnałem dźwiękowym, a rzutek musi wylecieć w ciągu trzech sekund; późniejszy rzutek to No Bird. W Compak® Sporting zwolnienie ręczne też musi nastąpić w ciągu trzech sekund od komendy, a zwolnienie głosowe (sonopull) ma stałe opóźnienie pół sekundy.", "Zanim ktokolwiek strzeli, sędzia kontroluje broń. Ładować wolno tylko na stanowisku, z bronią skierowaną w pole strzelania, gdy sędzia powie, że można zaczynać. Podczas pokazu rzutków i przy każdej przerwie w strzelaniu broń jest otwarta i pusta, a zamyka się ją ponownie dopiero na słowo sędziego. W Compak® sędzia rozpoczyna serię słowami „Start” albo „Competition”.", "Po każdym rzutku przepisy znają trzy wyniki: „one” (trafiony), „zero” (chybiony) i „No Bird” (rzutek się nie liczy i jest wyrzucany ponownie). Na świecie usłyszysz też „dead”, „good”, „lost” albo po prostu ciszę przy trafieniu. W Compak® sędzia musi ogłosić każde zero głośno lub sygnałem dźwiękowym, żeby strzelec, który się nie zgadza, mógł od razu zaprotestować.", "Strzelec też ma jedno formalne słowo: z uniesioną ręką „Protest!” albo „Appeal!”. Gdy tłumaczysz, wypowiadaj te komendy krótko i za każdym razem identycznie. Przed serią ustal ze strzelcem, jakich słów będziesz używać, i nigdy nie dodawaj nic od siebie między komendą a strzałem."], "key_points": ["Strzelec woła „Pull!” albo „Ready!”; rzutek musi wylecieć w ciągu 3 sekund", "Ładuj tylko na stanowisku i tylko za zgodą sędziego; broń otwarta podczas pokazu i przerw", "Słowa z przepisów: one = trafiony, zero = chybiony, No Bird = wyrzucany ponownie", "Compak®: każde zero ogłasza się głośno lub sygnałem dźwiękowym", "Protest = uniesiona ręka + „Protest!” albo „Appeal!”"], "terms": ["call", "referee", "trapper", "sonopull", "one", "zero", "no-bird", "loading", "target-presentation", "protest"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch5-referee-oath", "label": "5 · Referee's commitments"}, {"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}], "coach_says": [{"en": "You may load.", "meaning": "Sędzia pozwala zacząć strzelanie: włóż teraz naboje, broń skierowana w pole strzelania.", "say": "Można ładować."}, {"en": "No bird!", "meaning": "Ten rzutek się nie liczy; nie strzelaj do niego. Zostanie wyrzucony ponownie.", "say": "No Bird!"}, {"en": "Lost.", "meaning": "Sędzia uznał rzutek za chybiony (zero).", "say": "Chybiony."}, {"en": "Dead. / Good.", "meaning": "Rzutek trafiony (one).", "say": "Trafiony. / Jest."}, {"en": "Guns open, please — we’re showing the targets.", "meaning": "Wszyscy otwierają i rozładowują broń; sędzia wyrzuci rzutki do obejrzenia.", "say": "Broń otworzyć, proszę — pokazujemy rzutki."}, {"en": "Start. / Competition.", "meaning": "Compak®: pokaz się skończył, od teraz seria się liczy.", "say": "Start. / Zawody."}], "quiz": [{"q": "W Parcours de Chasse – Sporting™ rzutek wylatuje pięć sekund po sygnale sędziego. Jaka jest decyzja?", "options": ["Liczy się normalnie", "No Bird", "Zero, bo strzelec zawołał za wcześnie", "Ostrzeżenie tylko dla operatora wyrzutni"], "answer": 1, "why": "Rzutek musi wylecieć w ciągu trzech sekund od sygnału sędziego; późniejszy to No Bird i jest wyrzucany ponownie."}, {"q": "Kiedy strzelec może załadować broń?", "options": ["Idąc na stanowisko", "Za stanowiskiem podczas czekania", "Na stanowisku, z bronią w stronę pola strzelania, gdy sędzia pozwoli zacząć", "Kiedy tylko powie trener"], "answer": 2, "why": "Ładować wolno tylko na stanowisku, w stronę pola strzelania, i dopiero gdy sędzia zezwoli na start."}, {"q": "Jakie słowo rozpoczyna formalny protest na stanowisku?", "options": ["„Protest!” albo „Appeal!” z uniesioną ręką", "„Pull!”", "„No Bird!”", "„Panie sędzio, proszę spojrzeć!”"], "answer": 0, "why": "Przepisy obu dyscyplin wymieniają „protest” lub „appeal” z uniesioną ręką; „No Bird” należy wyłącznie do sędziego."}]}, {"id": "referee-scoring", "minutes": 5, "title": "Karty wyników, rezultaty i remisy", "body": ["Każdy rzutek trafia na kartę wyników. W Parcours de Chasse – Sporting™ kartę prowadzi sędzia albo osoba pod jego nadzorem. Wzór FITASC pokazuje literę wyrzutni każdego rzutka, X za trafienie i O za pudło, sumę i kolumnę na podpis. Zanim grupa przejdzie dalej, sędzia fotografuje kartę.", "Strzelcy muszą sprawdzić swój wynik, schodząc z każdego stanowiska. Niezgodność zgłasza się sędziemu od razu; sędzia decyduje, ewentualnie po zasięgnięciu opinii innych, i od tej decyzji nie ma odwołania. W Compak® Sporting strzelec podpisuje kartę wyników na koniec serii, a strzelec, który odmówi podpisu, traci prawo do reklamacji. Tłumacz „check your card” jako pilne polecenie, a nie uprzejmą uwagę.", "Zawody międzynarodowe to 200 rzutków w seriach po 25. Gdy strzelcy remisują o pierwsze trzy miejsca, strzelają dogrywkę (shoot-off) na 25 rzutków; jeśli nadal jest remis, następuje nagła śmierć (sudden death), w której pierwsze zero eliminuje. Poniżej trzeciego miejsca nie ma dogrywki: zremisowani strzelcy dzielą miejsce i są uszeregowani metodą countback, od ostatniej (ósmej) osi lub Compaku wstecz do pierwszej. Drużyny nigdy nie strzelają dogrywek.", "Dogrywki niosą jeszcze jedną pułapkę dla tłumacza. Jeśli nie ustalono godziny, strzelcy muszą być gotowi w ciągu piętnastu minut od wezwania. Nieobecny strzelec jest w przepisach Sporting™ „zdyskwalifikowany”, a w przepisach Compak® „uznany za wycofanego”. Używaj słowa z dyscypliny, w której jesteś."], "key_points": ["X = trafiony, O = chybiony na kartach wyników FITASC", "Sporting™: sprawdź wynik, schodząc z każdego stanowiska; Compak®: podpisz kartę albo stracisz prawo do reklamacji", "Remis o miejsca 1–3: dogrywka na 25 rzutków, potem nagła śmierć", "Poniżej 3. miejsca: countback od 8. osi lub Compaku; drużyny bez dogrywek", "Gotowość w ciągu 15 minut od wezwania na dogrywkę"], "terms": ["score-sheet", "round", "one", "zero", "shoot-off", "countback", "team", "referee"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}, {"book": "sporting", "id": "ch18-team-ties", "label": "18 · Team ties"}, {"book": "compak", "id": "ch15-who-keeps", "label": "15 · Who keeps the score sheet"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}, {"book": "compak", "id": "ch14-shootoff-availability", "label": "14 · Staying available for a shoot-off"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}, {"book": "compak", "id": "ch14-team-ties", "label": "14 · Ties between national teams"}], "coach_says": [{"en": "Check your card before you leave the stand.", "meaning": "Spójrz teraz na swoje znaki; późniejsze zastrzeżenia nie są przyjmowane.", "say": "Sprawdź kartę, zanim zejdziesz ze stanowiska."}, {"en": "Sign here, please.", "meaning": "Compak®: podpis potwierdza wynik; odmowa oznacza utratę prawa do reklamacji.", "say": "Proszę tu podpisać."}, {"en": "Twenty-three — you dropped two.", "meaning": "Wynik 23 na 25; dwa rzutki chybione.", "say": "Dwadzieścia trzy — dwa pudła."}, {"en": "There’s a tie for third — shoot-off in fifteen minutes.", "meaning": "Bądź na wskazanej osi i gotowy do strzelania w ciągu piętnastu minut.", "say": "Remis o trzecie miejsce — dogrywka za piętnaście minut."}, {"en": "Sudden death: first zero is out.", "meaning": "Po dogrywce na 25 rzutków pierwszy strzelec, który chybi (przy równej liczbie oddanych strzałów do rzutków), odpada.", "say": "Nagła śmierć: pierwsze zero odpada."}], "quiz": [{"q": "Co oznacza O na karcie wyników FITASC?", "options": ["Trafienie", "No Bird", "Pudło", "Puste stanowisko"], "answer": 2, "why": "Wzór FITASC oznacza trafienie przez X, a pudło przez O."}, {"q": "Dwóch strzelców remisuje o 7. miejsce. Co się dzieje?", "options": ["Dogrywka na 25 rzutków", "Od razu nagła śmierć", "Rzut monetą przez jury", "Dzielą miejsce i są uszeregowani metodą countback"], "answer": 3, "why": "Dogrywki są tylko o miejsca 1–3; poniżej zremisowanych strzelców szereguje się metodą countback od ósmej osi lub Compaku."}, {"q": "W Compak® Sporting twój strzelec odmawia podpisania karty wyników. Jaki jest skutek?", "options": ["Traci prawo do jakiejkolwiek reklamacji", "Serię strzela się ponownie", "Podpisuje sędzia i nic się nie zmienia", "Automatycznie dostaje 25 zer"], "answer": 0, "why": "Przepisy Compak® mówią, że strzelec, który odmawia podpisu, traci prawo do reklamacji."}]}, {"id": "referee-cards", "minutes": 5, "title": "Ostrzeżenia, kartki i kary", "body": ["Kary FITASC rosną stopniowo. Zgłaszając się do zawodów, strzelec akceptuje przepisy i sankcje. Pierwsze naruszenie przepisu zwykle oznacza ostrzeżenie, pokazywane żółtą kartką. W Parcours de Chasse – Sporting™ klasycznym przykładem jest pozycja broni: kolba powyżej linii na kamizelce albo broń złożona, zanim pojawi się rzutek, to ustne ostrzeżenie i żółta kartka.", "Powtórzenie na tej samej osi (lub tym samym Compaku) oznacza czerwoną kartkę, a rzutek liczy się według tabeli: zero przy rzutku pojedynczym, zero i No Bird przy dublecie na zawołanie, zero i zero przy dublecie symultanicznym lub rafale. Ta sama skala dotyczy strzelania do ogłoszonego No Bird oraz, w Sporting™, przekroczenia piętnastu sekund między rzutkami. W Compak® Sporting limit to dziesięć sekund na komendę.", "Udzielanie wskazówek trenerskich w trakcie zawodów też jest karane: strzelec dostaje żółtą kartkę, powtórzenia prowadzą do kolejnych sankcji, a sędzia odsyła osobę, która udzielała wskazówek, poza teren strzelania. Dla tłumacza to najważniejsza kartka w przepisach.", "Za powtarzające się wykroczenia, odmowę podporządkowania się albo próby wpływania na sędziego jury może odebrać jeden rzutek, całą serię 25 rzutków albo wykluczyć strzelca. Rzucenie bronią, obrażanie lub przemoc oraz celowe strzelanie do żywych zwierząt mogą oznaczać natychmiastowe wykluczenie. Wykluczenie FITASC odnotowuje na pięć lat i nie wiąże się ze zwrotem wpisowego. Tłumacz „warning”, „yellow card” i „red card” dosłownie, spokojnie i natychmiast."], "key_points": ["Pierwsze naruszenie: ostrzeżenie z żółtą kartką", "Powtórzenie na tej samej osi lub Compaku: czerwona kartka + rzutek liczony według tabeli", "Wskazówki trenerskie na zawodach: żółta kartka dla strzelca, trener usunięty", "Skala jury: jeden rzutek, jedna seria albo wykluczenie", "Wykluczenie: odnotowane na 5 lat, bez zwrotu wpisowego"], "terms": ["yellow-card", "red-card", "penalty", "ready-position", "firing-time", "jury", "conduct"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch13-acceptance", "label": "13 · Acceptance of rules; first breach = warning"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch12-shooting-nobird", "label": "12 · Shooting at a declared No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch13-jury-penalties", "label": "13 · Jury penalty scale"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "sporting", "id": "ch13-immediate-expulsion", "label": "13 · Immediate expulsion"}, {"book": "sporting", "id": "ch13-expulsion-record", "label": "13 · Expulsion record and lifetime ban"}, {"book": "sporting", "id": "ch13-no-refund", "label": "13 · No refund after expulsion"}, {"book": "compak", "id": "ch23-yellow-card", "label": "23 · Accepting the rules; first a yellow card"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch23-exclusion-record", "label": "23 · Exclusions: record, repeat, no refund"}], "coach_says": [{"en": "Warning — your stock was above the line.", "meaning": "Sporting™: broń była za wysoko, zanim pojawił się rzutek; następnym razem na tej osi kosztuje to rzutek.", "say": "Ostrzeżenie — kolba była powyżej linii."}, {"en": "That’s a yellow card.", "meaning": "Oficjalne pierwsze ostrzeżenie; zostaje zapisane.", "say": "To jest żółta kartka."}, {"en": "Red card — the target is zero.", "meaning": "Powtórne wykroczenie: rzutek liczy się jako chybiony.", "say": "Czerwona kartka — rzutek zero."}, {"en": "You’re over time.", "meaning": "Strzelec przekroczył dozwolony czas (15 s w Sporting™, 10 s na komendę w Compak®).", "say": "Przekroczyłeś czas."}, {"en": "Sir, please leave the shooting area.", "meaning": "Sędzia usuwa kogoś, np. osobę przyłapaną na udzielaniu wskazówek.", "say": "Proszę pana, proszę opuścić teren strzelania."}], "quiz": [{"q": "Sporting™: po żółtej kartce za złożoną broń strzelec znowu składa się za wcześnie na tej samej osi, przy rzutku pojedynczym. Jaki jest skutek?", "options": ["Kolejne ostrzeżenie", "Czerwona kartka i rzutek zero", "No Bird", "Natychmiastowe wykluczenie"], "answer": 1, "why": "Po pierwszym ostrzeżeniu kolejne wykroczenie na tej samej osi oznacza czerwoną kartkę; przy rzutku pojedynczym rzutek to zero."}, {"q": "Sędzia widzi, że trener udziela strzelcowi rad w trakcie zawodów. Co mówią przepisy?", "options": ["Nic, wskazówki między stanowiskami są dozwolone", "Trener dostaje czerwoną kartkę", "Strzelec dostaje żółtą kartkę, a trener zostaje usunięty z terenu strzelania", "Seria zostaje anulowana"], "answer": 2, "why": "Przepisy obu dyscyplin dają zawodnikowi żółtą kartkę i nakazują sędziemu odesłać osobę udzielającą wskazówek poza teren strzelania."}, {"q": "Której z tych kar jury NIE może nałożyć według skali kar?", "options": ["Utraty jednego rzutka", "Utraty serii 25 rzutków", "Wykluczenia", "Kary pieniężnej płaconej sędziemu"], "answer": 3, "why": "Skala jury to utrata rzutka, utrata serii albo wykluczenie; nie ma kary pieniężnej na rzecz sędziego."}]}, {"id": "referee-appeals", "minutes": 5, "title": "Protesty, kaucje i jury", "body": ["Protest musi nastąpić na miejscu. Strzelec unosi rękę i mówi „Protest!” albo „Appeal!” na stanowisku, zanim zawoła następny rzutek (w Compak® Sporting — zanim zawoła następny strzelec). Sędzia przerywa strzelanie i wysłuchuje powodu. Wołając następny rzutek, strzelec akceptuje poprzednią decyzję, więc jako tłumacz musisz tu być szybki.", "Jeśli sędzia jest pewien, decyzja zostaje potwierdzona i staje się ostateczna. W razie wątpliwości sędzia może zapytać innego sędziego, operatora wyrzutni albo strzelców z grupy, wyłącznie o opinię, a potem decyduje sam. Strzelcom nigdy nie wolno wychodzić w pole ani podnosić rzutka, by go sprawdzić, a o rzutku rozbitym za naturalną przeszkodą lub poza granicą strzelania decyduje sędzia.", "Niektóre decyzje nigdy nie mogą trafić do jury: czy rzutek był trafiony, czy chybiony, No Bird i czy tor lotu był prawidłowy. Od innych decyzji można się odwołać do jury na piśmie, wpłacając kaucję: w Parcours de Chasse – Sporting™ jest to 40% wpisowego; w Compak® kwota obowiązująca w danym dniu i tylko w sprawie zdarzeń z tego samego dnia. Jeśli odwołanie zostanie uwzględnione, kaucja jest zwracana.", "Po ostatecznej decyzji strzelec musi wznowić strzelanie w ciągu piętnastu sekund w Sporting™ i dziesięciu w Compak®; w przeciwnym razie jest to odmowa podporządkowania się. Dalsze spieranie się, demonstracyjne podważanie sędziego albo otwarta krytyka decyzji przez inne osoby to próba wpływania na sędziego. Twoim zadaniem jest dokładnie przetłumaczyć protest i odpowiedź, a nie spierać się w tej sprawie."], "key_points": ["Protest natychmiast, na stanowisku, z uniesioną ręką: „Protest!” / „Appeal!”", "Zawołanie następnego rzutka = akceptacja poprzedniej decyzji", "Bez odwołania: trafiony/chybiony, No Bird, prawidłowy tor lotu", "Pisemne odwołanie do jury z kaucją (Sporting™: 40% wpisowego)", "Wznowienie w ciągu 15 s (Sporting™) lub 10 s (Compak®); dalsza dyskusja = wpływanie na sędziego"], "terms": ["protest", "appeal", "jury", "referee", "entry-fee", "no-bird", "trajectory"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "sporting", "id": "ch9-consultation", "label": "9 · Referee in doubt: consultation"}, {"book": "sporting", "id": "ch9-jury-appeal", "label": "9 · What can go to the jury and the 40% deposit"}, {"book": "sporting", "id": "ch9-deposit-outcome", "label": "9 · Outcome of a jury appeal"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch15-appeal-jury", "label": "15 · Appeal jury"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}, {"book": "compak", "id": "ch19-consultation", "label": "19 · Referee in doubt: who may be consulted"}, {"book": "compak", "id": "ch4-complaint-limits", "label": "4 · What you cannot complain about"}, {"book": "compak", "id": "ch4-complaint-procedure", "label": "4 · How to lodge a complaint and the deposit"}, {"book": "compak", "id": "ch21-refusal-to-comply", "label": "21 · Refusal to comply: 10 seconds to resume"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Protest! The target was broken before I fired.", "meaning": "Strzelec formalnie kwestionuje decyzję i podaje powód (tu: wyrzucono rozbity rzutek).", "say": "Protest! Rzutek był rozbity, zanim strzeliłem."}, {"en": "I’m certain — the decision stands.", "meaning": "Sędzia potwierdza; decyzja jest ostateczna.", "say": "Jestem pewien — decyzja zostaje."}, {"en": "Did anyone see a piece come off?", "meaning": "Sędzia ma wątpliwości i pyta grupę wyłącznie o opinię; decyduje nadal sędzia.", "say": "Czy ktoś widział, że odpadł kawałek?"}, {"en": "You can take it to the jury in writing, with the deposit.", "meaning": "Od tej decyzji można się odwołać; potrzebne jest pisemne odwołanie i kaucja.", "say": "Może pan to skierować do jury na piśmie, z kaucją."}, {"en": "Please carry on shooting.", "meaning": "Decyzja jest ostateczna; wznów teraz, inaczej będzie to odmowa podporządkowania się.", "say": "Proszę kontynuować strzelanie."}], "quiz": [{"q": "Twój strzelec uważa, że rzutek zaliczony jako zero był trafiony, ale już zawołał następny rzutek. Czy może jeszcze zaprotestować przeciw tej decyzji?", "options": ["Tak, na koniec serii", "Tak, na piśmie do jury", "Nie: zawołanie następnego rzutka oznacza akceptację poprzedniej decyzji", "Tak, jeśli grupa się zgodzi"], "answer": 2, "why": "Wołając następny rzutek, strzelec akceptuje poprzednią decyzję, a decyzje trafiony/chybiony i tak nigdy nie trafiają do jury."}, {"q": "Od której decyzji MOŻNA odwołać się do jury?", "options": ["Czy rzutek był trafiony, czy chybiony", "No Bird", "Czy tor lotu był prawidłowy", "Od innej decyzji sędziego, np. kary za spóźnienie"], "answer": 3, "why": "Decyzje trafiony/chybiony, No Bird i dotyczące toru lotu są ostateczne; od innych decyzji sędziego można odwołać się do jury na piśmie z kaucją."}, {"q": "Jak wysoka jest w Parcours de Chasse – Sporting™ kaucja przy pisemnym odwołaniu do jury?", "options": ["40% wpisowego", "Całe wpisowe", "Stałe 50 euro", "Kaucja nie jest potrzebna"], "answer": 0, "why": "Przepisy Sporting™ ustalają kaucję na 40% wpisowego; jest zwracana, jeśli jury przyzna rację strzelcowi."}]}, {"id": "referee-categories", "minutes": 5, "title": "Kategorie: Junior, Lady, Men, Senior, Veteran, Master", "body": ["Oprócz klasyfikacji otwartej (open), w której wszyscy startują razem, zawody FITASC klasyfikują strzelców w kategoriach według wieku i płci. Od 1 stycznia 2027 r. międzynarodowa tabela dla Parcours de Chasse – Sporting™ i Compak® Sporting ma sześć kategorii: Junior (13–20), Lady (od 13 lat), Men (21–55), Senior (56–65), Veteran (66–72) i Master (od 73 lat, mężczyźni i kobiety). Dla zawodów przed tą datą sprawdź tabelę obowiązującą wówczas na stronie FITASC.", "Liczy się rok urodzenia, a nie dzień urodzin. Strzelec przechodzi do nowej kategorii 1 stycznia roku, w którym osiąga dany wiek. Dla sezonu 2027 oznacza to: Junior — urodzeni w latach 2007–2014, Men — 1972–2006, Senior — 1962–1971, Veteran — 1955–1961, Master — urodzeni przed 1955. Granice przesuwają się co sezon o jeden rok.", "Największa pułapka dla tłumacza to „Senior”. W codziennym angielskim brzmi jak „dorosły”, ale w FITASC Senior oznacza grupę wiekową 56–65; główna kategoria dorosłych to Men. Nie tłumacz tego jako „dorośli”. „Master” to kolejna pułapka: kategoria wiekowa FITASC od 73 lat nie ma nic wspólnego z „Master class” NSCA, która jest poziomem umiejętności.", "Drużyny mają własne zasady: zwykle trzech strzelców, ale drużyna Men w Sporting™ ma czterech. Junior wystawiony w drużynie Men albo juniorka w drużynie Lady musi też indywidualnie startować w tej kategorii. Krajowe federacje i kluby mogą stosować własne kategorie, więc zawsze sprawdzaj program zawodów, a przy dogrywkach pamiętaj, że kategorie mają własną pierwszą trójkę."], "key_points": ["Sześć kategorii FITASC od 2027: Junior, Lady, Men, Senior, Veteran, Master", "Decyduje rok urodzenia; nowa kategoria zaczyna się 1 stycznia", "Senior = 56–65, a nie „dorośli”; główna kategoria dorosłych to Men", "Master FITASC (73+) ≠ Master class NSCA", "Drużyny po 3; drużyna Men w Sporting™ = 4; programy krajowe mogą się różnić"], "terms": ["category", "veteran", "team", "shoot-off", "entry"], "sources": [{"title": "FITASC — Categories", "url": "https://www.fitasc.com/competitions/categories"}], "sim": null, "rule_refs": [{"book": "categories", "id": "junior", "label": "Junior"}, {"book": "categories", "id": "lady", "label": "Lady"}, {"book": "categories", "id": "men", "label": "Men"}, {"book": "categories", "id": "senior", "label": "Senior"}, {"book": "categories", "id": "veteran", "label": "Veteran"}, {"book": "categories", "id": "master", "label": "Master"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}], "coach_says": [{"en": "Which category are you shooting in?", "meaning": "Pytanie przy rejestracji: Junior, Lady, Men, Senior, Veteran czy Master.", "say": "W jakiej kategorii pan startuje?"}, {"en": "He’s a Senior now.", "meaning": "W tym sezonie jest w grupie 56–65.", "say": "Teraz jest już w kategorii Senior."}, {"en": "She won the Lady category and was fourth overall.", "meaning": "Pierwsza wśród pań, czwarta w klasyfikacji otwartej.", "say": "Wygrała kategorię Lady i była czwarta w klasyfikacji generalnej."}, {"en": "There’s a shoot-off for Veteran bronze.", "meaning": "Dwóch lub więcej strzelców w kategorii Veteran remisuje o trzecie miejsce w swojej kategorii.", "say": "Jest dogrywka o brąz w kategorii Veteran."}], "quiz": [{"q": "Strzelec urodzony w 1971 r. startuje w zawodach FITASC w 2027 r. Jaka kategoria?", "options": ["Men", "Senior", "Veteran", "Master"], "answer": 1, "why": "W 2027 r. kończy 56 lat, więc od 1 stycznia jest w kategorii Senior, niezależnie od daty urodzin."}, {"q": "Jak przetłumaczyć klientowi kategorię FITASC „Senior”?", "options": ["„Dorośli”", "„Doświadczeni strzelcy”", "„Najwyższa klasa”", "„Grupa wiekowa 56–65”"], "answer": 3, "why": "W FITASC Senior to grupa wiekowa 56–65; główna kategoria dorosłych to Men."}, {"q": "Ilu strzelców liczy drużyna Men w Parcours de Chasse – Sporting™?", "options": ["Czterech", "Trzech", "Sześciu", "Pięciu"], "answer": 0, "why": "Drużyny mają zwykle trzech strzelców, ale drużyna Men w Sporting™ ma czterech."}]}]}, {"id": "etiquette", "icon": "shield", "title": "Bezpieczeństwo i etykieta", "intro": "Na strzelnicy bezpieczeństwo jest ważniejsze od każdego tłumaczenia, a dobre maniery utrzymują w grupie spokój i skupienie. Ta misja pokazuje, jak obchodzi się z bronią, jak zachowywać się przy stanowisku i w grupie oraz co musi nosić każdy, łącznie z tobą.", "lessons": [{"id": "etiquette-gun-safety", "minutes": 5, "title": "Bezpieczeństwo broni: otwarta, pusta, lufy w bezpiecznym kierunku", "body": ["Każdą broń traktuje się jako niebezpieczną, nawet gdy jest pusta. Poza stanowiskiem nosi się ją otwartą: bok (over-and-under) złamany na przedramieniu, półautomat z otwartym zamkiem, lufy prosto w górę lub prosto w dół. Pasy nośne są niedozwolone. Gdy nikt jej nie używa, broń stoi pionowo w stojaku na broń. Nikt nie dotyka broni innego strzelca bez pozwolenia.", "Naboje wkłada się do broni tylko na stanowisku, z lufami skierowanymi w pole strzelania, i tylko gdy pozwoli na to sędzia lub instruktor. Półautomat może mieć najwyżej dwa naboje. Zanim strzelec odwróci się na stanowisku, otwiera broń i wyjmuje wszystkie naboje, wystrzelone i niewystrzelone. Podczas pokazu rzutków i podczas każdej przerwy broń pozostaje otwarta.", "Jeśli broń nie wystrzeli, strzelec zostaje na miejscu z bronią skierowaną w pole strzelania i nie otwiera jej ani nie dotyka bezpiecznika, dopóki sędzia jej nie sprawdzi. To jednocześnie zasada bezpieczeństwa i zasada liczenia wyniku: zbyt wczesne otwarcie kosztuje rzutek. Składanie się i prowadzenie broni za wyobrażonym rzutkiem poza stanowiskiem albo gdy strzela ktoś inny też jest zabronione, a broń sprawdza się tylko na stanowisku do strzałów próbnych, nigdy na stanowisku zawodów.", "Gdy ktokolwiek krzyknie „Stop!” albo „Cease fire!”, wszyscy natychmiast przerywają i otwierają broń. Nie tłumacz tego jako zdania: powtórz głośno „Stop!” w języku swoich gości i sprawdź, czy ich broń jest otwarta. Jeśli gość odwraca się do ciebie z bronią, by o coś zapytać, najpierw gestem skieruj lufy w dół, a potem tłumacz."], "key_points": ["Poza stanowiskiem: broń otwarta, pusta, lufy w górę lub w dół, bez pasów nośnych", "Ładuj tylko na stanowisku, w stronę pola strzelania, za pozwoleniem; półautomat maks. 2", "Otwórz i rozładuj przed odwróceniem się; broń otwarta podczas pokazu i przerw", "Po niewypale: zostań na miejscu, nie otwieraj, czekaj na sędziego", "„Stop!” się powtarza, a nie objaśnia"], "terms": ["safety", "gun-handling", "muzzle", "gun-rack", "loading", "malfunction", "mock-shooting", "gun-test", "cease-fire", "semi-automatic"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "sporting", "id": "ch7-touching-sharing", "label": "7 · Other shooters' guns; sharing a gun"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "sporting", "id": "ch3-testing-guns", "label": "3 · No test shots on the stand"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-open-gun", "label": "21 · Keep the gun open: turning round, target viewing, interruptions"}, {"book": "compak", "id": "ch11-testing-guns", "label": "11 · Where to test your gun"}], "coach_says": [{"en": "Guns open and empty between stands, please.", "meaning": "Przechodząc na następne stanowisko, broń jest złamana i nie ma w niej nabojów.", "say": "Między stanowiskami broń otwarta i pusta, proszę."}, {"en": "Break your gun and show me it’s clear.", "meaning": "Otwórz (złam) broń — nie uszkodź jej! — żebym widział, że komory są puste.", "say": "Złam broń i pokaż mi, że jest pusta."}, {"en": "Don’t load until you’re on the stand and I say so.", "meaning": "Żadnych nabojów w broni podczas chodzenia ani czekania.", "say": "Nie ładuj, dopóki nie staniesz na stanowisku i ci nie powiem."}, {"en": "Muzzles down when you turn round.", "meaning": "Nigdy nie pozwól, by lufy wskazywały na ludzi, nawet przy otwartej broni.", "say": "Lufy w dół, kiedy się odwracasz."}, {"en": "Stop! Stop! Guns open!", "meaning": "Zatrzymanie awaryjne: przerwij strzelanie, otwórz broń, czekaj.", "say": "Stop! Stop! Broń otworzyć!"}], "quiz": [{"q": "Jak nosi się półautomat między stanowiskami?", "options": ["Zamknięty, na bezpieczniku", "Z otwartym zamkiem, lufa prosto w górę lub w dół", "Na pasie przez ramię", "Załadowany jednym nabojem"], "answer": 1, "why": "Broń nosi się otwartą, półautomaty z otwartym zamkiem, lufy prosto w górę lub w dół; pasy nośne są niedozwolone."}, {"q": "Broń klika, ale nie strzela. Co musi zrobić strzelec?", "options": ["Od razu ją otworzyć i zajrzeć", "Odwrócić się, by pokazać trenerowi", "Zostać na miejscu z bronią w stronę pola strzelania, nie otwierać jej ani nie dotykać bezpiecznika, aż sędzia sprawdzi", "Włączyć bezpiecznik i zawołać ponownie"], "answer": 2, "why": "Przepisy obu dyscyplin wymagają, by strzelec został na miejscu, aż sędzia sprawdzi broń; wcześniejsze otwarcie lub dotknięcie bezpiecznika to zero."}, {"q": "Ktoś krzyczy „Cease fire!”. Jakie jest pierwsze zadanie tłumacza?", "options": ["Głośno powtórzyć „Stop!” i sprawdzić, czy goście otwierają broń", "Wyjaśnić, dlaczego przerwano strzelanie", "Zapytać trenera, co się stało", "Poczekać, aż gość zapyta"], "answer": 0, "why": "Zatrzymanie awaryjne powtarza się natychmiast; wyjaśnienia przychodzą dopiero, gdy cała broń jest otwarta."}]}, {"id": "etiquette-on-the-stand", "minutes": 5, "title": "Przy stanowisku: cisza, odstęp, bezruch", "body": ["Strzelec na stanowisku potrzebuje pełnego skupienia, od załadowania do otwarcia broni po ostatnim strzale. Przepisy umieszczają miejsca oczekiwania blisko stanowiska, ale zastrzegają, że nie mogą one rozpraszać strzelca. W praktyce oznacza to: cicho albo wcale, żadnych gwałtownych ruchów w polu widzenia strzelca, broń otwarta, telefony wyciszone i w kieszeni. Przepisy nie wspominają o telefonach, ale na każdej strzelnicy oczekuje się tej uprzejmości.", "Stój za strzelcem, nigdy obok stanowiska ani przed nim. W Compak® Sporting rama ogranicznika kąta strzału (Firing Angle Limiter) ogranicza ruch broni każdego strzelca; w Parcours de Chasse – Sporting™ stanowiska na wielu strzelnicach mają klatkę. Wszyscy pozostali czekają za nią, poza każdą możliwą linią luf. W Compak® czekający strzelec stoi za stanowiskiem 1, a strzelec, który skończył, czeka, nie przeszkadzając następnemu.", "Przeszkadzanie strzelcowi ma skutki w przepisach. Jeśli sędzia widzi, że strzelcowi wyraźnie przeszkodzono, rzutek to No Bird i wyrzuca się go ponownie. Pozorowane strzelanie, gdy strzela członek grupy, jest zabronione. Strzela tylko ten, czyja jest kolej, i tylko do własnego rzutka.", "Dla ciebie ta lekcja jest praktyczna. Przestań mówić, gdy twój gość wchodzi na stanowisko, nawet w połowie zdania. Nie odpowiadaj na pytania, gdy broń jest zamknięta. Odezwij się dopiero, gdy broń jest otwarta: między rzutkami, między dubletami albo po stanowisku. Przegapiona rada kosztuje mniej niż dublet zepsuty twoim głosem."], "key_points": ["Cicho, bez ruchu, broń otwarta, telefony wyciszone, za strzelcem", "Stój za stanowiskiem, klatką lub F.A.L., nigdy obok ani przed", "Wyraźnie rozproszony strzelec dostaje No Bird", "Bez pozorowanego strzelania, gdy strzela ktoś inny", "Tłumacz: mów tylko, gdy broń jest otwarta"], "terms": ["quiet-on-stand", "shooting-stand", "conduct", "no-bird", "mock-shooting", "rotation"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch8-own-turn-live-animals", "label": "8 · Shoot only in turn; not at others' targets or animals"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}], "coach_says": [{"en": "Quiet behind, please — she’s on.", "meaning": "Strzelczyni jest na stanowisku; wszyscy przestają mówić.", "say": "Cisza z tyłu, proszę — ona strzela."}, {"en": "Wait until he’s opened his gun.", "meaning": "Nikt nie mówi ani się nie rusza, dopóki strzelec nie skończy i nie otworzy broni.", "say": "Poczekaj, aż otworzy broń."}, {"en": "Stand right behind me so you can see what I see.", "meaning": "Na treningu trener chce, żebyś stał dokładnie za nim, poza zasięgiem ruchu broni.", "say": "Stań tuż za mną, żebyś widział to, co ja."}, {"en": "Keep out of his line, please.", "meaning": "Jesteś w polu widzenia strzelca albo blisko toru luf; cofnij się.", "say": "Proszę zejść z jego linii."}], "quiz": [{"q": "Gdzie stoi tłumacz, gdy gość strzela?", "options": ["Obok strzelca, by widzieć jego twarz", "Przed stanowiskiem, by widzieć rzutek", "Za stanowiskiem, poza każdą linią luf", "Tam, gdzie nie widzi go sędzia"], "answer": 2, "why": "Wszyscy czekają za stanowiskiem lub klatką; miejsce obok strzelca jest najniebezpieczniejsze."}, {"q": "Głośna rozmowa telefoniczna za stanowiskiem wyraźnie przeszkadza strzelcowi w chwili strzału. Co może zdecydować sędzia?", "options": ["No Bird: rzutek wyrzuca się ponownie", "Zero dla strzelca", "Nic, telefonów nie ma w przepisach", "Żółta kartka dla strzelca"], "answer": 0, "why": "Jeśli sędzia widzi, że strzelcowi wyraźnie przeszkodzono, rzutek to No Bird."}, {"q": "Kiedy jest właściwy moment, by przekazać uwagę trenera?", "options": ["Gdy strzelec woła rzutek", "Między komendą a strzałem", "Gdy tylko trener skończy mówić", "Gdy broń jest otwarta: między rzutkami, dubletami albo po stanowisku"], "answer": 3, "why": "Rutyny strzelca nie wolno przerywać; mów dopiero, gdy broń jest otwarta."}]}, {"id": "etiquette-squad", "minutes": 5, "title": "Maniery w grupie", "body": ["Grupa (squad) to maksymalnie sześciu strzelców wylosowanych do wspólnego strzelania. Punktualność to pierwsza uprzejmość, a zarazem przepis. W Parcours de Chasse – Sporting™ nieobecnego strzelca wywołuje się trzy razy w ciągu jednej minuty, a niestrzelane rzutki liczy się jako zero. W Compak® Sporting strzelec, który przyjdzie po tym, jak pierwszy strzelec grupy zawołał rzutek, dostaje 25 zer w serii, a wcześniejsze zgłoszenie się do sędziego jest obowiązkowe.", "Kolejność ma znaczenie. W Sporting™ kolejność zmienia się na każdym stanowisku i przy dubletach; w Compak® strzelcy po każdej serii rzutków przesuwają się o jedno stanowisko w prawo. Nikt nie wchodzi na stanowisko, dopóki poprzedni strzelec go nie opuści. Wywołany strzelec jest gotowy od razu, z wystarczającą liczbą nabojów na całą serię.", "Sędzia decyduje sam. Członkowie grupy nie komentują, czy rzutek został trafiony, chyba że sędzia ich zapyta. Otwarta krytyka decyzji, ze strony strzelców lub widzów, jest traktowana jako próba wpływania na sędziego. Utrata panowania nad sobą, np. rzucenie bronią albo obrażanie kogokolwiek, trafia do jury i może oznaczać wykluczenie.", "Poza przepisami są zwyczaje. Strzelcy zwykle witają się na początku z sędzią i grupą, mówią „good shot” albo „well shot” („dobry strzał”) po dobrym stanowisku i „bad luck” („pech”) po pudle, ale nigdy nie komentują techniki obcej osoby. Słowo podziękowania dla operatora wyrzutni i sędziego na koniec, uścisk dłoni i spokój przy ogłaszaniu wyników są powszechne na wielu strzelnicach. Tłumacz te uprzejmości ciepło — one mają znaczenie."], "key_points": ["Bądź na czas i zgłoś się do sędziego; spóźnienie kosztuje zera", "Trzymaj się kolejności; wchodź tylko na wolne stanowisko", "Rozstrzyga tylko sędzia; bez komentarzy o trafieniach", "Utrata panowania nad sobą może oznaczać wykluczenie", "Zwyczaje: przywitaj się, „well shot”, podziękuj operatorowi i sędziemu"], "terms": ["squad", "rotation", "referee", "trapper", "conduct", "round"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-ready", "label": "9 · Be ready with a full round of equipment and ammunition"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch21-loss-of-control", "label": "21 · Loss of self-control"}], "coach_says": [{"en": "Number twelve — last call!", "meaning": "Sędzia wywołuje nieobecnego strzelca; jeśli nie przyjdzie, jego rzutki będą zerami.", "say": "Numer dwanaście — ostatnie wezwanie!"}, {"en": "You’re next — get ready.", "meaning": "Przygotuj się teraz: okulary, ochronniki, naboje, ale nie wchodź, dopóki stanowisko nie jest wolne.", "say": "Jesteś następny — przygotuj się."}, {"en": "Well shot!", "meaning": "Szczera pochwała po dobrym rzutku lub stanowisku.", "say": "Dobry strzał!"}, {"en": "Bad luck.", "meaning": "Przyjazne współczucie po pudle, a nie krytyka.", "say": "Pech."}, {"en": "Thanks, ref — thanks for pulling.", "meaning": "Podziękowanie sędziemu i operatorowi wyrzutni na koniec serii.", "say": "Dzięki, panie sędzio — dzięki za rzutki."}], "quiz": [{"q": "Compak® Sporting, strzelanie w grupach: twój gość przychodzi po tym, jak pierwszy strzelec jego grupy zawołał pierwszy rzutek. Co się dzieje?", "options": ["Dołącza na następnym stanowisku", "Dostaje 25 zer w tej serii", "Strzela ostatni bez kary", "Serię zaczyna się od nowa"], "answer": 1, "why": "W Compak® przy strzelaniu w grupach granicą jest pierwsza komenda grupy; po niej spóźniony strzelec ma 25 zer (możliwe jest odwołanie do jury)."}, {"q": "Kolega z grupy głośno mówi sędziemu, że myli się co do trafienia. Jak traktują to przepisy?", "options": ["Jako pomocną informację", "Jako formalny protest", "Jako próbę wpływania na sędziego", "Jako nic"], "answer": 2, "why": "Otwarta krytyka decyzji przez innych bez zgody sędziego to próba wpływania; protestować może tylko zainteresowany strzelec."}, {"q": "Jak w Parcours de Chasse – Sporting™ działa kolejność strzelania w grupie?", "options": ["Zmienia się na każdym stanowisku i przy dubletach", "Jest stała przez cały dzień", "Zawsze zaczyna najlepszy strzelec", "Sędzia wybiera dowolnie"], "answer": 0, "why": "Grupy po sześć osób są losowane, a kolejność zmienia się na każdym stanowisku, a także przy dubletach."}]}, {"id": "etiquette-protection-and-dress", "minutes": 5, "title": "Uszy, oczy i strój — także twój", "body": ["Ochronniki słuchu są obowiązkowe dla każdego na osi lub w jej pobliżu: strzelców, sędziów, obsługi i widzów. W Parcours de Chasse – Sporting™ okulary strzeleckie są obowiązkowe, bez wyjątków, dla strzelców, sędziów, obsługi i każdego, kto jest blisko stanowiska. W Compak® Sporting przepis o okularach wymienia zawodników, sędziów i obsługę. Strzelec, który wejdzie na stanowisko bez jednego z nich, jest traktowany jako nieobecny.", "To dotyczy także ciebie. Stojąc za stanowiskiem, jesteś „w pobliżu osi”. Ochronniki aktywne (elektroniczne) to najlepsze narzędzie tłumacza: tłumią huk strzału, ale przepuszczają głos, więc słyszysz trenera i sędziego. Przezroczyste lub barwione okulary strzeleckie chronią cię też przed spadającymi odpryskami rzutków; pomaga również czapka z daszkiem.", "Kodeks ubioru dotyczy bezpieczeństwa i szacunku. Żadnych krótkich szortów: tylko długie szorty typu bermudy, kończące się nie wyżej niż 5 cm nad kolanem. Koszula musi mieć co najmniej krótkie rękawy oraz kołnierzyk albo okrągły dekolt jak w T-shircie; kamizelka na gołe ciało jest niedozwolona. Sandały są zakazane, a w Compak® dotyczy to zarówno treningu, jak i zawodów. Numer startowy nosi się na plecach, między łopatkami a pasem, w pełni widoczny, niezłożony i nieprzycięty.", "Pierwsze naruszenie zasad ubioru lub numeru to ostrzeżenie; jeśli nie zostanie poprawione, następują kary, aż do wykluczenia przez jury. Podczas ceremonii członkowie drużyn noszą strój reprezentacji narodowej albo eleganckie spodnie i marynarkę, a wszyscy nagrodzeni muszą być obecni na dekoracji. Ubierz się jak spokojny profesjonalista: zakryte buty, neutralne ubranie, nic, co łopocze albo błyszczy w oczy strzelca."], "key_points": ["Ochronniki słuchu dla każdego w pobliżu osi, łącznie z widzami i tłumaczami", "Okulary: Sporting™ — każdy blisko stanowiska; Compak® — zawodnicy, sędziowie, obsługa", "Bez nich strzelec jest traktowany jako nieobecny", "Bermudy maks. 5 cm nad kolanem, rękawy, bez gołej klatki pod kamizelką, bez sandałów", "Numer na plecach, w pełni widoczny; pierwsze naruszenie = ostrzeżenie"], "terms": ["hearing-protection", "electronic-ear-muffs", "earplugs", "safety-glasses", "dress-code", "competitor-number", "shooting-vest", "prize-giving"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "sporting", "id": "ch17-ceremonies", "label": "17 · Dress at the opening and closing ceremonies"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch7-ceremonies", "label": "7 · Dress for opening and closing ceremonies"}], "coach_says": [{"en": "Eyes and ears on before you leave the clubhouse.", "meaning": "Załóż okulary i ochronniki słuchu, zanim wyjdziesz na osie.", "say": "Okulary i ochronniki założone, zanim wyjdziesz z klubu."}, {"en": "Where are your ears?", "meaning": "„Ears” = ochronniki słuchu, a nie same uszy.", "say": "Gdzie masz ochronniki?"}, {"en": "You can’t shoot in sandals here.", "meaning": "Ze względów bezpieczeństwa wymagane są zakryte buty.", "say": "Tutaj nie możesz strzelać w sandałach."}, {"en": "Your number’s folded — it has to be fully visible.", "meaning": "Numer startowy na plecach musi być cały i widoczny; inaczej ostrzeżenie.", "say": "Masz złożony numer — musi być w pełni widoczny."}], "quiz": [{"q": "Twój strzelec wchodzi na stanowisko bez okularów strzeleckich. Jak traktują go przepisy?", "options": ["Dostaje ostrzeżenie i może strzelać", "Może strzelać, jeśli trener się zgodzi", "Traci jeden rzutek", "Jest traktowany jako nieobecny"], "answer": 3, "why": "W obu dyscyplinach strzelec bez ochrony oczu lub słuchu na stanowisku jest traktowany jako nieobecny."}, {"q": "Jakie szorty są dozwolone?", "options": ["Dowolne szorty sportowe", "Szorty typu bermudy kończące się nie wyżej niż 5 cm nad kolanem", "Szorty tylko w Compak®", "Żadne szorty"], "answer": 1, "why": "Krótkie szorty są zakazane; długie szorty typu bermudy nie wyżej niż 5 cm nad kolanem są akceptowane."}, {"q": "Dlaczego ochronniki aktywne to dobry wybór dla tłumacza?", "options": ["Tłumią huk strzału, ale przepuszczają głos", "Tłumacze nie muszą ich nosić", "Całkowicie blokują wszystkie dźwięki", "Nagrywają trenera"], "answer": 0, "why": "Ochronniki słuchu są obowiązkowe w pobliżu osi, a ochronniki aktywne pozwalają słyszeć trenera i sędziego."}]}]}, {"id": "interpreter", "icon": "speech", "title": "Tłumacz przy pracy", "intro": "Tutaj łączy się wszystko, czego się nauczyłeś: co wolno, a czego nie wolno ci mówić, gdzie stać, słowa, które zwodzą nawet doświadczonych lingwistów, liczby i jednostki, słownictwo brytyjskie i amerykańskie, a na koniec cały trening, od pierwszego „dzień dobry” do podsumowania.", "lessons": [{"id": "interpreter-role", "minutes": 5, "title": "Twoja rola: trening a zawody", "body": ["Na treningu jesteś głosem trenera. Oddawaj każdą wskazówkę w całości, w kolejności i tonie trenera: stanowczo, gdy chodzi o bezpieczeństwo, ciepło, gdy to pochwała. Nie łagodź krytyki, nie dodawaj powodów, których trener nie podał, i nigdy nie dodawaj własnych porad technicznych, nawet jeśli znasz odpowiedź. Jeśli nie dosłyszałeś słowa, dopytaj, zanim przetłumaczysz.", "Zawody to co innego. Udzielanie zawodnikowi wskazówek trenerskich w trakcie zawodów jest zabronione zarówno w Parcours de Chasse – Sporting™, jak i w Compak® Sporting: strzelec dostaje żółtą kartkę, powtórzenia pociągają kolejne sankcje, a sędzia usuwa osobę udzielającą wskazówek z terenu strzelania. Sędzia też rozstrzyga sam: nikt w grupie nie komentuje trafień, a otwarta krytyka decyzji jest traktowana jako próba wpływania na sędziego.", "A teraz uczciwie. Przepisy FITASC w ogóle nie wspominają o tłumaczach. Czy przekazywanie rady trenera słowo w słowo w trakcie zawodów jest udzielaniem wskazówek i gdzie tłumacz może stać — przepisy tego nie mówią. To kwestia otwarta dla FITASC i nie powinieneś przedstawiać żadnej odpowiedzi jako oficjalnej.", "Dopóki FITASC nie odpowie, stosuj bezpieczną praktykę. Na zawodach tłumacz wyłącznie komunikację z sędzią, jury i organizatorem: komendy, decyzje, ostrzeżenia, protesty, godziny i grupy. Przed zawodami powiedz sędziemu lub organizatorowi, kim jesteś, i ustal, gdzie będziesz stać. Jeśli trener poprosi cię o przekazanie rady w trakcie zawodów, grzecznie odmów i wyjaśnij dlaczego. To chroni twojego strzelca przed żółtą kartką."], "key_points": ["Trening: głos trenera — w całości, tym samym tonem, nic od siebie", "Zawody: wskazówki trenerskie są zabronione (żółta kartka, trener usunięty)", "Kwestia otwarta dla FITASC: przepisy nie wspominają o tłumaczach", "Bezpieczna praktyka: na zawodach tłumacz tylko komunikację z sędzią, jury i organizatorem", "Przedstaw się sędziemu i ustal, gdzie stoisz"], "terms": ["coach", "referee", "jury", "yellow-card", "conduct", "interpreter", "coaching"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Tell her she’s lifting her head on the second bird.", "meaning": "Trening: przekaż to w całości, gdy broń jest otwarta.", "say": "Powiedz jej, że przy drugim rzutku podnosi głowę."}, {"en": "Quick — tell him to give the crosser more.", "meaning": "Zawody: to udzielanie wskazówek. Grzecznie odmów; nie przekazuj.", "say": "Szybko — powiedz mu, żeby dał więcej poprzecznemu."}, {"en": "Who are you with?", "meaning": "Sędzia pyta, dlaczego jesteś przy stanowisku; przedstaw siebie i swoją rolę.", "say": "Pan/Pani z kim?"}, {"en": "Ask the referee if I can still change chokes.", "meaning": "Pytanie proceduralne do sędziego: możesz je przetłumaczyć.", "say": "Zapytaj sędziego, czy mogę jeszcze zmienić czoki."}], "quiz": [{"q": "W trakcie serii na zawodach trener prosi cię, żebyś powiedział strzelcowi „more lead on the crosser”. Co robisz?", "options": ["Szybko szepczesz", "Tłumaczysz po następnym rzutku", "Grzecznie odmawiasz: byłoby to udzielanie wskazówek, które jest zabronione", "Prosisz sędziego, żeby to przekazał"], "answer": 2, "why": "Wskazówki trenerskie w trakcie zawodów są zabronione, a strzelec dostałby żółtą kartkę; przepisy nie mówią, czy przekazywanie rad jest dozwolone, więc działaj bezpiecznie."}, {"q": "Co przepisy FITASC mówią o tłumaczach?", "options": ["Mogą stać na stanowisku", "Potrzebują licencji sędziego", "Są traktowani jak trenerzy", "Nic: to kwestia otwarta"], "answer": 3, "why": "Przepisy nie wspominają o tłumaczach, więc ich dokładna pozycja na zawodach to kwestia otwarta dla FITASC."}, {"q": "Na treningu trener mówi: „Not bad, but you stopped the gun.” Jak tłumaczysz?", "options": ["W całości i tym samym tonem, obie części", "Tylko pochwałę, żeby gość był zadowolony", "Tylko błąd, żeby zaoszczędzić czas", "Dodajesz własną radę, jak to poprawić"], "answer": 0, "why": "Ani nie łagodzisz, ani nie wyolbrzymiasz: cały komunikat, tonem trenera, nic od siebie."}]}, {"id": "interpreter-position", "minutes": 5, "title": "Gdzie stać i kiedy mówić", "body": ["Na treningu stań tuż za strzelcem, obok trenera, za stanowiskiem lub klatką i poza każdą linią luf. Stamtąd widzisz to, co trener — rzutek i wyloty luf jednocześnie — a trener może mówić do ciebie cicho. Miejsce obok strzelca jest najniebezpieczniejsze; przed stanowiskiem w ogóle nie wchodzi w grę.", "Dobierz tryb do chwili. Tłumaczenie konsekutywne (trener mówi, robi pauzę, ty mówisz) pasuje do odprawy bezpieczeństwa, przejścia między stanowiskami i podsumowania. Tłumaczenie szeptane, chuchotage, pozwala trenerowi mówić dalej, podczas gdy ty szepczesz strzelcowi do ucha zza pleców; to męczące, więc stosuj oba tryby na zmianę. Ustal znak „pauza, tłumaczę”, np. uniesioną dłoń.", "Wyczucie czasu to wszystko. Rutyna strzelca trwa od zamknięcia broni do strzału. Mów tylko wtedy, gdy broń jest otwarta: między rzutkami, między dubletami, po stanowisku. Między dubletami powtarzaj krótkie wskazówki trenera — „more in front”, „head down”, „same again” — a długie wyjaśnienia zostaw na później. Pamiętaj o zegarze: w Parcours de Chasse – Sporting™ strzelec ma najwyżej 15 sekund między rzutkami lub dubletami, a w Compak® Sporting 10 sekund na komendę. Twoje słowa też zużywają ten czas.", "Na zawodach czekaj tam, gdzie czeka grupa, blisko stanowiska, ale nigdy nie rozpraszając strzelca: wyraźnie rozproszony strzelec dostaje No Bird i nikt nie chce być tego przyczyną. Na początku poznaj sygnały rąk trenera i przetłumacz je raz swoim gościom; potem będą cię potrzebować mniej i to dobry znak."], "key_points": ["Trening: tuż za strzelcem, obok trenera, poza linią luf", "Konsekutywnie przy odprawach i podsumowaniach; chuchotage na stanowisku; na zmianę", "Mów tylko, gdy broń jest otwarta", "Krótkie wskazówki między dubletami; limity czasu 15 s (Sporting™) i 10 s (Compak®)", "Zawody: czekaj z grupą, nigdy nie rozpraszaj"], "terms": ["quiet-on-stand", "shooting-stand", "coach", "firing-time", "no-bird", "chuchotage", "consecutive-interpreting", "hand-signals"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Stand right behind me.", "meaning": "Za trenerem i strzelcem, poza zasięgiem ruchu broni.", "say": "Stań tuż za mną."}, {"en": "Head on the stock — just whisper it to him, I’ll keep going.", "meaning": "Przejdź na chuchotage i przekaż wskazówkę cicho; trener nie zrobi pauzy.", "say": "Głowa na kolbie — po prostu mu to szepnij, ja mówię dalej."}, {"en": "When I do this — hands apart — it means more in front.", "meaning": "Trener wyjaśnia sygnał ręką; przetłumacz go raz dla grupy.", "say": "Kiedy robię tak — rozsuwam dłonie — to znaczy więcej przed rzutkiem."}, {"en": "Wait — let him finish the pair.", "meaning": "Wstrzymaj radę, aż broń znów będzie otwarta.", "say": "Czekaj — niech skończy dublet."}, {"en": "Sorry — did you say “under it” or “on it”?", "meaning": "Dopytaj, podając obie usłyszane możliwości; to szybsze niż „proszę powtórzyć”.", "say": "Przepraszam — powiedział pan „pod nim” czy „na nim”?"}], "quiz": [{"q": "Gdzie powinieneś stać podczas treningu na stanowisku Sporting™?", "options": ["Obok strzelca, żeby widzieć jego oczy", "Za strzelcem obok trenera, poza linią luf", "Przed klatką, twarzą do strzelca", "Obok wyrzutni"], "answer": 1, "why": "Zza pleców widzisz to, co trener, i jesteś bezpieczny; obok lub przed strzelcem jest niebezpiecznie."}, {"q": "Co to jest chuchotage?", "options": ["Tłumaczenie po pauzie mówcy", "Pisemne tłumaczenie przepisów", "Tłumaczenie sygnałów rąk", "Szeptane tłumaczenie symultaniczne do ucha słuchacza"], "answer": 3, "why": "Chuchotage to szeptane tłumaczenie symultaniczne; konsekutywne to tryb „pauza i mówienie”."}, {"q": "Ile czasu w Compak® Sporting ma strzelec na komendę od strzału do rzutka z poprzedniego stanowiska?", "options": ["10 sekund", "15 sekund", "30 sekund", "Bez limitu"], "answer": 0, "why": "Compak® daje najwyżej 10 sekund na komendę; Sporting™ pozwala na 15 sekund między rzutkami lub dubletami."}]}, {"id": "interpreter-false-friends", "minutes": 6, "title": "Fałszywi przyjaciele na strzelnicy", "body": ["Najgorsza pułapka to dym. „Smoked it!” trenera (albo „inked it”, „powdered it”) oznacza idealne trafienie: rzutek zniknął w chmurze. Ale w przepisach rzutek, z którego unosi się tylko pył lub dym, bez widocznego odprysku, to zero. „Chip”, mały widoczny odprysk, to trafienie. Tłumacz więc „smoked it” trenera jako „rozniósł go w pył”, a „only dust” sędziego jako „tylko pył — zero”.", "Słowa z punktacji nie są dosłowne. „Dead” i „kill” oznaczają trafienie („trafiony”, „jest”), nigdy „martwy” ani „zabójstwo”. „Lost” to pudło („chybiony”, „zero”), a nie „zgubiony”. „Dropped two” znaczy dwa rzutki chybione. „Straight” w „25 straight” to seria bez pudła, a nie „prosto”.", "Słowa o sprzęcie i miejscu. „Trap” to maszyna do wyrzucania (wyrzutnia), a nie „pułapka” (Trap to też dyscyplina olimpijska). „Stand” to jedno stanowisko, a nie „stoisko”; „peg” to oznaczone miejsce do strzelania, a nie kołek; „broken gun” to broń otwarta (złamana). „Pull!” to komenda, „pull-away” to metoda wyprzedzenia, „length of pull” to długość kolby. „Card” to karta wyników albo żółta lub czerwona kartka. „On report” znaczy na huk strzału. „Squad” to grupa FITASC licząca do sześciu osób; w ClayAway to także nazwa podgrupy w ramach wyjazdu.", "Inne języki dokładają pułapek. Francuskie „chandelle” to rzutek prawie pionowy (angielski teal), a nie angielski chandelle. Francuskie „en battue” i włoskie „in battuta” oznaczają zwierzynę pędzoną, a nie rzutek battue; portugalskie „batida” to rzutek battue, a „de batida” znaczy pędzona. Na trafienie francuski sędzia mówi „Bon”, włoski „Buono”; operator wyrzutni to „pulleur” albo „puller”. Włoskie przepisy używają różnych słów na grupę: batteria w Parcours de Chasse – Sporting™, squadra di tiro w Compak®."], "key_points": ["„Smoked it” trenera = idealne trafienie; „only dust or smoke” w przepisach = zero", "Dead / kill = trafiony; lost / dropped = chybiony; straight = seria bez pudła", "Trap = maszyna (wyrzutnia); stand = jedno stanowisko; peg = miejsce; broken gun = broń otwarta", "Pull, card, report i squad mają każde więcej niż jedno znaczenie", "Francuskie chandelle i „en battue” różnią się od angielskich słów"], "terms": ["one", "zero", "visible-piece", "trap", "shooting-stand", "squad", "call", "double-on-report", "pull-away", "length-of-pull", "yellow-card", "score-sheet", "battue", "teal", "false-friend", "peg", "smoked-it"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Smoked it!", "meaning": "Idealne trafienie, rzutek obrócił się w pył. Nie „tylko dym” z przepisów.", "say": "Rozniosłeś go w pył!"}, {"en": "Only dust — zero.", "meaning": "Sędzia: nie odpadł żaden widoczny kawałek, więc to pudło.", "say": "Tylko pył — zero."}, {"en": "Just a chip, but it’s dead.", "meaning": "Odpadł mały widoczny kawałek: liczy się jako trafienie.", "say": "Tylko odprysk, ale trafiony."}, {"en": "Break your gun.", "meaning": "Otwórz broń. Nie ma to nic wspólnego z jej łamaniem w sensie psucia.", "say": "Złam broń."}, {"en": "Step into the peg.", "meaning": "Stań na oznaczonym miejscu do strzelania.", "say": "Wejdź na swoje miejsce."}, {"en": "The second one’s on report.", "meaning": "Drugi rzutek zostanie zwolniony hukiem twojego pierwszego strzału.", "say": "Drugi jest na zawołanie."}], "quiz": [{"q": "Trener po strzale krzyczy „Smoked it!”. Co się stało?", "options": ["Unosił się tylko dym: zero", "Rzutek został zniszczony: idealne trafienie", "Nabój nie wypalił", "To był rzutek flash"], "answer": 1, "why": "W żargonie trenerów „smoked it” to idealne trafienie; w przepisach „only dust or smoke” to zero — przeciwne znaczenia."}, {"q": "Najlepszy polski odpowiednik „Lost.” sędziego?", "options": ["„Zgubiony”", "„Stracony czas”", "„Chybiony”", "„Rzutek zniknął”"], "answer": 2, "why": "„Lost” to słowo z punktacji oznaczające pudło (zero), a nie coś zgubionego."}, {"q": "Francuski gość mówi, że uwielbia strzelać „en battue”. Co ma na myśli?", "options": ["Zwierzynę pędzoną (ptaki pędzone nad strzelców)", "Płaski rzutek battue", "Rzutek wyrzucany w dublecie", "Rozbity rzutek"], "answer": 0, "why": "Francuskie „en battue” (włoskie „in battuta”) oznacza zwierzynę pędzoną; rzutek battue to osobna rzecz."}]}, {"id": "interpreter-numbers-and-units", "minutes": 5, "title": "Liczby i jednostki: stopy, jardy, kalibry, numery śrutu", "body": ["Brytyjscy i amerykańscy trenerzy mierzą wyprzedzenie w stopach: „give it three feet”, „a yard in front”, „half a bird”, „a barrel’s width”. To obraz, a nie pomiar. Tłumacz jednostkę tak, jak padła — „trzy stopy” — i nie przeliczaj jej w środku wskazówki: 0,9 m brzmi precyzyjnie i zmienia sens. Wyjaśnij raz, przed zajęciami, że stopy trenera to wrażenie, i zachowuj „more”, „less”, „double it” dokładnie tak, jak padły.", "Odległości do rzutków to inna sprawa. „It’s about thirty yards” można podać w metrach ze słowem „około” („około 27 metrów”), bo jard jest trochę krótszy od metra. Kierunki często podaje się według tarczy zegara: prosto przed sobą to 12, więc „pick it up at eleven o’clock” to lekko w lewo. Zachowaj zegar; nie zamieniaj go na stopnie.", "Kaliber działa odwrotnie. „12-bore” czy „12 gauge” to nie 12 mm; im mniejsza liczba, tym szersza lufa, więc kaliber 20 jest węższy. Przepisy FITASC obu dyscyplin dopuszczają najwyżej kaliber 12, z lufami co najmniej 66 cm (26 cali). Linia na kamizelce w Parcours de Chasse – Sporting™ to 25 cm, co brytyjscy strzelcy mogą nazwać „niecałe dziesięć cali”.", "Naboje: FITASC dopuszcza najwyżej 28 g ołowiu, blisko „one-ounce load” (jednej uncji), o której mówią Brytyjczycy, ze śrutem 2,0–2,5 mm. Numery śrutu nie są takie same w każdym kraju: nr 9 to prawie wszędzie około 2 mm, ale inne numery mogą się nieco różnić między systemem brytyjskim, amerykańskim i kontynentalnym. Gdy to ważne, pytaj o milimetry. Czoki mogą być podawane nazwami, ułamkami albo w „thou” (tysięcznych cala); tłumacz w systemie, którego użył trener."], "key_points": ["Wyprzedzenie w stopach to obraz: zachowaj jednostkę, nigdy nie przeliczaj w środku wskazówki", "Odległość do rzutka: jardy można podać jako „około … metrów”", "Tarcza zegara dla kierunków: 12 = prosto przed sobą", "12 gauge ≠ 12 mm; maks. kaliber FITASC 12, lufy ≥ 66 cm (26 cali)", "28 g ≈ jedna uncja; śrut 2,0–2,5 mm; numery śrutu różnią się w krajach — pytaj o mm"], "terms": ["lead", "gauge", "barrel-length", "shot-size", "load-weight", "choke", "cartridge", "clock-face"], "sources": [{"title": "Shotgun Life — Does barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}], "coach_says": [{"en": "Give it three feet.", "meaning": "Obraz wyprzedzenia, którego chce trener; widziany odstęp, a nie zmierzona odległość.", "say": "Daj mu trzy stopy."}, {"en": "Half that.", "meaning": "Użyj połowy poprzedniego wyprzedzenia.", "say": "Połowę tego."}, {"en": "Pick it up at eleven o’clock.", "meaning": "Szukaj rzutka lekko w lewo od kierunku na wprost.", "say": "Podejmij go na jedenastej."}, {"en": "It’s about forty yards out.", "meaning": "Rzutek jest w odległości około 37 metrów.", "say": "Jest jakieś czterdzieści jardów, czyli około 37 metrów."}, {"en": "Put a nine in the bottom barrel.", "meaning": "Załaduj nabój ze śrutem nr 9 (ok. 2 mm) do dolnej lufy, która zwykle strzela pierwsza.", "say": "Daj dziewiątkę do dolnej lufy."}], "quiz": [{"q": "Trener mówi „Give it four feet.” Jakie tłumaczenie jest najlepsze?", "options": ["„Wyprzedzenie — około 1,22 metra”", "„Wyprzedzenie — cztery stopy”", "„Strzelaj cztery metry dalej”", "„Cztery rzutki do przodu”"], "answer": 1, "why": "Wyprzedzenie w stopach to obraz; przeliczanie go w środku wskazówki dodaje fałszywej precyzji i zmienia komunikat."}, {"q": "Jaki jest największy kaliber dozwolony w FITASC Sporting™ i Compak®?", "options": ["10", "16", "20", "12"], "answer": 3, "why": "Przepisy obu dyscyplin dopuszczają najwyżej kaliber 12; mniejsza liczba oznacza szerszy przewód lufy, więc 10 jest niedozwolony."}, {"q": "Brytyjski gość pyta, czy jego naboje „one-ounce” są dozwolone na zawodach FITASC. Co wiesz?", "options": ["Limit FITASC to 28 g ołowiu (+2%), czyli mniej więcej jedna uncja", "FITASC dopuszcza 36 g", "Każda naważka jest dozwolona", "Dozwolone jest tylko 24 g"], "answer": 0, "why": "Przepisy dopuszczają do 28 g ołowiu z tolerancją +2%; jedna uncja to około 28 g. Średnica śrutu (2,0–2,5 mm) też musi się zgadzać."}]}, {"id": "interpreter-english-sporting-vs-fitasc", "minutes": 5, "title": "Słowa brytyjskie i amerykańskie a FITASC", "body": ["Wielu trenerów, z którymi będziesz pracować, wyrosło na angielskim Sportingu, którym w Anglii zarządza CPSA, albo na amerykańskim Sporting Clays pod egidą NSCA. Słowa są podobne do FITASC, ale przepisy za nimi już nie, a największa różnica dotyczy pozycji broni.", "W angielskim Sportingu i NSCA strzelec może zaczynać „gun up”, z bronią już złożoną, przed komendą. W Parcours de Chasse – Sporting™ jest to niedozwolone: kolba pozostaje poniżej linii na kamizelce, aż pojawi się rzutek, a do każdego rzutka strzela się z ramienia. Compak® Sporting jest pośrodku: pozycja broni przy komendzie jest dowolna. Tak więc „pre-mount this one” to na treningu ćwiczenie, ale na zawodach FITASC Sporting™ żółta kartka. Przetłumacz to, a jeśli gość wkrótce startuje, zapytaj trenera, czy wspomnieć o przepisie.", "Dublety mają różne nazwy. „True pair” (angielski i amerykański) to dublet symultaniczny FITASC. „Report pair” to dublet na zawołanie. „Following pair” to rafale FITASC. „Show pair” to pokaz rzutków przed strzelaniem. „Peg” to stanowisko strzeleckie, „station” to amerykańskie słowo na stanowisko, a „cage” to rama wokół niego.", "Język wyników też się różni. „HOA”, High Over All, to zwycięzca klasyfikacji generalnej. Klasy takie jak AA, A, B czy C to krajowe poziomy umiejętności według średnich, a nie kategorie wiekowe FITASC ani klasy trudności FITASC A, B i C, które oceniają tory lotu. Nawet w obrębie FITASC dublety się różnią: w Sporting™ oba naboje można oddać do jednego rzutka dubletu, w Compak® tylko jeden nabój na rzutek. Zawsze zadaj sobie pytanie, jakie przepisy ma na myśli mówiący."], "key_points": ["Gun up: dozwolone w angielskim Sportingu i NSCA, zabronione w FITASC Sporting™, dowolne w Compak®", "True pair = symultaniczny; report pair = na zawołanie; following pair = rafale", "Peg = miejsce do strzelania; station = stanowisko (USA); cage = rama ochronna", "HOA = zwycięzca generalny; klasy AA/A/B/C to nie kategorie FITASC ani klasy trudności", "Sporting™: oba strzały do jednego rzutka dozwolone; Compak®: jeden na rzutek"], "terms": ["ready-position", "gun-mount", "simultaneous-double", "double-on-report", "rafale-double", "target-presentation", "shooting-stand", "english-sporting", "nsca", "cpsa", "gun-up", "true-pair", "peg", "cage", "hoa", "shooter-class"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "CPSA — English Sporting", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Pre-mount this one for now.", "meaning": "Ćwiczenie treningowe: zacznij z bronią przy ramieniu. Niedozwolone na zawodach FITASC Sporting™.", "say": "Na razie ten złóż wcześniej."}, {"en": "It’s a true pair.", "meaning": "Oba rzutki wylatują w tej samej chwili (FITASC: dublet symultaniczny).", "say": "To dublet symultaniczny."}, {"en": "Following pair off the left trap.", "meaning": "Dwa rzutki z tej samej wyrzutni jeden po drugim (FITASC: rafale).", "say": "Rafale z lewej wyrzutni."}, {"en": "Let’s see a show pair.", "meaning": "Wyrzuć dublet raz, żeby wszyscy mogli go obejrzeć przed strzelaniem.", "say": "Zobaczmy pokaz dubletu."}, {"en": "He’s AA class and won HOA last year.", "meaning": "Wysoka krajowa klasa umiejętności i zwycięzca generalny zawodów.", "say": "Ma klasę AA i w zeszłym roku wygrał klasyfikację generalną (HOA)."}], "quiz": [{"q": "Brytyjski trener mówi „It’s a true pair.” Jaki to termin FITASC?", "options": ["Dublet na zawołanie", "Dublet rafale", "Dublet symultaniczny", "Prawidłowy dublet"], "answer": 2, "why": "„True pair” to angielska i amerykańska nazwa dwóch rzutków zwalnianych jednocześnie, czyli dubletu symultanicznego FITASC."}, {"q": "W której dyscyplinie start „gun up” jest NIEDOZWOLONY?", "options": ["Parcours de Chasse – Sporting™ (FITASC)", "Compak® Sporting", "Angielski Sporting (CPSA)", "Sporting Clays (NSCA)"], "answer": 0, "why": "FITASC Sporting™ wymaga, by kolba była poniżej linii na kamizelce, aż pojawi się rzutek; Compak® pozostawia pozycję broni dowolną."}, {"q": "Gość czyta w brytyjskich wynikach „Class C”. Co to jest?", "options": ["Kategoria wiekowa FITASC", "Krajowy poziom umiejętności według średnich", "Najtrudniejsza klasa torów lotu FITASC", "Rodzaj naboju"], "answer": 1, "why": "W wynikach brytyjskich i amerykańskich klasy to poziomy umiejętności; FITASC używa A/B/C tylko do trudności torów lotu, a zamiast tego ma kategorie wiekowe."}]}, {"id": "interpreter-session-script", "minutes": 8, "title": "Cały trening krok po kroku", "body": ["Przed zajęciami spotkaj się z trenerem na pięć minut. Ustalcie znak pauzy, zapytaj, jakiej metody uczy i jakich słów używa na wyprzedzenie, i poznaj jego sygnały rąk. Potem grupa zbiera się na odprawę bezpieczeństwa: tłumacz ją konsekutywnie, zdanie po zdaniu, stanowczo i w całości.", "Na pierwszym stanowisku trener zwykle zaczyna bez nabojów: sprawdzenie oka dominującego, potem postawa i pozycja gotowości. W kontekście FITASC broń zaczyna nisko, poniżej linii na kamizelce. Szepcz jego poprawki zza pleców, gdy ustawia stopy i ręce.", "Następnie odczytywanie rzutka. Trener go pokazuje, pyta, gdzie strzelec po raz pierwszy wyraźnie go widzi, i ustala punkt podjęcia rzutka, punkt wyjściowy lufy i punkt strzału. Trzymaj się tych trzech terminów przez cały dzień — „punkt podjęcia”, „punkt wyjściowy”, „punkt strzału” — żeby gość je przyswoił.", "Teraz strzelanie. Między rzutkami trener daje wskazówki z dwóch do pięciu słów; ty je powtarzasz, tej samej długości, w tej samej kolejności, gdy broń jest otwarta. Gdy pada diagnoza pudła — „behind”, „over the top”, „you stopped” — tłumacz diagnozę i poprawkę razem. Pochwałę tłumacz z tą samą energią.", "Potem dublety: który rzutek pierwszy, „eyes first, then the gun”, drugi strzał. Na koniec podsumowanie, znów konsekutywnie, w którym trener zbiera dwie–trzy najważniejsze rzeczy. Zapisz je w obu językach i daj gościowi notatkę. Poniżej jest prawdziwy ciąg zwrotów w kolejności, w jakiej je usłyszysz."], "key_points": ["Przed: znak pauzy, metoda, słowa na wyprzedzenie, sygnały rąk", "Odprawa bezpieczeństwa: konsekutywnie, stanowczo, w całości", "Te same trzy terminy przez cały dzień: podjęcie, punkt wyjściowy, punkt strzału", "Wskazówki między rzutkami: ta sama długość, broń otwarta; diagnoza + poprawka razem", "Podsumowanie: zapisz najważniejsze punkty w obu językach"], "terms": ["coach", "safety", "eye-dominance", "master-eye", "stance", "ready-position", "gun-mount", "pick-up-point", "hold-point", "break-point", "lead", "maintained-lead", "pull-away", "head-lift", "stopping-the-gun", "follow-through", "double-on-report", "crosser", "rabbit", "choke"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "NSSA-NSCA — Foot position (Ask the instructor)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}], "coach_says": [{"en": "Morning, everyone. Before we load anything, a quick safety briefing.", "meaning": "Początek zajęć; tłumacz odprawę konsekutywnie i w całości.", "say": "Dzień dobry wszystkim. Zanim cokolwiek załadujemy, krótka odprawa bezpieczeństwa."}, {"en": "Guns stay open until you’re on the stand and I say “load”.", "meaning": "Poza stanowiskiem żadnej zamkniętej broni; ładowanie tylko na słowo trenera.", "say": "Broń zostaje otwarta, dopóki nie staniesz na stanowisku i nie powiem „ładuj”."}, {"en": "Point at my nose, both eyes open. Now close your left eye.", "meaning": "Sprawdzenie oka dominującego: jeśli palec przeskoczy, prawe oko nie jest dominujące.", "say": "Wskaż mój nos, oboje oczu otwarte. Teraz zamknij lewe oko."}, {"en": "Front foot pointing at the break point, weight forward.", "meaning": "Postawa: ustaw stopy pod miejsce, gdzie rzutek zostanie rozbity; pochyl się lekko do przodu.", "say": "Przednia stopa na punkt strzału, ciężar do przodu."}, {"en": "Gun down, stock under the line. Mount only when you see it.", "meaning": "Pozycja gotowości FITASC: broń idzie w górę dopiero po pojawieniu się rzutka.", "say": "Broń w dół, kolba pod linią. Składaj się dopiero, gdy go zobaczysz."}, {"en": "Watch this one. Where do you first see it clearly?", "meaning": "Trener ustala punkt podjęcia rzutka.", "say": "Obejrzyj ten. Gdzie widzisz go wyraźnie po raz pierwszy?"}, {"en": "Hold your muzzles about halfway back, just under the line.", "meaning": "Punkt wyjściowy między podjęciem a punktem strzału, nieco poniżej toru lotu rzutka.", "say": "Trzymaj wyloty luf mniej więcej w połowie drogi z powrotem, tuż pod linią."}, {"en": "Behind it. Give it more.", "meaning": "Śrut przeszedł za rzutkiem: więcej wyprzedzenia.", "say": "Za nim. Daj więcej."}, {"en": "Call it three feet — that’s the picture you want.", "meaning": "Obraz wyprzedzenia, który masz zobaczyć przy strzale; stopy jako wrażenie, zachowaj jednostkę.", "say": "Powiedzmy trzy stopy — taki obraz masz widzieć."}, {"en": "Over the top. You lifted your head — stay in the gun.", "meaning": "Pudło górą, spowodowane oderwaniem policzka od kolby.", "say": "Nad nim. Podniosłeś głowę — zostań w broni."}, {"en": "Smoked it! Same again.", "meaning": "Idealne trafienie; powtórz dokładnie to, co zrobiłeś.", "say": "Rozniosłeś go w pył! Tak samo jeszcze raz."}, {"en": "You stopped the gun. Keep it moving through the shot.", "meaning": "Pudło za rzutkiem, bo ruch broni się zatrzymał; prowadź dalej.", "say": "Zatrzymałeś broń. Prowadź ją dalej przez strzał."}, {"en": "Next is a report pair: crosser first, then the rabbit.", "meaning": "Rabbit zostanie zwolniony hukiem strzału do rzutka poprzecznego.", "say": "Teraz dublet na zawołanie: najpierw poprzeczny, potem rabbit."}, {"en": "Eyes first, then the gun.", "meaning": "Przy drugim rzutku znajdź go oczami, zanim ruszysz wylotami luf.", "say": "Najpierw oczy, potem broń."}, {"en": "Keep the muzzles under the rabbit.", "meaning": "Zostań nisko przy toczącym się rzutku, żeby podskok nadal trafił w śrut.", "say": "Wyloty luf pod rabbitem."}, {"en": "Change to quarter and half for this stand.", "meaning": "Wkręć czoki 1/4 i 1/2 (otwarty, potem trochę ciaśniejszy).", "say": "Na tym stanowisku zmień na ćwierć i pół."}, {"en": "Let’s call it a day. Three things for tomorrow: feet, head, follow-through.", "meaning": "Koniec zajęć; trener podsumowuje — zapisz to dla gościa.", "say": "Na dziś kończymy. Trzy rzeczy na jutro: stopy, głowa, prowadzenie po strzale."}], "quiz": [{"q": "Kiedy i jak tłumaczy się odprawę bezpieczeństwa?", "options": ["Krótko, w chuchotage, gdy goście ładują", "Na początku, konsekutywnie, zdanie po zdaniu i w całości", "Tylko jeśli gość zapyta", "Po pierwszym stanowisku"], "answer": 1, "why": "Bezpieczeństwo jest na pierwszym miejscu i nie wolno go skracać; tryb konsekutywny pozwala, by dotarła każda zasada."}, {"q": "Trener mówi „Behind it. Give it more.” Jakie krótkie tłumaczenie między rzutkami jest najlepsze?", "options": ["„Trochę się spóźniłeś, spróbuj jeszcze raz, może szybciej”", "„Za nim. Więcej wyprzedzenia.”", "„Strzelaj wcześniej”", "„Dobrze, tak samo”"], "answer": 1, "why": "Odzwierciedlaj trenera: ta sama długość, ta sama kolejność, diagnoza plus poprawka, nic dodanego."}, {"q": "Dlaczego „pick-up point”, „hold point” i „break point” trzymać przez cały dzień w tych samych polskich słowach?", "options": ["Wymagają tego przepisy", "Żeby trener rozumiał po polsku", "Żeby gość przyswoił trzy stałe pojęcia i ich nie mylił", "To nie ma znaczenia"], "answer": 2, "why": "Spójne terminy budują w głowie gościa mapę stanowiska; zmienianie słów sprawia, że trzy pojęcia wyglądają jak sześć."}]}]}]};
